{index="30100",text="[憧憬的景色]米浴"},
{index="30101",text="[Q≠0]爱丽速子"},
{index="30102",text="[光芒四射地奔跑吧∞]神鹰"},
{index="30103",text="[待兼唐☆大冒险]待兼唐怀瑟"},
{index="30104",text="[《蔷薇辉石与梦之石》]荒漠英雄"},
{index="30105",text="[和我们一起，实现梦想吧！]特别周"},
{index="30106",text="[奔向理想的熏风]气槽"},
{index="30107",text="[小感伤预警♪]丸善斯基"},
{index="30108",text="[听凭骰运]中山庆典"},
{index="30109",text="[心怀超赞，终绽樱华]樱花千代王"},
{index="30110",text="[It's on the house.]曼城茶座"},
{index="30111",text="[帝王！王！王！！！]东海帝王"},
{index="30112",text="[TT Ignition！]双涡轮"},
{index="30113",text="[乌托邦设计师]琵琶晨光"},
{index="30114",text="[啊，华丽一族]第一红宝"},
{index="30115",text="[月下小恶魔♪]目白善信"},
{index="30116",text="[太阳小天使♪]大拓太阳神"},
{index="30117",text="[出来吧！恐怖的魔王军]新光风"},
{index="30118",text="[A Win Foreshadowed]克里斯象征"},
{index="30119",text="[夜风中飞舞的祈愿之花]目白雅丹"},
{index="30120",text="[燃至天际的祈祷之火]八重无敌"},
{index="30121",text="[U & Me]美浦波旁"},
{index="30122",text="[Danke schön]荣进闪耀"},
{index="30123",text="[GLAD TIDINGS]成田白仁"},
{index="30124",text="[Are you merry？]气槽"},
{index="30125",text="[从现在开始Don't stop！]樱花桂冠"},
{index="30126",text="[化为那无人知晓的风]山人西风"},
{index="30127",text="[平安喜乐寄于板羽球中]特别周"},
{index="30128",text="[难以捉摸的绝世佳人]东商变革"},
{index="30129",text="[源远流长冬夏青青]草上飞"},
{index="30130",text="[To you]喜嘉奇迹"},
{index="30131",text="[Marvelous☆巧克力盛宴]美丽周日"},
{index="30132",text="[变身！侍者形态！]微光飞驹"},
{index="30133",text="[让笑容绽放的黑巧]菱曙"},
{index="30134",text="[璨烂]目白拉莫娜"},
{index="30135",text="[高举熊熊燃烧的灯火]葛城荣主"},
{index="30136",text="[Unyielding resolve]克里斯象征"},
{index="30137",text="[迈向永恒的荣光]引领众人的始祖"},
{index="30138",text="[此刻请不要闭眼]优秀素质"},
{index="30139",text="[夜风掳心]目白麦昆"},
{index="30140",text="[比翼的华尔兹]东海帝王"},
{index="30141",text="[任务“为内心补充营养”]美浦波旁"},
{index="30142",text="[此刻，樱花烂漫]樱花桂冠"},
{index="30143",text="[终抵之处的风景]生野狄杜斯"},
{index="30145",text="[优俊少女们的欢乐日常]谷水琴蕾"},
{index="30146",text="[奔跑吧，奔跑吧，奔跑吧！！]小栗帽"},
{index="30147",text="[The frontier]森林宝袋"},
{index="30148",text="[Something Blue]大和赤骥"},
{index="30149",text="[与你定制的宝贵回忆]阿斯顿真弓"},
{index="30150",text="[点燃心火！！]伏特加"},
{index="30151",text="[Chill chill night*]重炮"},
{index="30152",text="[All'alba vincerò！]好歌剧"},
{index="30153",text="[暖月]黄金城"},
{index="30154",text="[宛如海鸥]目白善信"},
{index="30155",text="[#夏天 #全新的我]大拓太阳神"},
{index="30156",text="[坚持一生的奇迹]奇锐骏"},
{index="30157",text="[与你共赏的泡沫]曼城茶座"},
{index="30158",text="[在这火热的夏天飞奔吧！]森林宝袋"},
{index="30159",text="[Seaside Bloom]气槽"},
{index="30160",text="[黎明将至]佐岳鸣"},
{index="30161",text="[志向远大，展翅高飞]神鹰"},
{index="30162",text="[Precious☆Moments]爱慕织姬"},
{index="30163",text="[绽放于赛场的堇花]中山庆典"},
{index="30164",text="[犹如烈炎，心怀斗志]菱亚马逊"},
{index="30165",text="[福尔图娜的喝彩]谷水琴蕾"},
{index="30166",text="[高歌一曲YO-HO！]跳舞城"},
{index="30167",text="[Hello my clover]美妙姿势"},
{index="30168",text="[乘风破浪梦想远行]黄金船"},
{index="30169",text="[上天馈赠的微笑]鹤丸强志"},
{index="30170",text="[我的舞蹈轮回不息]帝王光辉"},
{index="30171",text="[啊啊，好开心，好开心啊！]春乌菈菈"},
{index="30172",text="[打飞出去吧——？！]目白麦昆"},
{index="30173",text="[大地与我们的合奏]万籁争鸣"},
{index="30174",text="[圣夜，为了有所改变]目白多伯"},
{index="30175",text="[融化寒冬的炽火]目白拉莫娜"},
{index="30176",text="[精心挑选，饱含心意]目白莱恩"},
{index="30177",text="[畅快满足的胜利微笑]维普露斯"},
{index="30178",text="[血脉初现]鸣声雷动"},
{index="30179",text="[百花之愿铭记于心]里见光钻"},
{index="30180",text="[今后也将延续！]不断缔造传奇的人们"},
{index="30181",text="[齐唱万众之歌]双涡轮"},
{index="30182",text="[衣锦还乡的雪白双翼]北幸樽前"},
{index="30183",text="[两抹小小的微笑]胜利奖券"},
{index="30184",text="[感谢感谢！樱吹雪！！]樱花进王"},
{index="30185",text="[冲吧，时尚达人！]北方飞翔"},
{index="30186",text="[Balliamo?]贵妇人"},
{index="30187",text="[唯有君临]黄金巨匠"},
{index="30188",text="[共创闪耀时刻]都留岐凉花"},
{index="30189",text="[属于两人的欢快舞步]北部玄驹"},
{index="30190",text="[充满激情的双人舞]鸣声雷动"}
}
p.text_data_88={
{index="10001",text="我叫特别周！<br>梦想是成为全国第一的优俊少女！<br>为了让妈妈她们开心……我会加油嘞！"},
{index="10002",text="我叫无声铃鹿，我很喜欢跑步。<br>领头的位置，我不会让给任何人。<br>嗯……就说这些吧。"},
{index="10003",text="呀吼，我是东海帝王！<br>务必关注会成为<br>零败三冠优俊少女的我哦！"},
{index="10004",text="Hi，我是丸善斯基！<br>异次元的跑法，你也是来看这个的吧？<br>哼哼♪要是被我迷得神魂颠倒的话……<br>我可不管哦♪"},
{index="10005",text="我叫小栗帽。<br>为了让故乡的大家开心，<br>我会全力以赴。请多指教。"},
{index="10006",text="哟，我是黄金船大人！<br>管它是在火焰里还是草地上！<br>即使是宇宙的尽头也无所谓！<br>我会追寻有趣的东西直到天涯海角☆"},
{index="10007",text="噢，我是伏特加！我的原则是时刻保持<br>身为最帅气优俊少女的形象！<br>逊爆了的事我绝对不会做，给我记好了！"},
{index="10008",text="Howdy！我是大树快车！<br>我要用马力全开的奔跑<br>带给大家快乐！"},
{index="10009",text="我是草上飞。<br>既然作为优俊少女出生，<br>就要在这条“道路”上钻研到底。呵呵♪"},
{index="10010",text="我是目白麦昆。我的家族，<br>目白家的夙愿——称霸“天王奖”<br>就用我的双腿来实现吧。"},
{index="10011",text="奔跑于赛道的赤红怪鸟！<br>神鹰登！场！啦！<br>以世界为目标，奋勇前进！"},
{index="10012",text="哈——哈哈哈！我是最强大<br>最美丽的“霸王”——好歌剧！<br>让传说就此开演吧！"},
{index="10013",text="我是鲁道夫象征，是站在所有优俊少女<br>的顶点为她们引路的“皇帝”。<br>志同道合的同志们，一起勇往直前吧。"},
{index="10014",text="呀吼，我是青云天空哦——<br>适度随意且悠闲地活下去吧——<br>放长线才能钓大鱼，对吧？"},
{index="10015",text="我叫……米浴……那、那个？<br>米浴，会让大家陷入不幸……很没用……<br>但是……我、我会加油改变的！"},
{index="10016",text="我我我！我的梦想是成为德比优俊少女！<br>还有……啊！名字！<br>我叫胜利奖券！请多指教！"},
{index="10017",text="我是黄金城……事先说好，<br>绝对不许把我当成换装娃娃。<br>别看我的外表，靠我的跑步表现来评价我吧。"},
{index="10018",text="你好！我是樱花进王！<br>如你所见，我还是一名优秀的班长！<br>为了成为大家的榜样，现在！前进吧！"},
{index="10019",text="呵呵，我是超级溪流哦～<br>为了让大家露出笑容，<br>我会非——常努力的。交给我吧♪"},
{index="10020",text="我是春乌菈菈！最喜欢胡萝卜，<br>跑步也超——级喜欢♪<br>为了拿到第1名，我会努力加油！"},
{index="10021",text="您好，我是特雷森学园的理事长秘书<br>骏川手纲。为了让各位过上<br>更舒适的学园生活，我会全力以赴♪"},
{index="10022",text="你好，我是桐生院葵，是特雷森学园的<br>新人训练员。我只是一个新手，<br>但是我会为优俊少女竭尽全力的！"},
{index="10023",text="你好，我叫大和赤骥！<br>我会竭尽全力……啊，是你啊。哼！<br>我的目标只有第1名，除此之外什么都不要！"},
{index="10024",text="这里有很多神气十足的家伙啊……<br>嘿嘿，让菱亚姐来会会你们！来单挑吧！"},
{index="10025",text="我是气槽。只要坚定信念，<br>理想定会发芽。为了证明这一点，<br>我会作为“女帝”为大家指明方向。"},
{index="10026",text="辛苦喽！我是小数码！<br>我是光彩夺目的优俊少女们的粉丝！<br>每天都好幸福！能成为阿宅真是太幸运了♪"},
{index="10027",text="咱叫玉藻十字！咱呀，要在比赛中<br>获胜获胜再获胜，成为大明星！<br>别因为咱个子小，就小看咱！"},
{index="10028",text="您好，我是美妙姿势！<br>我想尽可能多地创造美好回忆。<br>首先我想了解一下好吃的拉面店♪"},
{index="10029",text="我是琵琶晨光。<br>我的目的，是创造无懈可击的胜利公式。<br>还有，我的头围在正常范围内！"},
{index="10030",text="诶嘿嘿，我是重炮亲哦☆<br>特别喜欢令人兴奋的事<br>和刺激的事，请多指教！"},
{index="10031",text="我是……曼城茶座。<br>我想追上……一个朋友……<br>她总是跑在我前面……看，就在那里……"},
{index="10032",text="我的名字是美浦波旁。<br>当前设置的目标是成为三冠优俊少女。<br>跑法等信息请参考其他数据。"},
{index="10033",text="我叫目白莱恩！<br>锻炼身体就能精神饱满！锻炼肌肉<br>就能健康强壮！鼓足力气加油吧！"},
{index="10034",text="我、我叫雪之美人！<br>我的梦想是成为在闪耀之星系列赛里获得成功<br>的城市少女！呼……成功说出来了……"},
{index="10035",text="哈喽哈喽！我是艾尼风神！<br>为了让家人们开心，不管是比赛还是打工，<br>我都会加油的！"},
{index="10036",text="优俊少女究竟可以快到什么程度……<br>你对此也不感兴趣吗？如果有兴趣的话……<br>就来成为我——爱丽速子的小白鼠吧！"},
{index="10037",text="我叫空中神宫。任何比赛中<br>数据都很关键。模拟实验没有异常，<br>让我来扳倒你吧，用我的逻辑。"},
{index="10038",text="我是荣进闪耀。为了保护优俊少女的传统，<br>我会一直奔跑下去。不管是什么样的比赛，<br>我都会严格按照计划进行。"},
{index="10039",text="我是醒目飞鹰！叫我飞鹰子吧！<br>我的梦想是成为优俊偶像！<br>随时都可以找我要签名哦☆"},
{index="10040",text="我是成田大进，没了。我只想<br>包揽胜利，让那些看不起我的人<br>好好看看……不要管我。"},
{index="10041",text="你好，我是西野花。<br>我想成为值得大家信赖的、<br>优秀的优俊少女大姐姐！"},
{index="10042",text="正义的英雄，微光飞驹登场！<br>我的奔跑可以击败一切强敌<br>让大家的脸上露出笑容！厉害吧！"},
{index="10043",text="嗨嗨，我是美丽周日！<br>我要将marvelous的心情传递给全世界！<br>大家一起来，marvelous！"},
{index="10044",text="你好！我叫待兼福来！<br>坚信白兴大人的神谕，等待福气到来……<br>同时也在夜以继日地钻研占卜！"},
{index="10045",text="我叫名、名将怒涛！那个、那个，<br>我想变得更自信，<br>我会竭尽船力……说、说错了！"},
{index="10046",text="你好……那个，我是目白多伯。<br>我也是目白家的优俊少女，<br>所以要跑出不负家族之名的成绩……我是这么想的。"},
{index="10047",text="啊……我是优秀素质。啊哈哈，<br>“优秀的素质”这个名字果然名过其实了吧……<br>哎呀，慢慢来吧？"},
{index="10048",text="哦——呵呵！我的名字是帝王光辉！<br>作为一流的优俊少女，我会创造最优秀的<br>成绩！这也是为了向全世界展现我的才能！"},
{index="10049",text="我是负责让大家开心的漆黑表演者<br>富士奇石！我一定会用最棒的“奇迹”<br>让你露出笑容！"},
{index="10050",text="东商变革是变身前的名字！<br>我是天才魔法少女小革！<br>这就是魔法哦！嘿！（咚）"},
{index="10051",text="我是双涡轮！<br>涡轮要拿第1，一定要拿第1！<br>冲吧，开足涡轮！"},
{index="10052",text="耶——我是大拓太阳神！<br>我会让比赛嗨翻天，所以<br>麻烦你们提供史上最棒的欢呼声☆"},
{index="10053",text="我叫生野狄杜斯。<br>管理工作就交给我吧。<br>我会用钢铁般的意志实行严格的管理方针。"},
{index="10054",text="我是目白善信！你好呀～<br>遇到难题的时候，随时都可以找我聊天哦。<br>不要有顾忌，放开说♪"},
{index="10055",text="我是北部玄驹！<br>我的目标是让比赛像庆典一样<br>使大家热情高涨，为此我要全力奔跑！"},
{index="10056",text="我叫里见光钻。<br>这个世界上不存在什么命中注定。<br>我要用奔跑，让未来绽放光芒！"},
{index="10057",text="呀吼，我是待兼唐怀瑟哦。<br>为了不输给大家，我得努力<br>训练……诶，今天休息？！"},
{index="10058",text="我是八重无敌。作为金刚八重垣流<br>的门生，我渴望和强者交手。<br>来吧，一决胜负！"},
{index="10059",text="我叫荒漠英雄。那个……虽然我<br>并不强大，但是我非常向往英雄传说……<br>总有一天，我要在比赛中书写自己的故事！"},
{index="10060",text="我是㭴本理子。<br>保证优俊少女身心健康是训练员的职责，<br>处理工作时当然要时刻紧绷神经。"},
{index="10061",text="呵——呵呵呵！我是采珠！<br>你知道吗？这个世界充满了可能。<br>我一定会证明给你看！"},
{index="10062",text="我、我是樱花千代王！<br>为了和我憧憬的那个人一起站上梦想的舞台，<br>我要让这份信念……开花结果！"},
{index="10063",text="哦——呵呵！我是川上公主……<br>没错，我就是高贵优雅的公主中的公主！<br>比赛中我也会以可爱动人的身姿飞驰到底！"},
{index="10064",text="buono～buono♪我是菱曙☆<br>无论是料理还是赛跑，我都会<br>为大家献上大大——的爱！请多关照♪"},
{index="10065",text="嘿！我叫青竹回忆！<br>赌上魔鬼纪律委员长的名号，<br>我会努力奔跑的！"},
{index="10066",text="嗷呜！我是新光风！<br>害怕了吗？你肯定害怕了，老实承认吧！<br>喂！别无视我！我咬！"},
{index="10067",text="我是中山庆典。<br>不温不火的比赛可没法让我感受到刺激啊。<br>我说……让我更兴奋吧！"},
{index="10068",text="你说啥呢！我是稻荷一！<br>如你所见，我是土生土长的江户人！<br>我要成为最厉害的优俊少女！"},
{index="10069",text="我叫目白雅丹。<br>即使这双腿如此脆弱，我也要骄傲地跑下去……<br>哪怕转瞬即逝，我也要在赛场上绽放光芒"},
{index="10070",text="我是岛川乔丹。我的梦想是……<br>我可不想聊这种严肃话题哦☆<br>总之你先看看我的美甲！很漂亮吧？"},
{index="10071",text="我是天狼星象征！<br>比赛不需要讲什么大道理，静静地看着吧。<br>我要征服世界，向所有人证明我才是“最强”。"},
{index="10072",text="我是成田白仁。<br>没什么特别想说的。<br>我只需要把所有人都远远甩在后面，<br>夺得比赛的胜利。"},
{index="10073",text="我是Curren，真机伶！<br>让世界充满“可爱”吧☆<br>不许东张西望哦，你只要看着机伶就好♪"},
{index="10074",text="我是技艺高超的针灸师（的徒弟），安心泽刺刺美。<br>只要让我扎一下就能提升力量！<br>哇哦，安～心☆"},
{index="10075",text="我是爱慕织姬……我可以走了吗？<br>我要更努力地训练、赢得比赛。<br>因为我必须成为一等星。"},
{index="10076",text="哎呀？是该做自我介绍了吗？<br>呵呵，我叫目白光明。<br>身为目白家的一员，我会努力的～"},
{index="10077",text="你好，我是成田路！<br>为了不辜负大家的支持和期待，<br>我会全力以赴的！"},
{index="10078",text="有一种风只存在于赛场之上。<br>那是轻盈、澄澈的……随心所欲的顺风哦。<br>我是千明代表，请多关照。"},
{index="10079",text="我是第一红宝。<br>登峰造极乃我们一族的责任。<br>为履行己身之责，我定将勇往直前"},
{index="10080",text="我是……喜嘉奇迹。<br>为了回报赐予我生命的大家……<br>我一定会创造奇迹"},
{index="10081",text="我是鹤丸强志！总之我会向着憧憬的<br>“三冠优俊少女”全力——咳咳！<br>只、只是呛到了而已！我很好不用担心！"},
{index="10082",text="我是克里斯象征，象征家对我有恩。<br>作为其中一员，不论是自己立下的目标<br>还是被赋予的任务，我都会将其完成"},
{index="10083",text="我是明亮光晕，主要负责活动策划工作。<br>让我为舞台上闪闪发光的各位……<br>稍尽绵薄之力吧"},
{index="10084",text="我是谷水琴蕾！我追求的是理想的“我”。<br>我无意伪装这个暂居的自我。尽情破坏，<br>踹破一切——然后向着终焉前进吧！"},
{index="10085",text="我是樱花桂冠。我的目标是世界，是凯旋门奖！<br>呵呵，虽然现在这还只是个“梦”……<br>但我将来一定会让它实现的"},
{index="10086",text="我是山人西风……<br>我的目标，是风……<br>我想要成为快过一切、自由驰骋的风"},
{index="10087",text="我是小真——阿斯顿真弓。<br>总有一天我会成为世界的吉祥物。<br>请用你的双眼一直注视着我哦"},
{index="10088",text="想要了解我？那就请移步草地吧。<br>目白拉莫娜……我的一切都在那里。"},
{index="10089",text="我是森林宝袋。<br>想跑的话，我可以奉陪哦。<br>不过，“最强”的宝座可不会让给你。"},
{index="10090",text="我是从北方港口飞来的纸翼候鸟♪<br>苫小牧的地方偶像——北幸樽前嘞♪<br>唔……是不是该想个更别致的说法呢"},
{index="10091",text="我是葛城荣主，请多指教！<br>有梦想的话就别畏畏缩缩的啊。<br>我会为你打破那些狭隘的障壁！"},
{index="10092",text="Rickey☆Lucky☆大吉大利☆<br>我是小林历奇！我会用风水的力量<br>为你也带来幸福的哦♪"},
{index="10093",text="我是奇锐骏。<br>虽然性格悠哉，但我可是很擅长<br>踏踏实实努力哦。请多指教啦。"},
{index="10094",text="我是佐岳鸣！分析欧洲赛事的话就交给我吧。<br>让我们一起称霸“凯旋门奖”，<br>实现这前无古人的梦想吧！"},
{index="10095",text="来吧，踏上令人心潮澎湃的旅途！享受与伙伴<br>共舞的日子！Everyone！想要追寻梦想的<br>家伙们——全都登上我跳舞城的船吧！"},
{index="10097",text="我是极峰。<br>总有一天我会打破一切成为女王，<br>在那之前我决不会气馁。"},
{index="10098",text="啊，我深爱的音乐家们！<br>今天也与我万籁争鸣一同，<br>让彼此的旋律交织相融吧！"},
{index="10099",text="我是维普露斯哦！总有一天，我一定要在<br>闪闪发光的迪拜跑一场有名人风范的比赛♪<br>我们一起去吧！毕竟我都决定好啦♪"},
{index="10100",text="我想要的——只有“最强”的称号哦！<br>我要成为铭刻在人们记忆中的优俊少女！<br>为此我所需的……没错，就是自我包装哦！"},
{index="10101",text="我是鸣声雷动……<br>我的目标并非胜利，而是在其前方的“最强”。<br>就是这样……"},
{index="10102",text="嗯，我是北方飞翔！服装、妆容、饰品，<br>还有坚持不懈的努力——请见证由这一切<br>雕琢而成的、属于我的闪耀光芒吧！"},
{index="10103",text="无礼之徒，还不速速跪下——<br>黄金巨匠的称霸之道，<br>你只管俯首膜拜便是。"},
{index="10104",text="我是都留岐凉花。<br>平时主要从事各种内容的制作。<br>我会给各位带来最棒的感动。"},
{index="10113",text="过程也好，道理也罢，都毫无意义。<br>胜者即是正义，不是吗？<br>我贵妇人定将让一切都屈服于我。"},
{index="20001",text="向阳而跑，直至日落西山。<br>这便是特雷森学园学生的青春。<br><br>“嗯，有这些应该够了吧？”<br><br>她喃喃自语，望着<br>运动饮料和数个盐饭团。<br>现在就差……<br><br>“呼……呼……小特，快点。”<br><br>“铃、铃鹿……我、跑不动了～”<br><br>“呵呵，终于到了呀。这下人都到齐了。”<br><br>她瞥了一眼已过门禁时间的时钟的分针，<br>朝宿舍玄关走了过去。<br>对超过门禁时间才回这件事做出提醒……<br>然后，大力犒劳努力拼搏的二人。<br><br>这便是特雷森学园宿舍长的青春。"},
{index="20002",text="“这里应该使用这个算式，所以……”<br><br>她正在奋笔疾书，<br>似乎没有注意到自己在自言自语。<br>笔记本上写满了整整齐齐的算式，<br>身旁堆叠着常用的参考书。<br>不经意间，她回想起自己说过的<br>关于母亲的话。<br><br>“妈妈是什么都会的优秀优俊少女，<br>是我的憧憬。”<br><br>曾说出过这些话语的她，现在如同追赶母亲一般，<br>默默地舞动着笔尖。<br>为了不打扰如此努力的她，<br>我选择了悄悄离开。"},
{index="20003",text="在阳光刺目的晴空之下，<br>大家都在呼喊着她的名字，称赞着她的胜利。<br><br>“哈哈，真是心情舒畅。<br>好好看着吧！<br>下一场比赛我依旧会马力全开！”<br><br>视线所及之处全都响彻着震耳欲聋的欢呼声，<br>但她的思绪却早已飘向远方，<br>落到了那在前方奔跑的怪物身上——"},
{index="20004",text="“只剩下这个装饰了。<br>大家，打起精神加油干！”<br><br>粉丝答谢会的筹备工作进行得非常顺利！<br>这是当然——负责指挥的，<br>可是以女帝之名著称的她。<br><br>“咦，‘小金船特制炒面贩卖会’？<br>之前是这个横幅吗？”<br><br>“啊……？”<br><br>距离女帝的雷霆怒火击中始作俑者，<br>还有3秒！"},
{index="20005",text="追☆击　追☆击<br>( ﾟ∀ﾟ)o彡゜( ﾟ∀ﾟ)o彡゜<br><br>U☆游击来咯！（什么什么？）<br>M☆magazine全力发射！（耶耶！）<br>A☆用assault♪（击倒对手！）<br><br>追☆击　追☆击<br>( ﾟ∀ﾟ)o彡゜( ﾟ∀ﾟ)o彡゜<br><br><br>“耶！悠露喵好可爱！<br>诶？！啊，等、等一下，她、她看我——”<br><br><br>※请稍等片刻※<br><br><br><br><br><br><br>“呼，灵魂终于回来了。<br>在演唱会中灵魂出窍，我也太不小心了……<br>好！打起精神继续吧！”<br><br><br>※返回第一行×∞"},
{index="20006",text="“呼……每天必做的训练完成了，<br>总觉得腿部——还有余力呢。<br><br>理论上，距离体能达到上限，还剩……唔。<br>腿举450千克大概还能做12次吧。<br>这样的话……”<br><br>眼镜上闪过一道光，<br>镜片下的金色正在静静燃烧。<br><br>“只能，验证一下了……对吧！”<br><br>她双眉紧皱，干劲十足。<br>摇晃的尾巴显得十分开心。"},
{index="20007",text="闪闪发光、阳光明媚的一天！<br><br>“是成熟女孩聊天的好日子☆”<br><br>从便利店买来的略带苦味的零食和<br>刊登了新款美妆的时尚杂志♪<br><br>“啊，白羊座的爱情运特别好诶☆”<br><br>“buono！还有美容甜点特辑♪”<br><br>“呀！我要一个不落地全都看一遍！”<br><br>总是兴奋不已！女孩之间的聊天！<br>防晒措施也非常完美☆<br>因为因为，这可是成熟大人的滴水不漏♪<br>少女们的聊天，还在继续。<br><br>小心漏听上课铃哦！"},
{index="20008",text="<br>……，……。……？<br><br>“嗯……没错。<br>就是说……我很喜欢……所以画了。”<br><br>……，……。<br>……，……，……？<br><br>“嘿嘿……猜错了……正确答案是……云……”<br><br><br>这是下雨天和“朋友”之间的悄悄话。"},
{index="20009",text=".COMMAND；Squat<br><br>START：0830……<br>　WGT　100kg+20kg<br>　SET　10×3<br>……END：<br><br>正在笔记本上奋笔疾书的笔尖停住了。<br><br>“哈……哈……已确认到出汗和体温上升。<br>但是，下肢的负荷依然不足。<br>再来一组……加油！加油——”<br><br>随着脑海中浮现的朋友的声音，<br>她合上了笔记本。"},
{index="20010",text="滴滴——<br>宣告得分的哨声响起。<br>球场上的主角取得了胜利。<br><br>“谢谢！大家表现得很棒！<br>听到大家的加油声，我的肌肉都兴奋起来了！”<br><br>闪闪发光的是太阳？<br>还是她的笑容？<br><br>被击中的是篮筐？<br>还是观众们的心？<br><br>答案是……没错，都是正确答案。"},
{index="20011",text="“快、快看！上面写着thank you！<br>笑眯眯的涂鸦也……很阔爱！”<br><br>“哼哼，雪之的笑容也不落下风哦。”<br><br>十分向往的时尚咖啡厅。<br>为了成为大都市里的时髦少女，<br>踏入了一个全新的世界——少女因此闪闪发光。<br><br>“好、好嘞！接下来是发到社交软件上……”<br><br>“你也玩社交软件啊。<br>机会难得，我可以关注你吗？”<br><br>“哇！当当当当然可以！”"},
{index="20012",text="20XX.XX.XX<br>某位热爱研究的优俊少女的独白。<br><br>“我在渴望着，<br>渴望着足以震颤神经突触的兴奋。”<br><br>地点是教学楼3楼的某间空教室。<br>用厚厚的窗帘与外界隔绝的<br>阴暗处——也就是所谓的实验室。<br><br>为了超越极限，<br>到达事件视界。<br><br>“去有资格为其献身的小白鼠那里……<br>看看新药的效果吧。”<br><br>为了满足那无穷无尽的好奇心。"},
{index="20013",text="哔——<br><br>闹铃响了一声后，陷入了沉默。<br>从斜光的角度来看，天气应该与预测结果一致。<br><br>“呼……按时起床。用216秒整理头发，<br>310秒换好衣服……”<br><br>“呼啊……现在开始安可……”<br><br>洋溢着幸福的睡脸上露出了微笑。<br>目前超时约5.2秒。<br><br>但是——这是令人快乐的误差。<br><br>“闪耀也要练习，偶像声援……<br>一定要好好练习……哦……”<br><br>“嗯？”"},
{index="20014",text="“1、2……呼……”<br><br>远离喧嚣的游泳池边。<br>认真做完拉伸运动后，<br>终于等到了其他学生陆续准备离开的时刻。<br><br>这下可以安静地游——<br><br>“好疼！腿抽筋了！<br>救、救命！大进！”<br><br>“啧……都、说、了！<br>先做好伸展运动啊！”<br><br>嘴上虽然这么说，但少女还是站了起来。<br>看来暂时还没办法进入泳池呢。"},
{index="20015",text="新·marvelous计划！<br>　　　　　　　起草人：美丽周日<br><br>【简介】由marvelous提供，为marvelous而存在的、<br>　　　　marvelous的……计划！<br>【目标】向世界传递marvelous的心情！<br>【活动期间】现在！立刻！接下来马上！<br><br><br>“综上所述☆　即刻开始★”<br><br>写有重要事项的企划书，在空中飞舞。<br>但是现在不是在乎这些的时候，因为——<br>世界正在等待……marvelous！<br><br>※散落在地的文件之后都收拾干净了。"},
{index="20016",text="即使太阳西升东落！<br>运势也会由凶转吉……不，大吉。<br>不不不！再加把劲变成大大吉吧！<br><br>“请降临！开运必胜白兴大人！”<br><br>她拿出的是，<br>“特制☆招福白兴大人专用表”<br>可不能小看它！这连比赛运<br>都能看得一清二楚哦。（制作者曰）<br><br>“比赛当天……天、气、有、时、晴、朗”<br><br>“阴、天……之、后……有、雨……<br>啊，这是占卜？不会吧？”"},
{index="20017",text="“幸福要靠自己把握！”<br>被这句话打动的少女——<br><br>现在有点后悔了！<br><br>“好、好痛苦……大家的、视线……<br>呜呜……真的要，这样绕教学楼一周吗？”<br><br>“没错！这都是为了招来幸福啊！<br>奋斗吧！开运吧！”<br><br>“幸福……奋、奋斗吧……<br>开、开运吧！”<br><br>努力一定会有回报。因为——<br><br>幸福，其实就在我们身边。<br>只要愿意努力，所有人都可以看到它……大概！"},
{index="20018",text="说这是憧憬，就太过亲近。<br>说这是目标，又过于遥远。<br><br>即使如此，仍然想要追赶。<br>跑在她前面的那两道身影。<br><br><br>“好，先来一圈，<br>争取赶上莱恩的用时。”<br><br><br>视线的前方是闪闪发光的草地。<br>也有人内心满怀憧憬，望着她的侧脸。"},
{index="20019",text="人迹寥寥的泳池。<br>自由自在地游泳的身影，不是孤狼而是孤鱼。<br><br>“没有哪里比白天里的泳池更棒了。<br>好，再来一圈吧，顺带放松一下身体。”<br><br>她假装没看到泡肿的指尖，<br>但从额头流下的汗水，证明了她的努力。"},
{index="20020",text="一流，绝非一日炼成。<br>一流，需要闻一知十。<br>一流，以第一为目标。<br><br>“不愧是我！不光是训练，<br>连写心得也是一流水平！”<br><br>“哦——呵呵呵！<br>如果想达到我的水平，<br>就一定要每天坚持……<br>这一流的三段笑！”<br><br>“是！一流加一流再加一流，<br>就变成了三流——”<br><br>“没错没错……等等。”"},
{index="20021",text="“辛苦了！”<br><br>某天，在训练场上，<br>我向同期的训练员打了声招呼。<br>她的脸颊带着一点绯红。<br><br>“我观摩了你的训练指导！<br>好强的指导能力，激发了我的斗志。<br>我也……不能输给你。”<br><br>“我也不会输……嗯。”<br><br>“米可！是的，我更正一下。<br>我们，绝对不会输。<br>我们切磋共进吧！”<br><br>她的宣言，如青空般澄澈透明。<br>她的双眼，如穿透树叶的春日般耀眼夺目。"},
{index="20022",text="怎么样！松软香嫩又弹牙！<br>这就是关西的烤鱿鱼！<br><br>关东的鱿鱼净是些整条拿来烤的吧？<br>但是咱心目中的“烤鱿鱼”是这种。<br>从小一直拿它当小零食吃，<br>说咱吃它长大的也不为过呀！<br>你说我不算大？哪儿那么多嘴啊！<br><br>真是的，再刁难我可不给你吃了！<br>逗你玩儿的，谁让咱这么大度呢。<br>喏，别客气，大口吞！<br><br>咋样？嘻嘻，好吃吧！<br>你这满足的表情，让咱这关西人倍感欣慰啊！"},
{index="20023",text="+＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝+<br>　　能让任何人都顺从于我的魔法<br>+＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝+<br>【等级】★★☆☆☆　魔女入门<br><br>【材料】<br>·连续7天接受月光沐浴的水<br>·绝对要成功的信念<br><br>【顺序】<br>①用手指蘸取接受过月光沐浴的水并画一个五芒星<br>②咏唱对方的全名3次<br>③咏唱“我于从顺”1次<br>④一边注入意念一边合上书（结束♪）<br><br>※被发现的话可能会受到魔法制裁哦？<br>　要小心☆<br><br>“哼哼哼……太完美了。<br>这下就能逃掉明天值日倒垃圾的任务了！”<br><br><br>制裁魔法“宿舍长训话”准备释放……<br>魔女的命运究竟会走向何方？！<br>"},
{index="20024",text="准备完毕，完美！好兴奋☆<br>胡萝卜汁和胡萝卜棒！<br>再加上薯片，<br>这下不开派对还等什么！<br><br>“啊哈哈哈！嗨起来吧！<br>素质看这边♪<br>耶！向喜欢的人撒撒娇亲亲～”<br><br>“呃，那个……”<br><br>好啦好啦，怎么样？现在很嗨吧？<br>不管是睡衣还是我们，都超级可爱吧？<br>这下肯定要涨粉了！<br>搞不好会爆火？天哪，我开心爆了☆<br><br>“哦，乔丹来了。<br>这里这里。<br>胡萝卜汁可以吗？”<br><br>“阔以～<br>好厉害，已经这么热闹了诶～”<br><br>“乔丹，太慢了！<br>话说，是不是应该再拉点人过来？<br>和栗东宿舍的人来场偶遇之类的。<br>啊哈！那肯定会嗨翻天☆”<br><br>派对才刚开始，<br>人多点会更热闹吧？<br>说不定能把所有人都叫来？<br>吃吃喝喝，热热闹闹地玩一场，<br>哪有时间去睡觉啊？<br><br>哎呀，总之赶紧开始吧！<br>耶耶！看这边！<br>麻烦大家举个杯！<br>那么——<br><br>“今晚玩个通宵吧！<br>耶！今晚是party night！”<br>"},
{index="20025",text="“啪！”，一声清脆的敲击声<br>回荡在泳池边。<br>生野狄杜斯正站在白板前，<br>对两位优俊少女进行指导。<br><br>“听好了，涡轮。<br>连热身运动都不做就下水<br>简直是不可理喻。<br>无论体力有多强，如果掉以轻心的话<br>还是会有生命危险。听懂了吗？<br>首先要拉伸肌肉，认真拉伸——”<br><br>“呜呜，听懂了啦。你话好多哦～”<br><br>“唐怀瑟也是，<br>不要发呆，好好做伸展运动！<br>做屈伸和前屈的时候要用上肌肉，<br>步骤都写在这里了。<br>只要严格遵守，就能获得<br>比平时更好的训练成果——”<br><br>“好、好的！”<br><br>一直在一旁望着<br>二人争来争去的<br>待兼唐怀瑟也收获了<br>生野狄杜斯的谆谆教诲。<br><br>“要保护好你们的双脚。<br>坚决不可以乱搞一通把身体搞伤。”<br><br>“你不要管我啦～”<br>一不小心让牢骚脱口而出的双涡轮<br>也乖乖听从了这个要求。<br>她并不是喜欢说教，<br>而是非常为同伴着想。所以——<br><br>“那我重头再说一遍。”<br><br>她一定会把热身运动<br>的重要性重复很多遍，<br>让这些知识深深印在她们的脑海里吧。<br><br>“啊？！”，这次声音<br>响彻整个泳池，<br>生野狄杜斯的拉伸运动指导，<br>在那之后又持续了很久。"},
{index="20026",text="“等——疼疼疼。<br>不要碰尾巴和耳朵啦！”<br><br>“啊哈哈，是素质大家族！<br>看起来很开心啊～”<br><br>你看起来更开心吧。<br>不要悠哉悠哉地看戏啦，<br>快过来帮帮我啊。<br>别误会，我很喜欢小孩。<br>孩子天真可爱，也没有坏心眼。<br>但是——<br><br>“大姐姐，<br>你的耳朵和尾巴好可爱！”<br><br>“嗯！超可爱！”<br><br>“唔……”<br><br>毫无坏心眼的人也很难对付啊。<br>小孩子夸我可爱，<br>我才不会开心……啊啊真是的，<br>居然满眼期待地问我“能不能摸一下呀？”<br>真是的，不要来求我啊。<br><br>“就、就算你用那种表情看着我，<br>不行的事就、就是不行……”<br><br>语气充满了动摇。<br>好好好，我知道了。<br>这一定是无效的抵抗。<br>反正，最后肯定会被<br>天真无邪的笑容欺骗，唉。"},
{index="20027",text="用花做谢礼，天空她会喜欢吗？<br>虽然还有很多花可以选，<br>但是听说雏菊特别喜欢太阳……<br><br>等待太阳，绽放花朵……<br>喜欢晒太阳的花，<br>和天空很像呢。<br><br>而且，还有一点<br>特别像天空——<br><br>雏菊的花语是“天真无邪”，<br>以及“保持本真”……<br><br>睡睡午觉，钓钓鱼，<br>看起来总是很开心的天空。<br>就像随风摇摆的雏菊一样<br>悠闲自由……<br><br>和她说话的时候总能感到安心，<br>仿佛在对我说，不要勉强。<br><br>（希望天空喜欢雏菊。<br>因为我已经，深深爱上雏菊了……）"},
{index="20028",text="没想到你居然想读<br>《艾凡赫优俊》……<br>不，我很高兴……非常高兴。<br><br>我想想……<br>这里的图书室有……<br><br>这本新订版怎么样？<br>注释非常详细，认真解释了<br>书中的很多细节。<br><br>这本大开本我也很推荐。<br>书里有很多插画，对想象当时的生活<br>和当地的风貌非常有帮助！<br><br>啊，根据电影改编的小说也很棒！<br>原创部分实在是惊心动魄，<br>高潮部分是五位优俊少女<br>持枪战斗的场面。<br><br>不过，还是希望你能读一下原著！<br>通过原著特有的<br>厚重的古风文笔<br>可以让你感受到真英雄的勇猛……<br>（※以下省略）"},
{index="20029",text="“呵——呵呵呵！<br>我们来制定海外远征的计划吧！<br>我的第一个目标是——法国！<br>然后是美国！你们呢？！”<br><br>“哦哦哦，世界！神鹰也要参加！<br>英国！迪拜！向往的巴黎！”<br><br>“真不错！感受到了你的热情！<br>在温莎古堡的景观大道共跑，<br>背对着凯旋门和强敌握手，<br>和朋友们一起欣赏迪拜的夜景。<br>真想用整整一周体验一下这些！<br>那边的女孩你怎么想？！”<br><br>“我想在国内稳扎稳打地赢比赛～”<br><br>“太棒了！主动拒绝走向世界也是不错的选择。<br>为了看到你闪耀的身姿，<br>全世界的人都会聚集在这个国家！<br>没错，你就是‘世界’的中心！<br>嗯嗯……革命！<br><br>真好……每个人都有<br>只属于自己的宝贵梦想。<br>关注这个世界！被世界所关注！<br>然后我们就能变成闪耀的宝石！”"},
{index="20030",text="她总是起得很早。<br>其他优俊少女还在睡梦中时，<br>她就已经出门开始了送报的兼职。<br><br>送完报后，她便继续上课和训练，<br>跑了很久后又继续兼职。<br>她甚至还同时做过三份兼职，<br><br>每天都忙到眼花缭乱。<br>即使是优俊少女也本应累到气喘吁吁的生活，<br>她又是怎样坚持下来的呢——<br><br>“好了，<br>补充完能量又能加把劲了！”<br><br>无论何时，<br>她都做好了飞奔而出的准备。<br><br>～～能量棒，献给努力的你～～<br><br>自从这条广告播出，<br>艾尼风神就从粉丝那里<br>收到了大量的能量棒……"},
{index="20031",text="“起跑练习？<br>让我起跑前都要在起跑线上好好等待？<br>不要小看我！这点小事根本就是小菜一碟！”<br><br>……<br>……<br><br>“啊啊啊！为什么还不让我起跑啊？！<br>为什么不下命令啊？！<br>呜呜呜……既然如此……”<br><br>（哗！哗！哗哗哗！）<br><br>“我就挖个洞钻出去！"},
{index="20032",text="时为当代，一日，风雨大作。<br>一玲珑娇小优俊少女，<br>立于泥泞赛道之上。<br><br>“干嘛一脸惆怅？<br>你是觉得我没法跑了吗？”<br><br>虽只为修行，<br>亦无贪图安逸之理。<br><br>“你说啥呢呆瓜！<br>狂风暴雨天就不能好好跑了吗？<br>赛道上有泥我就迈不开步了吗？”<br><br>或云，物是人非，<br>何来风情。<br><br>“哼！真小真小！<br>太小家子气啦！”<br><br>非也！<br>风情仍存于此地！<br><br>“顶风跑更有意义！<br>泥水算啥！只要是在地上，我就能跑！”<br><br>若无江户人风情之魂，<br>此优俊少女亦不复存！<br><br>“我就是在江户长大的稻荷一！<br>不管面前是狂风还是暴雨，<br>我都会义无反顾地勇往直前！”"},
{index="20033",text="“今天给大家介绍的产品是，<br>这款高压清洁喷嘴！<br>它能喷出强劲的水流，<br>就算不用力擦洗也能轻松去除污渍！<br>清洗鞋子当然不在话下，甚至连车和墙壁这类东西<br>也能轻松清洁干净哦！”<br><br>“哇哦，好棒。<br>但是，这个东西应该会很贵吧～”<br><br>“不会的哦，小青。<br>价格其实非常实惠！<br>而！且！喷射距离也很bueno！<br>就算给远处的花坛浇水也不在话下！<br>看，就像这样——”<br><br>（哗——）<br><br>“啊……”<br><br>“呵呵，神鹰……你这是在玩水吗？”<br><br>“小草？！对对对不起！<br>我不是故意的！！<br>只是小草你刚好在花坛旁边！<br>对吧？！小青——诶，人呢？！”<br><br>“神～鹰～<br>真是的……你是在清洗训练跑鞋吗？”<br><br>“对对对，没错！<br>它今天也陪我一起努力了，<br>所以我想把它洗干净！”<br><br>“对用品持以敬意是好事。<br>我想也一起洗洗，可以吗？”<br><br>“当、当然当然，请吧！呼……”<br><br>“话说，刚才你弄了我一身水，<br>我会在比赛中回敬你的。”<br><br>“那可是……正合我意！<br>我不会输的哦，小草！！”"},
{index="20034",text="一位优俊少女轻轻拭去额头上的汗。<br>从侧面望去，她神态凛然，<br>透露着高贵的精神和不畏逆境的意志。<br><br>“即使如此，我也要跑下去。”<br><br>她的双腿如同玻璃般脆弱，<br>担心她无法疾驰的人不在少数。<br><br>“即使如此，我也不会放弃。”<br><br>她的双眼，紧紧盯着两个身影。<br>一位在武道中寻得了光明，<br>一位对薄红抱有憧憬。<br>而她只能焦急且无奈地望着尚且遥远的背影。<br><br>“即使如此，我也要去竞争。<br>心怀骄傲，奔跑于当下！”<br><br>即使如此……她站了起来。<br>只要还有呼吸……不，只要这条路还在延伸。"},
{index="20035",text="啊，不行了不行了，我要休息～<br><br>哎呀，太难以置信了。<br>正常人谁会在共跑的时候使出全力啊？<br>谁会在弯道超车啊？<br><br>结果我被轻轻松松地甩在了后面。<br>太好笑了，笑死。<br><br>而且，指甲油怎么还没干～<br>哈啊……哈啊啊啊啊啊！<br><br>输得哑口无言，我也太丢人了。<br><br>好，终～于干啦☆<br>总之先去跑跑坡道吧！"},
{index="20037",text="“金黄色的汤汁，整整齐齐的面，<br>还有炖得入味、入口即化的叉烧肉”<br><br>“我肚子一饿，就会想到拉面。<br>无论是匠人制作的正宗拉面，<br>还是市井小店中受人喜爱的风味拉面，亦或是泡面，<br>都是让我感动过的美食！”<br><br>“啊！那些为我与拉面带来如此美妙邂逅的人们，<br>是不是该被授予‘拉面骑士’的勋章呢？”<br><br>“而为了能让匠人们做出更美味的拉面，<br>我想组建最好的设备，<br>让他们大显身手！<br>就把这里命名为‘拉面王国’吧！”<br><br>“诶？<br>这么做反而会让他们摸不着头脑？”"},
{index="20038",text="她威风地坐在粉丝的中央，周围满是尖叫声。<br>稍显冷酷的笑容，<br>似乎透露着不耐烦而又满意的意味。<br><br>是否该靠近她，让人犹豫不决。<br>但她的身影，还是会不自觉地出现在视线中……<br><br>真的……会有人不在意<br>像她这样的优俊少女吗？<br><br>熙熙攘攘，她的身影逐渐埋没在人群之中。<br>不经意伸了伸头，竟与她视线相交——<br><br>“怎么？一副渴望的样子，<br>你也想被我疼爱吗？”"},
{index="20039",text="你说——<br>“我是为了防止你再翘掉值日才监督你的。<br>这也是为了其他同学”。<br><br>正如你所说，只要我稍微休息一下，<br>你就会叽叽喳喳唠叨个不停。<br>我只是稍微玩了一下手机，<br>不至于吧？<br><br>喂，等等！你是什么时候<br>把笤帚拿过来的啊？还让我赶紧扫。<br>怎么像我老妈似的？<br><br>明明你也有事要做。<br>管我的这功夫，<br>车站前的泡芙就会卖光的啊。<br>你不是期待今天很久了吗？<br><br>啊啊～真是的，都怪你。<br>那不是得尽快扫完了吗？<br>一秒都不能耽误！"},
{index="20040",text="“呼～流了好多汗呀！<br>肌肉也练得很满足！”<br><br>目白莱恩在结束了一段训练后，<br>将运动饮料灌入口中<br>以补充流失的水分。<br><br>“训练员最好也到树荫下来，<br>在阳光下即使只是站着也会消耗体力的。<br>不介意的话，也请喝点——”<br><br>说到这，目白莱恩<br>一下子收回了递来饮料的手。<br><br>“那、那个……啊哈哈！<br>把我喝过的递给你太不礼貌了！<br>我去更衣室给你拿瓶新的来！”<br><br>目白莱恩的脸颊微微泛红。<br>说完，她便像训练时那样<br>潇洒地跑开了。"},
{index="20041",text="“好厉害……”<br><br>她坐在空无一人的教室中<br>观看着比赛视频，<br>不由自主地嘟囔道。<br>屏幕中映出的是<br>那个自信满满、实力强劲的奔跑身影——<br><br>“即便如此，我也要成为一等星……”<br><br>就在她坚定决心之时，<br>门突然被粗鲁地打开了。<br><br>“噢！端庄美丽的爱慕织姬！<br>没想到竟会在这里与你相遇！<br>果然我与你有命中注定……<br>剪不断的缘分啊！”<br><br>这声音打破了寂静。<br>意识到来者是谁的那一瞬间，<br>她合上了笔记本电脑。<br><br>“抱歉让你久等了，我的对手！<br>来，让我们共同奏响<br>名为炽热友谊的交响曲吧！”<br><br>“我本来就没在等你，<br>而且对手才不是你说的那种关系吧。”<br><br>她一边反驳着，一边收起了电脑。<br>不知道能不能摆脱这一局面呢——<br><br>“你的表情真凝重啊！<br>让我们一起解决困扰你的问题吧！<br>啊啊，这是多么感人的场景！<br>来吧，说出你的烦恼！”<br><br>“……”<br><br>绝对不能让这个人知道<br>刚才自己看的是谁的比赛。<br>被知道的话可就麻烦了。"},
{index="20042",text="“早呀！<br>这句招呼中还有更深层的含义，你知道吗？”<br><br>“早……也就是先于他人……<br>而‘先于’又可以理解为‘快于’！<br>这就说明！早上打招呼时说的‘早呀’<br>其实还包含‘快呀’的意思！”<br><br>“换句话说，<br>这句问候语其实是跟速度相关的！”<br><br>“只要坚持早上打招呼，<br>就能加快前进的速度！<br>这就是前进革命！！”<br><br>“所以，让我们一起来问好吧！<br>早呀！！”"},
{index="20043",text="这是来到特雷森学园后<br>写的第几封信了呢？<br>致北海道两位妈妈的信——<br><br>虽然打电话可以马上告诉她们，<br>但感觉通过文字<br>可以把自己真正的心情——<br>开心的事、烦恼的事<br>更加清晰地表达出来。<br><br>妈妈们也一定能够<br>清晰地感受到这一点吧。<br>我今天的心情，能够好好地传达给她们吗？<br><br>“妈妈们，近来还好吗？”"},
{index="20044",text="——你经常来这家店吗？<br><br>真机伶：是的！我刚搬进宿舍的时候，<br>想要添置一些小装饰，就来了这家店。<br>从那以后就经常会来♪<br><br>所以这也算是充满回忆的店铺了呢！<br><br>真机伶：店内装潢一直都没变，<br>总是让我回想起那时的情景……<br>啊！这个马克杯！<br>这也是从那时起就一直在卖的款式哦♪<br>虽然机伶买的那个已经褪色了，<br>但这也让我感到很开心呢～<br><br>——这是什么意思呢？<br><br>真机伶：我和训练员开作战会议的时候，<br>经常会用到这个杯子！<br>会议中我有时会很苦恼，<br>不知道该怎么去做。<br>但是但是！这时候中场休息一下，<br>灵感就会突然“噼里啪啦”地冒出来！<br>所以……<br>杯子虽然褪色了，<br>但这也代表我们一起克服了许多难关。<br>我觉得这是我们努力过的证明。<br><br>——是日积月累才有了这样的颜色呢。<br><br>真机伶：对！我以后也会多多使用它，<br>让它染上更加可爱的色彩♪<br><br>◆个人简介：真机伶<br>隶属于特雷森学园的优俊少女，<br>也是深受年轻人喜爱的网红。<br>称赞她的话题“可爱的真机伶”<br>时常登上热搜。<br>最近热衷的事情是训练。<br><br>骏友圈：＠Curren"},
{index="20045",text="唔！唔唔唔？！<br>鸽、鸽子……真的……<br>有用这种姿势吗？！<br><br>呀～好、好痛……<br>不、不行了……<br><br>不——可以放弃！<br><br>我要用最闪耀的光芒！<br>将“谢谢”<br>和“一起在优俊偶像的道路上前进吧”的<br>这份心情——<br><br>传达给所有的粉丝，<br>以及那位一直支持我的人！<br><br>因为……飞鹰子，<br>是顶级优俊偶像啊！！<br><br>（咔）<br><br>啊……"},
{index="20046",text="我重要的帽子被风吹走，落在草地上了。<br>看到这个情景，我就想起了<br>奶奶教我的魔法——<br><br>“哎呀哎呀……？<br>我可爱的小革，<br>怎么哭了？”<br><br>“帽子脏了？呵呵呵……<br>快别哭了，<br>可爱的小革。<br>你问为什么？因为这意味着，<br>你又向出色的魔女迈进了一步呢！”<br><br>“魔女的帽子<br>会跟着魔女一起奔跑，<br>在不断变脏和开线的过程中<br>慢慢积蓄魔力。”<br><br>“过来这边，<br>我来教你一个特别的魔法。<br>它能清除污迹，<br>并且不让积蓄的魔力随水流失——”<br><br>“没错，奶奶！<br>现在正是使用奶奶教的<br>‘净化魔法’的时候！”<br><br>“好～既然决定了，<br>就去准备魔法道具吧！<br>我记得是需要……清水和肥皂——”"},
{index="20047",text="一如既往的游戏厅，<br>今天却像有演出一般喧闹。<br><br>“嘿嘿～这样下去<br>我就要刷新最高分纪录了！<br>大家再营造点气氛吧！”<br><br>她在跳舞机上跳着舞，<br>声音明快而洪亮，<br>尾巴也随着轻盈的舞步摇摆。<br>然后，她露出了灿烂的笑容——<br><br>“哎！你也来给我加油吧！”<br><br>——先是心脏扑通直跳，<br>随即才意识到<br>那个眨眼和那句话是对我发出的。<br><br>“最后转个圈～摆出胜利手势！<br>耶！最高分！”<br><br>屏幕显示出超神的分数，<br>围观者们沸腾了，我也不由得鼓起掌来。<br><br>“谢谢大家为我加油！<br>哎呀，已经这个时间了啊。<br>那我们下次在赛场上见吧！”<br><br>“帝王大人我会让你们<br>比今天更兴奋的！<br>那我走啦，拜拜！”<br><br>她说完便跑开了。<br>即使她的身影已经消失不见，<br>她的笑容仍在我眼前挥之不去。<br><br>我想，从那时起，<br>我可能就已经成为<br>那个小小“帝王”的粉丝了——"},
{index="20048",text="“请问……你打算把这些全吃完吗？”<br>面对摄影师的提问，<br>小栗帽认真地点了点头。<br>不过笔者有注意到<br>她的尾巴在摇来摇去。<br><br>像小栗帽小姐这样的选手，<br>训练的强度也相当大吧，<br>吃这么多是为了恢复体力……吗？<br><br>小栗帽（以下简称小栗）：不。<br>我只是想吃这么多。<br>我真的很喜欢……很喜欢吃饭……<br>喜欢能够填饱肚子的所有东西。<br><br>她坚定地说着，<br>眼睛像彗星一样闪闪发亮。<br><br>小栗：我可以开吃了吗？<br>如果大家不介意的话，也可以一起吃。<br>那么……我开动了！<br><br>她的笑容就像绽放的花朵一样。<br>她是真心喜欢吃饭……<br>摄影师用相机捕捉到了<br>这位淡定“偶像优俊少女”出人意料的<br>真实一面。<br><br>（摘自《月刊闪耀》<br>【封面特辑！小栗帽——<br>“偶像的真实一面”】）"},
{index="20049",text="我不想被人当成花瓶。<br>我想证明<br>自己努力打磨的不仅仅是外表。<br><br>“啊，又焦了。”<br><br>我想变得更强……<br>至少要能够独立处理自己的事情。<br>我希望自己能从里到外都闪闪发光，<br>而不是只有表面的光鲜靓丽。<br><br>“好……再来一次！”"},
{index="20050",text="“呼啊……啊。<br>是菱亚的饭团啊。<br>这个用的鲑鱼很好，很好吃呢～”<br><br>“我说你……”<br><br>“啊，没事没事～<br>这是她做好留给我们的，<br>正好也有光辉的份……”<br><br>“唔～我不是说这个！<br>早上不是要去晨跑吗？！<br>你这家伙连衣服都没换，<br>还在那里……站着喝水——！”<br><br>“哦哦～真有精神啊。<br>嗯嗯嗯～<br>感觉好像醒过来了～<br>那我就去换衣服喽。”<br><br>“提前做好的饭团……<br>要是剩下的话会被丢掉吧。”<br><br>（哒哒哒……）<br><br>“……<br>剩下的话……不太好吧……”<br><br>嚼……<br><br>“啊！！真好吃……<br>说起来……<br>最近一直都是比赛……<br>都没有时间好好享用食物……”<br><br>“啊，浅蓝色容器里的<br>是我老家寄来的腌黄瓜。<br>那个也可以随便吃哦～”<br><br>“唔？！真是的……！！<br>我知道了，你快点去换衣服啦！！”"},
{index="20051",text="对于两次刷新纪录的壮举，<br>她如此说道：<br><br>“我能奔跑都是多亏了大家。<br>我的这个成绩<br>若是稍微报答了大家的恩情，我便心满意足。”<br><br>为了回报周围人曾带给自己的奇迹，<br>她决心要由自己来创造奇迹。<br><br>她突破重围，将对手们远远甩开——<br>身后是紧追不舍的影子。<br>那一瞬间，她所怀抱的感谢与执念，<br>在她苍蓝的双眸中燃起了火焰。<br><br>在燃尽一切的尽头，她抓住了<br>那第三次的奇迹——<br><br>（摄影：编辑部／记者：乙名史 悦子）"},
{index="20052",text="“嗯……<br>这个月的回顾，大概就是这样吧。<br>训练中没有晕倒，<br>也去看了小特她们的新人战……<br>嗯……<br>这个月让我更有动力继续加油了。”<br><br>“啊……不能再这样了！<br>得马上开始确认下个月的训练内容……<br>不，还是先从饮食内容开始吧？<br>对、对了。膏药贴也得再买一些——”<br><br>“咦……？热乎乎的，茶？<br>这是什么时候……”<br><br>“呵呵。希望合你的口味～”<br><br>“光明？！早上好！<br>对不起，我完～全没注意到……！<br>我这就趁热喝——好烫！”<br><br>“哎呀，这可不行～小鹤同学，<br>请先“呼～呼～”地吹一下。<br>来，和我一起……“呼～呼～”<br><br>“好、好的！呼……呼……<br>咕嘟……哈～”<br><br>“呵呵呵，这边还有茶点～<br>那么，我先去洗手间<br>梳洗一下了～”<br><br>“啊，好的！非常感谢！<br>我吃……呵呵，好甜啊。”<br><br>“好了，继续继续！<br>我记得刚才还在烦恼接下来要做什么。<br>嗯……首先要确认一下情况，<br>然后再排好优先级。<br>诶嘿嘿……好厉害啊。<br>刚才脑子明明乱成一团，现在思路却超级清晰！”<br><br>“好——！加油吧！”"},
{index="20053",text="“成田路……你的文件掉了。<br>这是下节世界史要用的资料吧？<br>我帮你拿……分我一半。”<br><br>“哇，谢谢你！<br>不过，我可以的！毕竟不重，<br>而且这算是班长分内的工作！”<br><br>“比起这个，织姬！<br>下节课你准备好了吗？<br>要去别的教室上课，<br>还是早点准备好比较好哦！”<br><br>“这种时候你还关心别人……你这人真是的。<br>来，我帮你拿。”<br><br>“织姬……！”<br><br>“是啊，成田路——！<br>也让我和大进帮忙搬吧——！！”<br><br>“都说了别在我耳边大叫啦……！<br>嗯，就是这样，<br>快点分一下吧，成田路。”<br><br>“奖券……！怎么连大进也这样！<br>那我就不客气啦，<br>请两位帮我拿一下海报纸！<br>织姬就拿地球仪吧！”<br><br>成田路干净利落地将东西分给了别人，<br>却固执地不肯让出那个装满了文件的纸箱……"},
{index="20054",text="“啊啊，太阳看到我后，<br>脸竟然变得如此赤红！”<br><br>“呵呵，这也没办法。<br>毕竟这个宇宙中最美的存在，<br>正是我啊！”<br><br>“普照世界的太阳啊，<br>尽管骄傲吧。<br>能与我一同入镜，是你的殊荣！”<br><br>“来，怒涛！开始吧！<br>为将来的世纪末霸王，<br>为伟大的我拍摄照片吧！”<br><br>“好、好的……！”<br><br>刚出道不久的好歌剧<br>选择了名将怒涛<br>来给她拍摄宣传照。<br><br>“主题当然是‘世纪末霸王’！<br>怎么样，这件威风凛凛的披风！<br>是不是充满了霸王庄严的魅力啊！”<br><br>“感、感觉比平时更耀眼了……！<br>能这么快就借到<br>过去圣蹄节用过的服装……<br>真不愧是好歌剧。”<br><br>“那我要开拍啦……？<br>呃，该从哪个角度拍呢……<br>咦……哇、哇哇哇哇？！”<br><br>名将怒涛不小心绊了一跤，<br>相机飞到了空中。<br>她慌慌张张地<br>试图飞身接住——<br><br>“噗啊……啊啊啊，对、对不起～！<br>差点就把相机弄坏了！”<br><br>“但是，总算是保住了，所以……<br>呀啊啊啊啊！！<br>变、变成连拍了？！<br>拍了好多张啊！”<br><br>“哦……？干得好，怒涛！”<br><br>“这不是拍到了最棒的一张吗！<br>看伫立的我这熠熠生辉样子——！<br>即使在开天辟地以来织就而成的历史之中，<br>也未曾有过如此至宝吧！”<br><br>“我由衷地赞美你，怒涛！<br>能捕捉到我最珍贵最美的瞬间，<br>真不愧是我的宿敌！哈——哈哈哈！”<br><br>“好、好歌剧……！<br>哇……虽、虽然不敢当……<br>但我很开心……！！”"},
{index="20055",text="手机的通知声响起。<br><br>消息应用LANE上<br>显示了最新消息。<br>“阿斯顿真弓<br>发来了一个文件”<br><br>点开一看，<br>她发来的似乎是一个音频文件。<br>等了许久……<br>她也没有再发来其他消息。<br>我按下播放按钮——<br><br>“电池，无异常。<br>麦克风功能也没问题。一切正常呢。”<br><br>“那么阿斯顿真弓广播，<br>现在开播咯～<br>开玩笑啦，平时我不会这么说的。”<br><br>“另外今天我会安安全全地<br>在楼顶的小屋里眺望天空，<br>然后就让双腿晃来晃去的吧。<br>毕竟我一点都不害怕呢。”<br><br>“昨天哗啦啦地下了大雨，<br>所以我的身边有很多水洼。多亏了它们，<br>小真现在正待在天空与天空之间。<br>上面是大大的天空，下面是小小的天空。”<br><br>“我现在，就在天空与天空之间。”<br><br><br>我停止播放音频，<br>从椅子上站了起来。<br>脑海中浮现的目的地，<br>是学园里能清楚看到天空的地方。<br><br>如果我用尽全力跑上楼梯，<br>她那圆溜溜的眼睛会不会变得更圆，<br>然后露出无奈的笑容呢？<br><br>“是的……小真就在这里。”"},
{index="20056",text="最强的称号、至高的荣耀，<br>我喜欢这些闪耀的东西。<br>大家也都是这样吧？<br><br>但是……那家伙却不一样。<br>她本身就比任何人都闪耀，<br>就像真的在发光一样，刺眼得要命。<br><br>哈哈，正合我意。<br>管你是光还是什么，都无所谓。<br>我会把你们统统甩在身后的。<br><br>不然的话，是赢不了的吧？<br>我所追求的，<br>就是这种最强的【顶点】啊。<br><br>“喂，速子，赏个脸吧。”"},
{index="20057",text="嗯……新的吹风机，感觉不错。<br>不会太干涩，有种蓬蓬松松自然干透的感觉。<br>真不愧是气槽前辈推荐的……<br>下次想和她说说我的使用感受呢。<br>要不要再送她一份香氛呢……？<br><br>用这个好好做个造型的话……<br>说不定，我也能拥有像光明那样<br>软绵绵的发型？<br><br>我从以前就觉得她的发型真可爱啊，<br>摸上去的手感也像棉花糖一样……<br>之前莱恩也说，<br>她总会不知不觉地就上手去摸。<br>不……我才不是想要被摸！<br>那样也太难为情了。<br><br>“不过——果然还是不行吧。<br>我和光明的发质完全不一样——”<br><br>“Hey，多伯！那个吹风机<br>是新买的吗？”<br><br>“哇，大树！嗯、嗯，<br>是气槽前辈推荐给我的……”<br><br>“Oh，太棒了！<br>气槽的头发又直又顺～<br>多伯的头发也是又直又顺～<br>也就是说，绝配！”<br><br>“等你吹干之后，<br>让我好~好地感受一下你的顺滑秀发吧♪<br>我很期待哦！！”<br><br>“诶……真是的，你在说什么啦。<br>不过……稍微摸一下的话倒是可以。”<br><br>大树真的就一直笑眯眯地等着。<br>我一说可以摸了，她就立刻扑到我的背后<br>伸出手来。<br>但和那股气势相反，<br>她从发根一路<br>缓缓抚摸到发梢的动作<br>比我想象中要温柔得多。<br><br>等我告诉她我有点害羞，<br>让她差不多停下时，<br>已经过了好一会。"},
{index="20058",text="“啊……啊嚏……！”<br><br>“抱歉，我从昨天开始就有点感冒呢……<br>我本没打算在公共场合<br>打出这么豪迈的喷嚏——”<br><br>“我开下窗吧——<br>感觉可能也是因为屋子里有些灰尘。”<br><br>打开窗户，带着暖意的风<br>驱散了干燥的空气。<br>她深深吸了一口气，然后缓缓吐出。<br><br>“我平时，是不会像那样打喷嚏的……<br>呵呵，真伤脑筋。明明越是在亲近的人面前<br>才越该绷紧神经呢。”<br><br>她移开视线，望向了窗外。<br>一抹橙色的夕阳<br>染红了她的脸颊。"},
{index="20059",text="比如说——刚入学的那会儿，<br>说起爱丽速子同学，<br>那可真是万众瞩目的焦点。<br>因为不巧和她在同一个班，<br>所以我现在也还清楚地记得那些堪称无礼的视线<br>曾如雨点般倾注在她的身上。<br><br>一开始，当然是因为她显赫的血统。<br>我们这所学园里<br>虽然也有不少所谓的名门大小姐，<br>但她的祖母是奥克斯优俊少女，<br>母亲更是不败的樱花奖优俊少女，<br>这种血统足以让她备受瞩目了。<br><br>然后……这些以她为中心<br>迅速汇集起来的视线很快便彻底反转了。<br>古怪的言行、可疑的实验活动、<br>即便如此也依旧耀眼的才能……<br>嗯……这么列举下来，<br>倒也足以令人对她敬而远之了。<br><br>“呵呵呵……<br>这不是出现了很有趣的论文吗？<br>关于优俊少女的肌肉收缩与能量的新学说……<br>这个点子似乎能用在下次的实验里！<br>说说而已……！”<br><br>今天，热闹的自助餐厅一角<br>也同样以她为中心空出了一圈的座位。<br>与其说是空出了一圈，不如说是结界？<br>或许是那高高堆起、数量异常的方糖<br>张开了什么屏障吧——<br>像我这样普普通通的学生<br>绝对无法突破的那种屏障。<br><br>“速子……<br>还是不要拿食物来玩了吧。”<br><br>“哦，是茶座啊！但你会这么说，<br>不正是因为你没有将食物看作食物吗？<br>我可是准备把这里所有的，<br>没错，是所有的东西都加到红茶里！<br>也就是说我会全部吃掉，所以没问题——”<br><br>“问题大了。”<br><br>而那样的屏障，<br>如今似乎有不少人能够突破了。<br><br>在满是空位的速子同学对面，<br>茶座同学叹着气坐了下来。<br>随着她的动作，我看到一颗<br>堆在上面的方糖骨碌碌地滚了下来。"},
{index="20060",text="“一二！三四！<br>五六七八！”<br><br>“最后来做个深呼吸……<br>准备运动就做好啦！”<br><br>“来，尽情地游泳！<br>然后把肚子游得空空吧！<br>今天的点心也做得<br>非常buono哦！”<br><br>“嗯？不太会游泳？<br>那你就抓着我的手，<br>让我来教你怎么游吧！”<br><br>“像救生圈一样圆滚滚的甜甜圈<br>正在等着我们哦。<br>一起加油吧！”<br><br>“好，那就噗通一声～<br>跳进……”<br><br>“啊，等等～<br>那个不是救生圈哦！<br>那是我烤的、特大号甜甜圈呀——！”"},
{index="20061",text="～小金船炒面缘起～<br><br>那还是我尚未披上白玉粉、<br>身为俏丽棕发的<br>小金船的时候——<br><br>“谁来……<br>谁来买一下这个酱汁吧……<br>这是我家祖传的酱汁——<br>唉，谁都不来买……”<br><br>然后，就在我心灰意冷、<br>开始在沙滩上用沙子堆城堡的时候——<br><br>突然，海面仿佛裂开一般，<br>一位貌美如花、光芒万丈、<br>秀发宛如珍珠的<br>优俊少女观音现身了。<br>她对我如此说道——<br><br>‘黄金船啊，做炒面——<br>用那个酱汁去做炒面吧——<br>如此一来，那酱汁和你<br>肯定都能大受欢迎的——<br>之后顺便再参加点比赛？”<br><br>就这样，黄金船特制<br>好吃到爆的炒面便诞生了。<br>故事到此结束——<br><br>而描绘了这段珍贵传说的<br>挂轴就在这里。<br>诶？你说这位优俊少女观音<br>和小金船长得一模一样？<br>真是的……你搭讪的套路也太老土了吧☆"},
{index="20062",text="今天真是个超赞的晴朗好天！<br>这种日子不去兜风<br>也太亏了吧？<br><br>来来！副驾驶座给你啦！<br>听说今天小塔要带我们<br>去一个特别棒的地方呢。<br><br>小塔它啊，总是会带我去<br>很棒的地方，<br>让我心情变得超级赞哦！<br><br>哎呀，可别忘了<br>系好安全带哦♪<br><br>因为用和小塔一样的速度去感受风<br>可是这世界上最棒的体验！<br><br>无论工作还是放松，<br>马力全开全速前进才是最畅快的吧？"},
{index="20063",text="（哗啦啦啦啦……）<br><br>下雨了……<br>明明还想继续跑的……<br>不知道要下多久才会停呢？<br><br>说起来，之前和小特<br>一起跑步的时候也突然下雨了……<br><br>那时我们一边在树下避雨，<br>一边看着云玩联想游戏来着。<br><br>那时小特突然开始说起豆包、饭团什么的，<br>我还纳闷，<br>原来是在说云的形状。<br><br>这朵像胡萝卜蛋糕、那朵像汉堡肉……<br>她还真是喜欢吃东西呢。<br><br>那朵云……<br>长得像训练跑鞋，<br>那边那朵是徽章的形状，<br><br>那朵云……是优胜锦旗的形状。<br>啊……雨云散开了。<br><br>太好了，好像只是阵雨。<br><br>咦？那边那朵云……<br>好像有点像胡萝卜汉堡肉？<br>呵呵，不知道小特<br>有没有发现呢……"},
{index="20064",text="嗯♪天气真好♪<br>阳气满满，<br>今天会是怎样美好的一天呢？<br><br>一日之始，最重要的果然还是“颜色”！<br>为了度过美好的一天，必须好好<br>主动控制自己的运势才行！<br><br>今天该和哪块手帕度过一天呢？<br>带着掌管成长的绿色手帕，<br>在训练中全力以赴……<br><br>不对，为了避免太过投入而累坏自己，<br>还是选择能带来宁静的柠檬黄……<br><br>啊，可要是在训练中<br>受伤就得不偿失了，<br>那还是带着能驱邪的紫色比较好……？<br><br>不不不，<br>我想遇到能一起<br>努力训练的相生伙伴……！<br>那就选能招来全新开始的红色！<br><br>图案就选和人际关系相关的花朵刺绣！<br>嗯！完美♪<br>这样肯定能吸引来最棒的气脉！<br><br>“历奇？你还在选手帕吗？！<br>再不走就要迟到啦！”<br><br>“你之前也因为纠结袜子的颜色什么的<br>差点迟到了吧！”<br><br>“诶，哎呀呀？！都这个时间了！<br>谢谢你，樽前！”<br>Rickey☆Lucky☆<br>向着最棒的一天跑出全力——！"},
{index="20065",text="美丽的晴空、灼热的阳光、<br>微风拂过脸颊的舒畅，<br>以及喝下茶水后的温暖，<br>若是能将这一切都牢牢铭记该多好啊。<br><br>但一切都会随着时间被渐渐淡忘吧。<br>即便记忆没有丝毫褪色，<br>也会被其他更鲜活的记忆所盖过，<br>最终消失不见。<br>所以至少让我记住这个——<br>记住她此刻绽放的笑容吧。<br><br>虽然这只是飞驰而过的日子里<br>一个平淡无奇的瞬间，<br>但这份笑容能够证明这样的时光里，<br>我们也依然在并肩而行……<br>只要还能回想起这份笑容，<br>就算其他的一切都已遗忘，<br>我也相信能像今天一样<br>品尝到同样美味的茶。"},
{index="20066",text="★天才小革的魔法笔记9★<br><br>【Sanidine·Anorthosyenite·Moonstone】<br>唤醒内心干劲的咒语。<br>收集像月光石一样漂亮的石头<br>并借助其中寄宿的魔力而施展的魔法，<br>能让心情变得闪闪发光。<br><br>〈记录〉<br>第●次　△月×日<br>遇到了没能成功帮到别人<br>而心情低落的北部，<br>便对她施了咒语。<br><br>实验对象的感想<br>“我的心真的变暖了！<br>谢谢你，变革前辈！”<br><br>结果：大获成功！<br><br>★天才小革的魔法笔记19★<br><br>【万灵药糖果】<br>用奶奶的秘方精炼而成的魔法糖果，<br>吃了就会恢复精神。<br><br>〈记录〉<br>第●次　□月○日<br>训练结束后，北部背着我跑回了宿舍。<br>我给了她一颗使用奶奶教给我的方法<br>精炼而出的糖果。<br><br>实验对象的感想<br>“好好吃！真是沁人心脾的味道！<br>感觉今天的疲劳全都消失了！<br>谢谢你！<br>变革前辈的魔法<br>总是能让我打起精神来呢！”<br><br>结果：大大大获成功！"},
{index="20067",text="“喂！你要闹到什么时候啊！”<br><br>“Wow，escape！<br>抱歉啦♪”<br><br>刚才还吵吵闹闹的房间慌忙熄了灯，<br>大树一边嬉闹着一边冲了出来。<br><br>（哎呀，原来是在强打精神呢）<br><br>说起来，今天多伯因为参加比赛<br>去关西远征了，所以不在宿舍。<br>她们两人的远征日程几乎碰不到一起，<br>大树常会一个人留在宿舍。<br><br>（真是的……要是觉得寂寞的话，<br>来依靠我不就好了嘛）<br><br>“站住！<br>嘿，逮到你啦！”<br><br>“天啊，真不甘心！<br>菱亚前辈，我已经在反省了！<br>惩罚就No thank you啦——”<br><br>“大树，今天一起睡吗？<br>来我的房间吧。”<br><br>“嗯——！！我要去！<br>今晚可真是太温馨了！！”"},
{index="20068",text="细长的画框中截取了<br>商店街的街景，<br>她在里面露出含蓄的微笑。<br><br>她掌心向上做出托起太阳的动作，<br>笑着说这样有点幼稚。<br>可明明她自己也还只是个孩子。<br><br>压在娇小肩头上的期待、<br>内心深处燃烧的斗志，<br>以及将这些淡淡封存的释然——<br><br>她将这一切尽数包容，<br>露出微笑。<br>正因如此，我才会想——<br><br>这轮太阳……<br>这枚直径约140万公里、<br>世界上最大的金牌，<br>唯有她才配得上。<br><br>我向她祈愿，<br>希望她能一直笑下去。<br>，至少此刻，愿她的笑容天真无邪。<br><br>我向天空祈愿，<br>当她伸手去抓太阳时，<br>但愿我是那个能够保护她柔软的双手<br>不被烈焰灼伤的人。"},
{index="20069",text="＝＝＝＝＝＝＝＝＝<br>〇月×日（△） 天气：阳光灿烂！<br><br>今天的小待呀，<br>和小福前辈还有怒涛一起，<br>给占卜小屋做了一场大扫除。<br><br>金光闪闪的小金鯱和<br>叼着胡萝卜的招财猫<br>都被我们擦得锃锃亮！<br>最后要清洁<br>幸运之壶喽！<br>但是……<br>就在这个时候！！<br><br>（小蜘蛛的画） ←这小家伙（＞＜）！<br><br>把小待吓得大惊失色！<br>同样大惊失色的还有小福前辈<br>以及怒涛！<br><br>一通乱挥的鸡毛掸子直接击中自己的鼻子。<br>眼泪吧嗒吧嗒，鼻血也滴滴答答。<br>真是惨兮兮的一天啊，呜～<br>＝＝＝＝＝＝＝＝＝"},
{index="20070",text="喂，妈妈？<br>好久没联系啦，最近身体好吗？<br><br>我？我刚刚吃完午餐哦，<br>和骏逸她们三个一起吃的。<br><br>骏逸还是老样子，<br>专挑褐色的食物吃，维普露斯<br>只肯吃那些能让她心动的东西。<br>真是的，两个让人头疼的孩子！<br><br>啊，不过请放心。<br>我有好好地让她们把蔬菜和米饭都吃完。<br><br>对维普露斯用了惯例的奖励战术，<br>对骏逸嘛……则是不乖乖吃饭的话<br>就一直追着喂饭。<br><br>呵呵。<br>哎呀，一点都不辛苦啦，<br>毕竟早就习以为常了嘛。<br>而且……<br><br>妈妈你最清楚吧？<br>我呀，最喜欢照顾她们了。"},
{index="20071",text="“几乎要发出悲鸣的内心重新振奋起来。<br>在冲过最终弯道的前一刻，莱斯的耳中<br>真切地听到了重要的人们的呼喊声。”<br><br>（莱斯描绘的场景宛如触手可及一般<br>真切地展现在我眼前……既然如此，<br>这里就特意来一段极弱音吧……<br>在高潮来临前，蓄势是必不可少的啊）<br><br>“一句‘莱斯，加油啊！’<br>使她的内心不再有任何迷惘。”<br><br>（然后从这里切入终段高潮！<br>时机已到！<br>主旋律转为慢板！<br>宏伟壮丽地！）<br><br>“脚踏大地的轰鸣。<br>下一个瞬间，挤满看台的观众们<br>目睹了一道在直线上奔驰的光芒——”<br><br>“太完美了！果然高潮就该是<br>围绕深厚的友谊而展开的正统热血青春剧……<br>感染力依然不曾过时啊。<br>还有万籁……你奏出了最棒的配乐哦！”<br><br>“哪里哪里，我的灵魂为之震颤，<br>让我情不自禁地就想加入进来。<br>多亏了你，我才能孕育出如此美妙的旋律。<br>该道谢的人是我才对，莱斯！”"},
{index="20072",text="大地见证了一切。<br>见证最初的生灵<br>自冰与火的一滴之中诞生；<br><br>见证众神以大树为基石，<br>反复上演着繁荣与纷争，<br>直至迎来黄昏；<br><br>见证世界最终走向毁灭，<br>又再次迎来了新生。<br><br>亦即——<br><br>既然注入了最初的一滴，<br>就去见证它的命运吧。<br>将杯盏打磨至极，<br>如此便能以新的润泽<br>实现重生。<br><br>“好厉害……！闪闪发亮啊！<br>我也要更卖力地擦！”<br><br>“呵，心志可嘉。”<br><br>啊，我们亦是如此。<br>只要将这命运不断打磨，<br>终有一日会迎来新生吧。"},
{index="20073",text="“诶，太阳已经要下山啦，不得了。”<br><br>“放学后的时间过得也太光速了吧？<br>明明感觉熬了超长时间才放学，就很迷”<br><br>“啊？什么？<br>相、对……相对……<br>相对论？”<br><br>“诶，也就是说‘上课感觉像过了一辈子’<br>居然是真的？！<br>这什么鬼啊，简直糟透了嘛——！”<br><br>“这样啊，<br>所以跑步还有闲聊这些事<br>一下就结束了啊”<br><br>“原来如此～学到了——”<br><br>“不过，只要拼尽全力去跑、<br>去聊，不就扯平了嘛！<br>所以，再多陪我一会儿啦♪”"},
{index="20074",text="“打、打扰了！<br>八重姐姐，我是你的粉丝！<br>你总是那么强、那么帅气……<br>我最喜欢你了！”<br><br>“好、好可爱……咳咳。<br>感谢你一直以来的支持。”<br><br>（不好，她实在是太可爱了，<br>害我差点表情松懈了……<br>我必须打起精神来！）<br><br>“无比荣幸！<br>我今后也会继续努力精进，噢！”<br><br>（她夸我“帅气”，<br>这份美好的憧憬——<br>我要守护到底！！哪怕赌上性命！！）<br><br>“哇～好厉害！好帅气！<br>无、比、荣、幸！噢！<br>妈妈！<br>我学得像八重姐姐吗？”<br><br>“呵呵，这孩子真是的，<br>平时在家里也总是在玩<br>模仿八重小姐的游戏呢。”<br><br>“唔……！<br>唔……呜，好可爱……唔唔唔……！”<br><br>“深感荣幸，噢！！”"},
{index="30001",text="“谢、谢谢谢谢大家<br>一、一直以来的热烈资瓷！”<br><br>她口齿不清的样子又可爱又好笑，<br>会场因此爆发出一阵笑声。<br><br>“人、人、人好多……”<br><br>“小特，冷静一点。”<br><br>“不是练习过了嘛，没问题没问题！”<br><br>也许是两人的话让她恢复了冷静，<br>一次深呼吸后，她重新转向前方。<br><br>“为、为了向大家表示感谢，<br>今天我会加油的！”<br><br>话音刚落，会场内响起了热烈的欢呼声。<br>伴随着她的笑容，优胜演出拉开了序幕。"},
{index="30002",text="“其实……之前我有点害怕，<br>不知道应该跟大家说些什么。”<br><br>整个演出会场安静了下来。<br>为了一字不落地倾听<br>独自站在舞台中心的少女所吐露的话语。<br><br>“我……只是喜欢奔跑，<br>除此之外，没有其他兴趣。”<br><br>少女思考、迷茫，同时组织着语言。<br><br>“但是现在，我想用歌声向大家传达我的心意。<br>我感觉，只要让这场演出圆满成功，<br>我就能知道……心怦怦直跳的原因。”<br><br>音乐响起。一次深呼吸后，<br>少女将手伸向前方——答案就在那里。"},
{index="30003",text="“嘿——嘿！虽然音乐还没结束，<br>但是大家先看帝王大人这边♪”<br><br>在舞台边与粉丝互动的<br>东海帝王以轻盈的舞步<br>“跳”上了舞台中心。<br><br>“今天我是第1名，也站上了舞台中心！<br>不管是比赛还是演出，我都是最强的♪<br>今后也永——远如此！”<br><br>耀眼的聚光灯<br>对准了这位少女，而她竖起了3根手指。<br><br>“成为‘无败三冠优俊少女’<br>对我来说根本不在话下！<br>所以大家不要犹豫，跟上我的脚步吧♪”"},
{index="30004",text="黄金船号不需要燃料。<br>如果有趣就会擅自跑起来，腻了就不知道喽。<br>Gold·Ship·1世。<br>（诗人、超级哲学家、魔鬼冒险家/？？？？～）<br><br>“碍事碍事！让开让开——”<br><br>最后直道，那个原本位列队尾的可恶家伙<br>甩着飘逸的银发冲了上去！<br><br>“呀——吼！超过去超过去！”<br><br>使用大胆无畏、出乎意料的瞬间移动后——<br>穿过终点板，达到了北极。<br><br>“哎呀，一不小心超越K点啦！<br>唉，小金船真是个冒失鬼☆”<br><br>下一集是《关东煮！》，一定要来看！"},
{index="30005",text="——说起来，“她”现在在哪？<br>在冲向直道的激烈角逐中，某位选手喃喃道。<br>而此时“她”已将挂好了档。<br><br>“好嘞！现在开始定胜负！”<br><br>伏特加从后方集团中猛地冲了出来，<br>就势迈着轻快的脚步向前追赶，<br>超过了一个又一个选手。<br><br>“嘿嘿……我是第一！”<br><br>忍耐了很久后，逐渐升温的马达<br>以极佳的状态持续加速，最后——<br><br>“这就是伏特加大人，都给我记住了！”<br><br>加速加速再加速，最后获胜。<br>能成为传说的人，永远都是<br>将自己的帅气贯彻到底的人。"},
{index="30006",text="“花即汝心……”<br><br>“喀嚓！”，草上飞拿起被剪下的花，<br>露出了柔和的微笑。<br><br>“有人是这么认为的，<br>用四季的花朵拼出心中最美的姿态，<br>从中便可读出一个人的心。”<br><br>突然，盈满笑意的眼角<br>露出了一丝坚毅。瞄准……<br>插好了最后一朵花。<br><br>“好了……怎么样？希望我这颗心<br>能够让你满意。”<br><br>纤弱却大胆，她的“心”<br>暗藏斗志，凛凛而立。"},
{index="30007",text="神鹰！神鹰！神鹰！<br><br>沐浴着如怒吼般的声援，<br>一道身影出现在舞台上。<br><br>“红方！来自美国！<br>身高163厘米，体重保密！<br>降临在拳击场上的蒙面人，这个人就是——”<br><br>只见她掀起外套……高举拳头！<br><br>“怪鸟！<br>神——鹰——”<br><br>哇啊啊啊——<br><br>“Are You Ready？！蓝方就是你们！<br>准备好开始跳舞了吗？<br>来吧！让心！为之颤抖吧！”"},
{index="30008",text="意识到这一切都是她的策略时，<br>一切都为时已晚了。<br><br>“喵哈哈！我是第一名啦♪”<br><br>为了配合后追选手的步调，<br>青云天空也使出了全力去奔跑。<br>现在是“领跑”优俊少女的“最终直道”。<br><br>“先领跑后摸鱼作战大获成功♪<br>这下就可以悠闲地——”<br><br>“小青……我一定要追上你！”<br><br>“看来不行啊，唉！”<br><br>（不过我从一开始就没打算偷懒。<br>因为我……也想赢！）<br><br>“能追上我的话就追追看吧。<br>可惜云朵无形哦♪”"},
{index="30009",text="“咋样，咱现在状态好得不行！<br>呃……喂喂喂你们看哪儿呢！”<br><br>小小优俊少女拼命蹦跳着。<br>检阅场里的玉藻十字<br>无论怎么闹腾都不太显眼。<br><br>“哎呀，大家往咱这儿看看啊！<br>别因为咱个头小就小看咱！”<br><br>她朝天空全力跳起，<br>总算引起了大家的注意——<br><br>“你们听好了，都小心点！<br>可别被咱的奔跑吓傻了！”<br><br>这些微笑着看着她威吓的观众，<br>即将接受闪电的制裁。"},
{index="30010",text="“哇，好漂亮……”<br><br>全场粉丝随着歌曲摇摆。<br>美妙姿势挥舞的手，<br>自然而然地流露出了高雅的气质。<br><br>（在紧张激动的比赛后，<br>居然还有如此让人激动的事。）<br><br>这是在房间里不曾见过的，<br>超乎她想象的感动……<br><br>（我还想创造更多更多的回忆！<br>在特雷森学园，和大家一起——）<br><br>“跑起来跳起来，笑起来！一起享受吧♪”<br><br>如果想找到带来幸福的四叶草，<br>就要用自己的双脚走向各地！"},
{index="30011",text="哪怕是在微风吹拂的起跑处，<br>艾尼风神也会想到家人。<br><br>“爸爸、妈妈、妹妹们。<br>你们看着吧。我会加油的！”<br><br>起跑冲刺，她全力冲了出去。<br>也许是因为反作用力，她的身体略微向右倾斜。<br><br>（糟了！不过没关系！）<br><br>后脚狠狠地蹬了一下，迅速调整了姿势。<br>下一秒，失误、家人和竞争对手<br>都从脑海中消失了——<br><br>“哈……哈……哈……啊哈哈！”<br><br>她可不是轻柔的微风，<br>她是横扫这片草地的暴风。"},
{index="30012",text="剩余200米，刚刚经过起点的时候，<br>三位挚友相聚了。<br>位于前列的胜利奖券即使不回头<br>也能感觉到身后逐渐逼近的热量。<br><br>“哈……哈……可恶……”<br><br>“唔……奖券……”<br><br>（好开心！好开心！我好开心！<br>我还想和大进还有晨光继续跑下去！）<br><br>但她为了甩开两位挚友，<br>使出了全身的力气并拼命呐喊。<br><br>“呜噢噢噢噢啊啊啊啊！”<br><br>（不想输，不想输，我不会输！<br>因为是那两个人，是挚友，所以！！）<br><br>“我绝对！不会让你们！追上我的！”"},
{index="30013",text="（毫无误差……冲吧！）<br><br>空中神宫气势汹汹地飞奔出去后，<br>场内所有人都发出“又来了”的叹息。<br>她又失控了，这样体力肯定撑不住。<br><br>（这群人的脑子里肯定都是这种肤浅的想法。）<br><br>她保持步伐继续加速，<br>叹息逐渐变成了惊叹。<br><br>（这是当然的。<br>因为我可是反其道而行之，拼命锻炼了耐力啊！）<br><br>不断重复的模拟实验<br>只为导出一个“公式”，然后——<br><br>“证明完毕！蠢——货！”<br><br>出人意料的结果导致场内骂声此起彼伏，<br>只有空中神宫——露出了嘲讽的笑容。"},
{index="30014",text="金色的长发随风飘动，发丝上沾着大大的雨珠。<br>与远远望到的那令人屏息的美貌相反，<br>黄金城现在——全身沾满了泥土。<br><br>“还差……一点点！”<br><br>只要能领跑到底就能获胜的最后冲刺阶段。<br>但是身旁的呼吸声正在逼近，<br>踢起的泥土也毫不留情地扑了过来。<br><br>（啊……好累，双腿好沉重！<br>但是我得坚持！坚持下去我就能赢！）<br><br>这场攻防战容不得丝毫掉以轻心，<br>但是她却一脸愉快。<br><br>（我现在是最佳状态！）<br><br>雨水、泥土和满头的汗水都是身上的饰品。<br>这里就是我绽放光芒的T台！"},
{index="30015",text="“尽情欣赏吧！这就是传说中的<br>班长便当！”<br><br>樱花进王的自信快要从便当盒里溢出来……<br>不对，已经溢出来了。<br><br>“野餐当然要带上三明治！<br>营养和颜色都非常完美吧？”<br><br>像是要附和她一般，面包在摇晃，<br>黄瓜和火腿在跳舞……<br><br>“那就快点大咬一口吧！<br>野餐才刚刚开始！<br>赶紧吃完，或者干脆边吃边跑吧？”<br><br>回过神来的时候，樱花色的眼睛已经凑到了眼前。<br><br>“来吧！在前进中享用吧！”"},
{index="30016",text="来，吃下这颗糖～<br><br>对，就是你。就、是、你♪<br>你一直在看着我，送给你～<br><br>哈哈，你刚才一脸不安呢，<br>是在想我能不能赢吗？<br><br>没事，没事。小栗和小稻，<br>还有其他人……的确都很强，<br>也都是好孩子，但是——<br><br>获胜的人一定是我。<br>所以请你悠哉地看着我吧。<br><br>那么，我要去比赛啦～<br>如果你能乖乖等我的话……<br>回来的时候我就摸摸你的头♪"},
{index="30017",text="“大家，大声喊出来！<br>首先告诉我飞鹰子的优点都有什么吧♪”<br><br>可爱！聪慧！超有毅力！<br><br>“最后那个说什么呢！唉，算了☆<br>接下来让我听听飞鹰子的名字！”<br><br>即使逃跑也很可爱，啊——飞鹰子！<br><br>“嗯，真棒☆ 最后是这个！<br>让飞鹰子听到爱的呼喊吧！”<br><br>L·O·V·E！<br>爱你哦飞鹰子！<br><br>“谢谢大家！飞鹰子一定会<br>成为顶级的优俊偶像！<br>全力追上我吧☆ 啾♪”"},
{index="30018",text="“今、今天我有一些话<br>想对大家说……”<br><br>紧紧抓住麦克风的双手<br>依然显得很稚嫩。<br><br>“谢谢大家<br>一直支持我。<br>虽然我还不够成熟，但是……”<br><br>小小的花朵，绽放了。<br><br>“总有一天，<br>我会成为出色的成熟女性！<br>今后也请一直一直支持我。”<br><br>据说那天的演出结束后，<br>会场各处都有人在低声念叨“我要活久一点”……"},
{index="30019",text="冰淇淋之歌　　　　　演唱者：春乌菈菈<br><br>冰淇淋 冰淇淋 超级棒！<br>冰淇淋娃娃 更加棒！<br><br>用抓手抓上来 摇摇晃晃也不会掉<br>吃了硬币，变大了吗？<br>厉害的 无敌的 超级冰淇淋！<br><br>抱紧冰淇淋就会融化掉<br>但是蹭蹭娃娃也不会化掉<br>（咬一咬 舔一舔 都没有味道！）<br><br>任何 任何冰淇淋都很棒！<br>草莓味 橘子味 还有蜜瓜和葡萄，还有——<br><br>“诶嘿嘿，我想吃冰淇淋了！<br>我们一起去买吧♪”"},
{index="30020",text="“唔唔，演出还不够热闹吗？<br>看来该正义的伙伴出场了！”<br><br>“让我来协助你吧！”<br><br>“啊！这个声音是……”<br><br>“营养满分！正义满分！<br>胡萝卜素注入，胡萝卜侠！<br>以及——”<br><br>“用正义之翼追上邪恶！奔跑吧！展翅吧！<br>拯救世界吧！冲向天际的，微光飞驹！<br>最强的英雄组合，登场！”<br><br>咚——<br><br>“我要守护大家的笑容！<br>现在开始是，正义表演时间！”"},
{index="30021",text="训练员，你辛苦了！<br>我是担任理事长秘书的骏川手纲。<br>从今往后我会全力协助你，<br>有什么问题都可以随时问我♪<br><br>话不多说，这些都是关于我校的资料。<br>开始工作前，请你先过目。<br><br>特雷森学园为优俊少女<br>提供的教育和设施都很完善。<br>当然，我们也有充足的资料<br>帮助训练员学习成长，请你放心！<br><br>我一直很期待<br>和你一起共事。今后，<br>我们一起为优俊少女努力吧！"},
{index="30022",text="“各位，感谢你们的支持！”<br><br>目白麦昆优雅地挥着手。<br>只有额头上的汗水能证明<br>她刚刚结束了一场激战。<br><br>“不过这次的第1名并不是梦想的终点。<br>我会时刻心怀目白家的骄傲，今后也要<br>华丽地赢得更多胜利！”<br><br>听到她的宣言后，场内爆发出了最热烈的欢呼声。<br>结束了符合大小姐身份的发言后，她转过身——<br><br>（我决定了，今天要奖励<br>自己吃一块蛋糕。选什么好呢……）<br><br>她心情愉悦地烦恼着，<br>离去的背影仍然是天真少女的模样。"},
{index="30023",text="（加油啊米浴，加油！）<br><br>希望她获胜的只有一个人。<br>支持自己的只有自己，少女非常肯定。<br><br>“米浴！米浴！米浴！米浴！”<br><br>但是，迎接全力跑完的少女的是，<br>仿佛要冲上高高蓝天一般、<br>热烈无比的欢呼声。<br><br>“啊……那个，呃……”<br><br>少女惊讶、迷惑……但是，<br>小小的少女迈出了大大的一步。<br><br>“谢……谢谢各位！”<br><br>送给少女的欢呼声久久、<br>久久没有停息——"},
{index="30024",text="盯——<br><br>“嗯……以我为原型的娃娃，<br>真可爱啊。”<br><br>这么说来是啊，因为“我”就是<br>获得了很多的爱<br>才会出生的。<br><br>“你们今后会被<br>送到很多人的手里吧。<br>为了被珍惜，为了收获爱。”<br><br>“妈妈，小栗栗好可爱哦。<br>好想抱抱它！”<br><br>“啊……这么快就到你出场了。<br>拜托了哦，另一个‘我’。<br>替我去感受拥抱吧。”<br><br>——包在我身上！"},
{index="30025",text="小特，谢谢你的来信。<br><br>没想到你那么快就迷路了，我很惊讶。<br>唉，你路痴这一点到底是随谁呢……<br>要好好谢谢铃鹿啊。<br><br>能遇到善良的优俊少女是件好事。<br>你们好像成了室友呢，<br>可不能赖床或者把房间搞乱哦。<br>那样会给人家添麻烦的。<br><br>现在说可能有点晚了，其实我一直担心<br>小特在这片没有优俊少女的土地上会不会寂寞。<br>所以，你能交到铃鹿这个朋友<br>妈妈真的非常开心！<br><br>和朋友们一起享受学园生活吧。<br>我会给小特寄你最爱吃的胡萝卜，<br>记得分给铃鹿吃。<br><br>祝小特永远幸福。<br><br>　　　　　　　　　　　　妈妈"},
{index="30026",text="一位少女飞奔着<br>跑到了镜头前。<br><br>“喂，各位！涡轮在这里！<br>喂喂，这个真的在录吗？<br>这样啊！能录上就行！<br>那个，这次的比赛很特别！”<br><br>少女一边说，一边凑近了镜头，<br>闪闪发光的眼睛飞快地眨了几下。<br><br>“所以，今天涡轮也要领跑到底！<br>绝对的绝对！一定要！<br>领跑到底，获得胜利！”<br><br>她的声音明亮且充满希望，<br>让人忘却了比赛的紧张感。<br>吸引了无数人的目光的少女<br>高声喊道：<br><br>“涡轮很强，<br>无论何时，从起点一直到终点<br>涡轮引擎都会全开到底！<br>永远跑在最前面！”<br><br>也许是因为初生牛犊不怕虎，<br>少女喊出了天真的——<br>甚至称得上鲁莽的话语。<br><br>“涡轮不会输！”<br><br>但是这声音像是在鼓励自己，<br>又像是在激励那些<br>止步不前的人一样铿锵有力——<br><br>“所以，一定要看着我！”<br><br>她的声音一直传到了屏幕的另一侧。"},
{index="30027",text="“啊哈哈哈！芜湖起飞！<br>搞不好能赢诶？！”<br><br>欢呼声与笑声交织，<br>还有“又是她们”的无奈眼神。<br>一切都一如既往，<br>都习以为常了——<br><br>（对啊……<br>不管是我们，还是其他任何人，<br>都拥有机会，都存在可能性。）<br><br>脚尖狠狠蹬地。<br>真奇妙……仿佛全身都在高喊，<br>催促我继续加速。<br>这种时候该怎么说来着，<br>好像是“好嘿哟”之类的。<br><br>“哦哦？！善信，哇哇哇！<br>你看起来好嗨哟！”<br><br>啊，就是这个。<br>嗯……现在就是这种感觉。<br>从观众席传来的喧闹声也让人心情舒畅。<br>能赢，向前冲，不要停。<br>全力跑起来吧，我对自己叫喊着。<br>但是说不定，在中途就会耗尽体力——<br><br>“拿下第1吧！！<br>善————信————”<br><br>心中的不安，<br>在听到背后传来的声音后<br>就消失得无影无踪了。<br>在比赛中给对手加油，<br>你到底在想什么啊。<br><br>（谢谢你，太阳神。）<br><br>嗯，热血沸腾起来了。<br>我还能继续跑下去。<br>冲吧，全力冲向前方，<br>提速提速再提速，<br>一直提到极限——<br><br>“看好了，这就是我的大差距领跑！”"},
{index="30028",text="（我就知道你快追上来了，小钻！）<br><br>啊，你果然很厉害。<br><br>可以听到你的呼吸声，<br>蹬地的声音也在逐渐逼近，<br>你如同光彩夺目的宝石，<br>让向前奔跑的我目眩神迷。<br>你总是这样，<br>从来不会给我放松的余地。<br><br>（不会让你超过去的……）<br><br>因为，脚下的道路已经清晰可见。<br><br>那些以咫尺之差输掉比赛的痛苦回忆，<br>现在也还深深地印在我的脑海里。<br>认真奔跑，互相使出全力，<br>以终点为目标奔跑。<br><br>因为痛苦、因为不甘、<br>因为快乐。<br>所以，我绝对不会输。<br>我不想输。<br><br>（但是，果然……）<br><br>快要被追上了。<br>想要获胜的信念，<br>从后方渐渐逼近。<br>强烈的信念化作热浪<br>炙烤着我的后背。<br><br>（嗯……真开心。<br>真开心啊，小钻。）<br><br>差不多要冲上来了吧。<br>你肯定又在笑吧？<br>我知道，因为我也在笑。<br>因为实在是太开心了，<br>想一直笑到最后。<br>所以——<br><br>“比赛还没结束！<br>这次一定是我赢！”"},
{index="30029",text="（如果是小北的话，<br>一定会在前面那里加速吧。）<br><br>啊，果然很棒。<br><br>无论何时何地，<br>那温柔且温暖的背影，<br>都会牵引着我向前。<br>你的头发和衣服仿佛黑影，<br>但奔跑的姿态却如此耀眼。<br><br>（好想超过你……）<br><br>前方的景色，一定更加耀眼。<br><br>我喜欢和你一起追逐梦想，<br>一起笑、一起哭、<br>一起牵着手走路，<br><br>更喜欢兴奋地跑出去后，<br>又突然停下脚步，<br>回头问我“跟上来了吗？”的你。<br><br>（但是，）<br><br>这里是神圣的场所，<br>要遵循礼节，用真挚的态度挑战对手。<br>即使难受、即使痛苦，<br>也要努力奔跑到底。<br>这就是有资格来到这里的人应尽的义务。<br><br>（不过……好开心啊。<br>对吧，小北。）<br><br>你用竭尽全力的侧脸，<br>回了我一个微笑。<br>仅是如此，我就明白<br>我们的心情是相通的。所以我也——<br><br>“这场比赛……我一定会赢！”"},
{index="30030",text="（啊，刚才摆手的动作好像错了？<br>脚也有点酸痛。<br>哦，她们应该要冲刺了！）<br><br>尽管在别人看来<br>非同寻常的努力后，<br>待兼唐怀瑟正在<br>挑战本场比赛。<br>但是她认为——<br><br>（你们两个人的奔跑我看了很多遍。<br>你们的跑法、习惯、以及冲刺时机，<br>我全都调查过了。不过这都是——）<br><br>这都是“正常的努力”罢了。<br>因为想要战胜跑在前方的人，<br>付出这种努力再正常不过。<br><br>（但是，如果想要获胜的话，<br>这种程度是远远不够的。<br>双脚要更加更加用力！）<br><br>我知道比赛很辛苦，<br>也深知获胜绝非易事。<br>但是，这都是理所当然的。<br>为了取胜，<br>我要迈出步伐，追上二人的背影。<br><br>“好！接下来我也要<br>嗖嗖地向前冲啦！”"},
{index="30031",text="小雪儿！加油哇！<br><br>嗯？你问小雪儿是谁？<br>喏，就是那边那个正在挥手的女娃儿！<br>看到她笑，俺的心都要化嘞～<br><br>小雪儿……就像是大家的闺女。<br>她帮俺们耕地，给俺们揉肩膀。<br>不过……最重要的是，她跑步的样子。<br>她跑得那么开心，俺们看着也会振作起来。<br>呜……所以！今天该俺们<br>让那孩子振作起来了！<br><br>诶？你也要为她加油？<br>嘿嘿……眼泪还是留到比赛结束吧！<br><br>好嘞！对了，这次一起说吧！<br>一——二——"},
{index="30032",text="炼技助武道之精进，领畴亦通焉。<br>奔驰、舞跃、歌唱、举止之礼。<br>不练无优，万物皆然。<br><br>彼日，吾于群敌中夺得光荣之冠。<br>居舞台之中央，<br>胜者之荣，亦责任，<br>宜用心对待。<br><br>发声之本，腹也。<br>气沉丹田，力达四梢，立地稳如磐石。<br><br>观客若排山倒海之势，沸腾矣。<br>幕落之际，吾握拳高呼<br><br>“承让！”<br><br>吾友——樱花千代王，<br>惊缩其躯，<br>然观众与演者皆喜笑颜开。<br><br>吾深鞠一礼，遂别离舞台。"},
{index="30033",text="我以为，<br>自己绝——对会哭呢！<br>因为从小时候起，<br>每次光是想像这个场景我都会流眼泪。<br><br>全国德比的，获胜者采访。<br><br>但是真不可思议，<br>真正站在这里的时候，<br>眼泪却一滴也流不出来。<br>因为，我不想忘记。<br>这蔚蓝的天空、<br>无数观众的笑容和欢呼声、<br>和最喜欢的朋友们的全力竞争<br>我要记住这一切！<br><br>如果让泪水模糊了记忆就太可惜了。<br>因为这里是，我们三人约好一起奔跑后，<br>相互鼓励、相互竞争，最后终于<br>抵达的……梦想中的地方！<br><br>“我是在这场<br>最棒的德比中获胜的<br>优俊少女——胜利奖券！”<br><br>而且，实现梦想之后，<br>道路还会延伸到很远很远！"},
{index="30034",text="“那、那个，<br>我们分别从不同的入口进去，<br>然后在里面会合吧？”<br><br>于是两人分头行动，<br>向散发着甘甜香气的<br>玫瑰迷宫的深处前进……<br><br>以上是几十分钟前发生的事。<br><br>少女气喘吁吁地小跑着，<br>无论怎么找都找不到，<br>但是……<br><br>（加油……加油啊米浴！<br>米浴一定要先找到……）<br><br>（就像那一天，<br>那一天就是米浴先找到的！）<br><br>（我一定会找到你！）<br><br>经过转角的一瞬间，<br>少女红扑扑的脸上绽开了笑容。<br><br>“啊……找到了！”"},
{index="30036",text="“事无巨细地规划好比赛生活”<br>对于尚未成熟的她们来说，<br>这是最有效的指导方法。<br><br>“为什么要擅自做<br>训练计划之外的伸展运动？”<br><br>“我太激动了，想冷静一下……<br>对不起，我没能遵从指导。”<br><br>暂时的情绪低落在预料之内。<br>没有必要担心，还有更重要的事。<br><br>“那个，㭴本训练员！<br>简单做做伸展运动应该没什么问题吧？”<br><br>“不，问题很大。<br>‘简单做做’这种想法<br>本身就是错的。”<br><br>“训练、伸展运动、饮食、睡眠……<br>每一方面都要认真对待。”<br><br>我很了解——比赛生活的压力有多大。<br>我很了解——通往梦想的桥有多脆弱。<br>我很了解——没有光芒的道路有多冰冷。<br><br>“好了……以防万一，你再做一次热身吧。<br>今天地下通道有点冷。”<br><br>我会将这种管理坚持下去。<br>这就是……㭴本理子的使命。"},
{index="30037",text="这帝王之路的第一步，<br>是奇迹，抑或是必然——<br><br>震耳欲聋的掌声响彻全场。<br>她悠然地<br>站上表彰区。<br><br>快门声此起彼伏。<br>而她一如既往地<br>摆出威风凛凛的姿势，<br><br>仿佛在说<br>这场胜利早已注定——<br><br>她笔直地<br>将一根手指指向天空。<br><br>“首先，拿下一冠”——<br><br>那声低语被欢呼声所淹没。<br><br>传说，由此开启——"},
{index="30038",text="只有胜者才能进入的场所——表彰区。<br><br>前往表彰区的路上，少女吃惊地瞪大了双眼。<br>这是一次出乎意料的相遇。<br>憧憬的人，就站在自己的面前。<br><br>被无与伦比的脚步所吸引的那一天，<br>她决心要与其比肩。<br>正是这份执着，换来了今天的胜利。<br><br>少女心中思绪万千，怎么都说不出话。<br>憧憬的人迈着如梦似幻的脚步走来，<br>露出了温柔的笑容。<br><br>也许是胜利的余韵让她放松了神经，<br>她的手，帮她系好了松开的腰带。<br>两人距离缩短，少女的脸颊泛出淡淡的红晕。<br><br>盛开的大朵鲜花旁，<br>小小的樱花已经悄然绽放。"},
{index="30039",text="这里是梦之国度——骏想国度。<br>我就是本国的公主。<br><br>今天是期待已久的我和王子结为夫妻的日子。<br>激动不已的全体国民<br>也为我献上了祝福。<br><br>我身着婚纱，站在礼拜堂中。<br>王子正缓缓向我走来。<br>就在我即将握住王子的手的<br>那个瞬间！<br><br>敌方重要干部带着手下突然出现。<br>当然，公主和王子会把<br>坏蛋们打得落花流水！<br><br>身为公主、身为新娘！！<br>幸福要用【自己的力量】来夺取！"},
{index="30040",text="♪buono胡萝卜婚礼蛋糕♪<br><br>＜材料＞<br>面团……<br>胡萝卜　  60根<br>低筋面粉　9kg<br>鸡蛋　　  120个<br>砂糖　　  4.5kg<br>黄油　　  6kg<br>泡打粉　  12大勺<br><br>奶油……<br>奶油乳酪　7.5kg<br>牛奶　　  600ml<br>砂糖　    2kg<br><br>♪多多招待你的朋友们吧♪<br><br>“我倾注了很——多爱，<br>所以特别buono哦♪<br>训练员也来尝尝看～”<br><br>“川上，<br>你说那会是一人份吗？”<br><br>“当然！不愧是菱曙，<br>真是太豪爽了，<br>身为公主，我也要向她学习！”"},
{index="30041",text="很可爱，<br>很美好，<br>很漂亮，<br>但不适合我。<br><br>一直以来我都以此为借口拒绝。<br>因为华丽的东西，<br>总是备受关注。<br><br>但是，我也想前进。<br>我想要为自己感到骄傲，<br>不再畏惧别人的视线。<br><br>所以，这件礼服代表着我的决心，<br>是使我变强的——伙伴。<br><br>总有一天，我要亲口告诉别人，<br>我会成为与礼服相称的人。"},
{index="30042",text="把对手远远甩在后面，<br>冠军手到擒来——开玩笑，<br>我怎么可能这么天真。<br><br>“哼！我就知道你会来！”<br><br>从身旁传来的强大压迫感，<br>使我的后背微微颤抖。<br>不过这只是……<br><br>（只是在兴奋啦！）<br><br>谁也无法妨碍我，这是最棒的瞬间。<br>我一直都在等待这一刻。<br>拒绝一切小手段的一对一，<br>力量之间的正面对决。<br>怎么可能不热血沸腾？<br><br>“上吧。”<br><br>连观众的喧闹都被盖下的低语，<br>让我倒吸了一口气。<br>来吧，好戏才刚刚开始。<br>堂堂正正地……<br><br>“一决胜负吧！”"},
{index="30043",text="是白，还是黑。<br>是胜利，还是失败。<br><br>投出硬币，就会出现正反面。<br>比赛也是一样，<br>只要开始便会决出胜负。<br>但大舞台之上，<br>存在各式各样稍显麻烦的因素。<br>希望谁获胜，谁是第一优俊少女。<br>此起彼伏的喧闹声不绝于耳。<br><br>因为是人气第一，<br>因为惹人喜爱。<br>因为大家都相信她能够取胜——<br>喂喂，等等啊！<br>不因为这些因素决出第1名的才叫比赛吧？<br><br>骰子已掷出，胜利女神会向谁微笑呢？<br>时间仅剩2分有余，<br>愉快又激烈的角逐将会上演。<br><br>好了……专注于眼前的事吧。<br>开幕号乐，即将响起。"},
{index="30044",text="欢呼声消失了……好安静。<br>听不到任何声音。<br><br>“姐姐，等等我呀！”<br><br>刚才跑过去的是？<br>啊……是那个时候的我。<br><br>那就跑得更快些吧。<br>不停地跑下去，直到追上她。<br><br>“姐姐，你跑不动了吗？”<br><br>即使如此你也要跑下去。<br>望着前方，不顾一切地、<br>满怀信心地前进吧。这样的话——<br><br>“这次我们也要……”<br><br>“一起奔跑吧，姐。”<br><br>“嗯，好啊。白仁！”<br><br>“现在，选手均已就位，<br>现在……比赛开始！”"},
{index="30045",text="（吸吸吸……）<br><br>“嗯♪这个果汁好甜，<br>还有气泡感，真好喝♪”<br><br>（偷瞄）<br><br>“哼哼，你肯定也想喝吧？<br>但是我绝——对不会给你喝的♪”<br><br>（吸吸，吸……）<br><br>“啊～快要喝光了！<br>你居然品尝不到这等美味，真是太可怜了！”<br><br>（吸，吸……）<br><br>“我说，你很想喝吧？<br>那就说出来啊！”<br><br>（……）<br><br>“哼哼，真拿你没办法♪<br>喏，给你一个吸管。”<br><br>（吸管插入，冰块晃动）<br><br>“要努力喝哦？<br>不过里面只剩下冰块了！噗噗♪”"},
{index="30046",text="“呀吼——”<br><br>胜利奖券踩着滑水板，<br>一脸轻松地上下翻飞着。<br>船体随着她的动作左右摇晃。<br><br>“忒、忒厉害嘞……”<br><br>“不是说那个动作<br>初学者做不了吗？<br>不愧是奖券前辈！”<br><br>“唔，这就是野生动物的直觉吧……<br><br>“太棒了～<br>再来一次！”<br><br>“哎呀！真有气势♪<br>小奖券，这回翻两圈吧♪”<br><br>交给我吧！<br>冲呀，这就是我的——”<br><br>船上传来女孩们的欢呼声，<br>就像滑水板溅起的水花一般耀眼。"},
{index="30047",text="“诶？诶？诶？诶诶诶？！<br>为什么我在最前面啊啊啊？！”<br><br>（我的确经常跑在前面，<br>但是那只是我的习惯，<br>不用这么客气啦！）<br><br>“等下，小特前辈！那是我的尾巴！<br>不要握得那么紧……啊啊啊啊啊啊！”<br><br>“诶诶诶诶，丸善前辈，<br>你为什么要摆pose……<br>难道我们会被拍照？！”<br><br>（哇哇哇，不要啊，<br>这种姿势，如果被那家伙看到的话！）<br><br>“啊……啊啊啊啊……<br>我绝对无法忍受啊！”<br><br>（咔嚓☆）<br><br>“啊啊啊啊！”"},
{index="30048",text="“最后一枚是……外角偏低的7号板。<br>这个有点难呢。<br>不过只要放松下来，<br>正确地运用肌肉的话……没问题！”<br><br>“听好了三角肌，不能胡乱用力，<br>在发球前要积累能量。<br>比目鱼肌也要加油，稳住身体轴心！<br>好……大家，拜托了！”<br><br>“打中吧！”<br><br>（咻砰——）<br><br>（铃铃铃♪<br>噔，噔蹬，蹬，蹬，蹬蹬蹬，蹬♪）<br><br>“成功了！全打中了！<br>我的肌肉们，感谢你们的理想发挥！<br>等下喝点蛋白粉吧！”<br><br>Welcome to 2nd stage！<br>Are You Ready？<br><br>“诶，还没结束吗？！<br>哼哼，就该这样！<br>大家，我们继续吧！”"},
{index="30052",text="能传达到吗？<br>有传达到吗？<br><br>我们的心跳，化作旋律。<br>我们的泪水，化作色彩。<br><br>这些，最终都只能归于阴影之中。<br><br>我……一直都想告诉你。<br>那时，我有话没能说出口。<br><br>所以，这一次……我一定要传达给你。<br>就像你在赛场上展示给我的那样。<br>我也要在这个舞台上，传达给你。<br><br>有传达到吗——"},
{index="30053",text="正午时分，尘土飞扬的决斗场上。<br>以技术……<br>不，是以腿脚为傲的游侠们正在对峙。<br>这时，又有一位豪士加入了进来。<br><br>“Oops！<br>大家看起来都好厉害呀！”<br><br>开朗到格格不入的声音回荡在荒野之上。<br>这家伙没什么大不了的。<br>就当每个人都在心里这么想的时候——<br><br>“But……赢的会是我。<br>我会一枪就解决掉你们的♪<br>Are you ready？”<br><br>她的宣战就像快枪手一般。<br>被射中的对手们恍然大悟，<br>称霸这片荒野的……是她。"},
{index="30054",text="无论付出了多少努力，<br>无论吃过多少苦，<br>永远都是结果决定一切。<br><br>获胜的主角总是散发着光芒。<br>对输掉的配角而言，那光芒实在是太过耀眼。<br><br>努力总是得不到回报，<br>与梦想失之交臂。<br>这就是现实，<br><br>我早就知道的。<br>我早就知道，但我并不想知道。<br><br>“哈哈……真是，好笑啊。”<br><br>反正，我还会跑下去。<br>梦想着有一天，自己也能绽放光芒。"},
{index="30055",text="震撼空气，招来暗云，将天空染成了<br>炼狱一般的颜色的那位施术者，<br>正是利用森罗万象之理破解万物本源之人。<br><br>驱动遮云蔽日的无数血泪，<br>使哭喊声在布满锈迹的虚空中回响，<br>她亦是远超人智的神罚的代行者。<br><br>在此记下她的名字，<br>这位使万物颤抖、万物回归的红色使徒名为——<br>“血云天空”。<br><br>发行　黄金出版社<br><br>《全明星集結！优俊王之军名簿》<br>“嗯……是不是有点夸张？<br>反正是宣传，夸张点应该没问题吧。”<br><br>“如果能给人留下‘我很强大’的印象，<br>她们说不定就会躲着我了♪”"},
{index="30056",text="“明亮耀眼的枝形吊灯、<br>金丝刺绣的地毯、豪华至极的装饰。<br>全都是荣华富贵的象征……但是，<br>这些都不是使舞会会场跃升为一流的原因。<br><br>“原因是不死鸟的羽毛？黄金蟹的标本？<br>天马的穹顶壁画？还是太阳的雕像？<br>不，都不是。<br>让整个舞会会场跃升一流的原因……那就是——”<br><br>“King Of Gorgeous！”<br><br>“有我在的地方，就是一流的空间！<br><br>“King Of Magic！”<br><br>“我的名声享誉世界！<br>没错，我就是——”<br><br>“King Of Kings！”<br><br>“哦——呵呵呵呵！<br>感谢名为“帝王”的存在吧！”"},
{index="30057",text="世纪末美食！<br>稻种烩饭的作法！<br><br>“首先让NPC把稻种拿过来！<br>这就是所谓的年贡。<br>这是考点，可给我记好喽！”<br>“然后用火（flame）翻炒稻种！<br>凭借优俊王的魔力，低级魔术<br>也会变成将万物烧成灰烬的业火！”<br><br>“嗯？喂！材料怎么没了？！<br>我的力量也太可怕了吧……真是的。<br>把新材料拿来，继续！”<br><br>“用适当的火力翻炒后，<br>放入清汤煮个20分钟左右，然后就完成啦！<br>可以根据个人口味再添稻种！”<br><br>“好嘞！散发着优俊大陆的<br>未来和希望的味道的稻种烩饭完成啦！”<br><br>“给，你尝尝。<br>是不是对白米再也提不起兴趣啦？<br>嘎——哈哈哈哈！<br>这下你也是优俊王之军的一员了！”"},
{index="30058",text="不管是天涯，<br>还是海角。<br><br>“我不会输给任何人。”<br><br>“我一定会获得胜利。”<br><br>飞往每一个角落，<br>奔向每一寸土地。<br><br>“将你甩在身后，向前跑去。”<br><br>“目不转睛地望着终点。”<br><br>这是——<br><br>“你就在我的身后伴舞吧。”<br><br>“输了可不要哭鼻子哦。”<br><br>追逐闪耀的，<br>优俊少女们的故事。"},
{index="30059",text="献给一个人的祝福，<br>对另一个人来说就是叹息。<br><br>“呜呜呜……怎、怎、怎么办。我一看到<br>摄像机，就忍不住紧张……一直在发抖……”<br><br>“那么，请允许我触摸你的背部。<br>根据存储在脑内的相关资料，<br>‘温暖’可以缓和紧张的情绪。”<br><br>“但是……如果和米浴离得太近，<br>可能会发生不好的事……”<br><br>“否定。电子设备以外的物体<br>随时都可以和我接触。因此……<br>为了完成拍摄工作，转为劝说模式。<br>即将参照劝说手册进行劝说——”<br><br>“米浴，<br>‘别啰嗦了，快靠过来！’，结束。”<br><br>“好、好的！诶、诶、诶！<br>哇……波旁好暖和。<br>诶嘿嘿……我真的不抖了呢。”<br><br>“米浴也很温暖。<br>因为热量，已经扩散到了内部。”<br><br>“即便如此”，我们说道，<br>“我们也要共同承担，挑战者的勋章。”"},
{index="30060",text="是礼裙、装饰品、还是聚光灯？<br>让她们散发出最耀眼的光芒的是——<br><br>“嗯，很可爱嘛♪<br>涡轮，胸花戴好啦～”<br><br>“哦哦！素质，好厉害！”<br><br>“你们两位准备得……也非常完美呢。<br>摄影差不多该开始了。”<br><br>“噢噢！唐怀瑟和生野<br>很适合穿礼服呢……嗯嗯♪”<br><br>“嘿嘿♪素质也很漂亮！”<br><br>“漂？！不、不要说恭维话啦！<br>好了，我们快拍吧！”<br><br>“好！大家，集——合——啦——”<br><br>星星一颗接一颗地连接在一起。<br>大家聚在一起，就是最耀眼的光芒。"},
{index="30061",text="相互竞争的脚步声，<br>变成了和谐的旋律。<br><br>（哒哒哒哒哒！）<br><br>“呜哇……是礼服！<br>拍照的时候要穿这个吗？！现在我有一种<br>跃跃欲试？激动不已？的感觉！”<br><br>（嗒，嗒，嗒）<br><br>“就穿平常那身呗，<br>不就是一身衣服的差别吗？”<br><br>（咚，咚）<br><br>“没错，礼服不过是点缀。<br>向支持自己的人展现<br>日常的姿态才是最重要的。”<br><br>“这样啊，日常……<br>那一一我们来比比看，<br>谁能第一个到达摄影棚吧——”<br><br>“诶，等等——”<br><br>“哈哈，这的确是我们的日常状态。<br>好，我们也跟上吧！”<br><br>“唉，好吧！”<br><br>（哒，哒，哒！）<br>（哒，哒，哒！）<br>（哒，哒，哒！<br><br>下摆轻轻飞舞，三个脚步声重叠，<br>声音无比悦耳，仿佛一首合奏曲。"},
{index="30062",text="“嗅嗅……哇……好香的味道。<br>这就是传说中的便当——胡萝卜盒饭……”<br><br>“小特，便当留到<br>排练结束后再吃吧。”<br><br>铃鹿！你看到我的手套了吗？<br><br>我记得你说想再改一改，<br>然后把它交给服装师了吧？”<br><br>后台里热闹非凡，<br>一刻都不能放松。<br>但是一一<br><br>我觉得这种感觉很棒。<br><br>“可能是因为身旁有你们在吧。”<br><br>“铃一一鹿一一”<br><br>“我听到了，小特。<br><br>呵呵，真是的。又怎么啦？”<br><br>为了完成这个承载了众多祝福的舞台，<br>我们要加油准备了。"},
{index="30063",text="跑鞋订单<br>·单号No.0723586<br>——————————<br>“姓名”<br>目白麦昆<br><br>“尺寸”<br>根据测量值以0.1毫米为单位调整<br>“鞋底指定使用材质”<br>UMAGANE股份有限公司制铝合金<br><br>“其他需求”<br>希望把鞋底更换成比75g样品更重的80g同款。<br>由于想增加负荷，<br>所以请把鞋底前端增厚。<br><br>此种跑鞋会频繁在平时的训练中使用，<br>因此请准备一打同款的跑鞋。<br>我会在今天再次造访时领取成品。<br><br>“麦昆的跑鞋订好了。<br>这样的定制应该是最佳方案。”<br><br>“哎呀，太感谢了！<br>配合我的条件调整重量之类的内容，<br>你对我观察得真细致啊！”<br><br>“毕竟对于优俊少女而言，<br>跑鞋可能会改变自己的未来，<br>是不可或缺的搭档。<br>所以我花了不少心思。”<br><br>“是啊，感觉这一定会是一双很好的跑鞋。<br>呵呵……我已经等不及想看看成品了！”<br><br>“我也……很期待”。"},
{index="30064",text="呜嗷呜嗷——！！<br>三具惊悚的木乃伊……！<br>终于醒来啦……<br><br>“飞毛腿庆典优俊少女”——<br>胡说八道木乃伊·稻荷！<br><br>“用绷带包裹一切的甜蜜沼泽”——<br>母乃伊·the·溪流！<br><br>然后是咱！“大阪最快”——<br>白色闪电·玉藻木乃伊！<br><br>为啥这么叫呢？因为跑得太快了，随风飘动的绷带<br>看起来就像闪电一样！<br>咋样？帅吧！<br><br>好了……木乃伊猎人·小栗——<br>你能战胜咱们吗？！<br><br>不是，你怎么在悠闲地啃南瓜派啊？！结果我说的你啥也没听见啊？！<br><br>咱可是好不容易才调动起情绪……<br>啥？让咱再说一遍？<br>说个头啊！太丢人了吧！"},
{index="30065",text="万圣节妖气满盈之时，<br>一位少女造访了传说中魔女的住处。<br><br>魔女像是试探她一样微微一笑。<br><br>“我这里的修行可没那么简单哦？”<br><br>“即便如此，我也有<br>无论如何都想实现的愿望！”<br><br>魔女本以为少女会知难而退，<br>可是她并没有气馁。不久，<br>魔女便给予了认可，并将魔杖赐予了她……<br><br>“请等等我。<br>这次，该由我来助你一臂之力了——”<br><br>她拥有帮助朋友、感动魔女的胆识。<br>她正是那个值得被称为小英雄的孩子。"},
{index="30066",text="那位幽灵小姐背对着我，<br>一动不动地站着。<br><br>幽灵小姐为了尽到自己的职责<br>一直一个人默默地努力着。<br>幽灵小姐是一位非常非常认真的人。<br><br>明明向别人寻求帮助<br>也不算是失败……<br><br>“……”<br><br>幽灵小姐一点一点地，<br>向我敞开了心扉。<br><br>听我说呀，你发现了吗？<br>正因为你那么温柔，我才会烦恼呀。——<br><br>摘自某手制图画书<br>《幽灵小姐与吸血鬼的万圣节》。"},
{index="30067",text="坐在王座上的，是立于一切顶点的<br>“皇帝”鲁道夫象征。<br>那庄严的身姿，展现出了无与伦比的风范。<br><br>有两位优俊少女被她的威光所吸引。<br>一位是拥有卓越的感性和才能、<br>以无敌为目标的东海帝王。<br>另一位是凭借强大的潜力和坚韧的意志力<br>勇往直前的鹤丸强志。<br><br>“我一定会超越你。”<br>“我绝对不会放弃。”<br><br>面对二人展现出的气势，“皇帝”微微眯起了眼。<br>她的双眸中映照的未来，正绽放着璀璨的光芒。"},
{index="30068",text="要将衣袖大幅挥舞，划出半月般的弧线……<br>彩排时已经确认过灯光的位置，<br>这个角度最能让妆容显得闪闪动人——<br><br>“嗯嗯，真不错呀♪”<br><br>这是在我心中描绘出的，<br>最可爱的机伶。<br><br>大家期待着看到这样的我，呼唤着这样的我，<br>所以我现在才会站在这里。<br><br>化了比平时更加艳丽的妆，<br>是热切期待着庆典的喧嚣<br>以及想回应大家期待的表现。<br><br>不过……不，正因如此才更要——<br><br>“让大家见识一下，超越所有人期望的可爱机伶！”"},
{index="30069",text="小小的火光摇曳着，让人情绪高涨。<br>沸腾的热血使一切杂音和思考都停了下来。<br><br>能感受到的唯有难以抑制的剧烈心跳。<br>如果强加抑制，<br>就会立刻被一股窒息感所折磨。<br><br>那就任由它跳动、任由它贪婪、<br>任由它渴望、任由它追寻——<br><br>唯有受尽煎熬后，将其吞噬殆尽！<br><br>“时间到了。走吧，白仁！”<br><br>“嗯……猎物已经逃不出我的手掌心了。”"},
{index="30070",text="舞者们伴随着轻盈的旋律舞动身姿。<br>跟着节拍，扇子旋动，<br>一轮缺月正挂在夜空之中。<br><br>“嘿，嘿哟！”<br>灯笼的光芒闪耀夺目，<br>映得观众的眼睛熠熠生辉。<br>翩翩起舞的那名少女，<br>却望着更遥远的地方。<br><br>（做得很好……不过，<br>这样和以前的我可没两样呀！）<br><br>“得再……再努力些！”<br><br>“雪之的舞步变快了呢♪<br>好，那机伶也得加把劲！”<br><br>“两个人都提速了——<br>嗯，我也要跟上……！”<br><br>追赶、赶超，旋律也渐渐变快。<br>随着少女们的舞步，<br>庆典氛围愈发浓郁。<br><br>“好戏才刚开始！<br>我也是庆典的主角！”<br><br>大家欢声笑语，动作不止。<br>今宵舞台上，祝庆久不息。<br>热闹繁华里，不负花都名……"},
{index="30071",text="“华丽登场！<br>D——J——就……<br>是——我——！！”<br><br>＼耶耶耶耶耶耶耶！！／<br><br>“不得了～☆这股气势，全场最赞啦！<br>大家嗨起来，摇起来！<br>来做平时的互动……<br>来吗？要来喽！绝不绝？！～”<br><br>＼绝了绝了～／<br><br>“OKOK♪<br>嗨起来嗨起来嗨起来——！<br>那从右侧开始……嗨翻天？！”<br><br>＼嗨翻天！／<br><br>“左侧的观众～嗨翻天？！”<br><br>＼嗨翻天！！／<br><br>“中间！嗨翻天～☆”<br><br>＼嗨翻天——！！／<br><br>“在场的一起！嗨翻天？！”<br><br>＼嗨翻天——！！／<br><br>“好棒～☆棒极了太棒了！<br>真是的～我都要爱上大家了♪<br>不对，是已经爱上了！早就爱死啦！<br><br>那么，今天就一起嗨到最后吧！<br>超强超棒的演唱会，开始喽～☆”"},
{index="30072",text="今天是特别开心的日子！<br>是把大家的欢欣雀跃装进盒子，<br>再系上亮闪闪的丝带的日子。<br><br>“训练员，这里这里！<br>我们的派对很厉害吧！”<br><br>这个笑容足以吹散冬日的严寒！<br>这片欢声毫不在意雪天的寂静！<br>这场欢乐明快的派对不负闪耀的星空！<br><br>多么美妙又特别的景象啊！<br><br>“快乐吧？开心吧？<br>所以我才想让训练员看到呀！”<br><br>想让你看到，想被你夸奖，想让你高兴。<br>虽然这样挺孩子气的，<br>或许和“成熟女性”有点不同……<br><br>但是，<br>不管怎么说，今天都是圣诞节！<br><br>在这个特别的日子，将这最高级的特别待遇……<br>系上最可爱的丝带，<br><br>当作礼物<br>送给特别的你，可以吧？"},
{index="30073",text="你走在倒映繁星的石板路上。<br>在一步半左右的前方，匆匆忙忙，好像生气了一样。<br><br>人头攒动的集市里，<br>那双纤细的腿如同穿针引线般，<br>利落地划开嘈杂的人群。<br><br>商铺门口霓虹流转，<br>陈列的商品光彩夺目。<br>香甜的热巧克力飘出热气，<br>有肉桂的香味氤氲其中，温暖了这个夜晚。<br><br>在这冬日的喧嚣中，<br>正是多亏了你自己，我才没有跟丢你那小小的肩膀。<br><br>“干什么呢！可别走散了。”<br><br>你回过头，冷淡地说道。<br>看到我点了点头，你又立刻转向前方。<br>仅仅领先一步半，不近也不远。<br>你一边细心留意着距离一边走着。<br><br>我在后面跟着，<br>装作没注意到你时不时回望的视线。<br>因为一旦被你发现，<br>这神圣的一步半将消失不见。<br><br>你在圣诞前夜的月光下前行。<br>仅仅领先一步半，比任何人都温柔、谨慎地前行。"},
{index="30074",text="“是雪呀～☆★<br>重炮快看快看，一片洁白耶～！”<br><br>“哇～♡<br>下了好多雪呀美丽亲，玩点什么好呢？”<br><br>“我们先marvelous地打雪仗吧☆<br>我扔～★”<br><br>“哎呀，好凉！<br>好，重炮要反击了哦☆”<br><br>“不会输给你的！<br>接招，marvelous☆★”<br><br>～三个小时后～<br><br>“呼～☆<br>真是marvelous的一场雪仗呀……★”<br><br>“是呀，美丽亲！<br>不过好像有点玩过头了～”<br><br>“玩‘过头了’？<br>才没有才没有！”<br><br>“诶～我们已经玩很久了哦！”<br><br>“可是可是，<br>雪是会消失的吧！”<br><br>“嗯，到了春天就会化掉。”<br><br>“那样的话，趁现在、现在、现在！<br>必须要‘现在’玩！<br>我想把这marvelous的一瞬间<br>不断延长……<br>让我们更加更——加marvelous地玩吧☆★”<br><br>“确实，有道理？！<br>好～重炮也要继续玩起来☆”<br><br>“啊哈哈哈哈！<br>直到雪化掉都要marvelous☆<br>这样的话，<br>即使雪化了也marvelous★<br>无论春夏秋冬！<br>遍布世界吧marvelous☆★☆”"},
{index="30075",text="跑啊跑啊跑。<br>还不够，还不足以追上她。<br>还不够，还不足以超越一切。<br><br>转啊转啊转。<br>上升，又下降。<br>思绪不停地循环往复，<br>不知不觉，我已站在了色彩斑斓的齿轮之上。<br><br>优美的歌声已然消逝，<br>那并非为我所唱。<br>只是，前进的意志亦消逝而去。<br>我所注视的并非前方，<br>而是她的背影。<br><br>啊，我只能看到她的背影，<br>只能看着她的背影。<br>只有朝着那摇曳的背影，<br>奋不顾身地奔跑。<br><br>我这个生物<br>被搅拌，被稀释，被重组，<br>变成了一个只为追上她的齿轮。<br>渐渐地，我忘记了自己是谁，<br>为什么会在这里。<br>喧嚣甚远，<br>以至于不知道那是欢呼还是怒吼。<br><br>在这被搅得一塌糊涂的世界中，<br>只有追逐她这一条细若游丝的道路，<br>永远那么寂静。<br><br>（我在追逐着你。<br>也只会一直追逐你——！）<br><br>黄金齿轮在转动。<br>我伸出手想要触碰她——<br><br>那一瞬间，<br>我将全世界都抛在了脑后。"},
{index="30076",text="只要闭上眼，脑海中就会浮现出这样的景色——<br><br>落日余晖，<br>几个身影向着光芒渐行渐远。<br>伫立的我，听到了远方某人的声音。<br><br>我是什么时候看到的呢……<br>我努力地追溯着回忆，<br>却始终无法想起……<br><br>所以……这一定是梦。<br>因为我不想再这样下去，<br>才会在潜意识中描绘出这样的噩梦。<br><br>为什么能这么肯定呢？<br><br>因为我无论何时睁开眼，<br>都会看到不同的景色——<br><br>“无声铃鹿！<br>又一次第一个冲过终点，实至名归！！”<br><br>我想看到的，不是梦，<br>更不是噩梦……<br><br>我——<br>还想看到未曾见过的景色。<br><br>现在是，以后也是，永远都会是！"},
{index="30077",text="“噢噢，难以置信！<br>这让我欲罢不能的美！<br>难道你就是我的莱博雷洛吗！”<br><br>“唔唔！织姬身穿的振袖和服，<br>花纹和我在梦里预知到的一模一样！<br>这是幸运福神的指引！<br>是白兴大人的指引！”<br><br>“啊哈哈哈！织姬真漂亮！<br>我知道了，你吃了很多年糕吧？<br>怪不得皮肤那么富有弹性！之后一起去打年糕吧！”<br><br>“新年伊始就这么吵啊……<br>唉，今年可怎么得了……”<br><br>“哇哇哇哇！对、对不起～<br>我跌倒了就会和滚雪球一样停不下来！<br>让一下让一下——”<br><br>“诶！别、别过来！”"},
{index="30078",text="“歌、歌牌大赛就要开始了！<br>哇哇哇哇！我、我抖个不停！<br>怎怎怎、怎么办啊！”<br><br>“别担心，怒涛！<br>只要边唱边跳白兴大人创作的<br>《新春招福之歌》，就能鸿运当头、万事如意！”<br><br>“出门见喜福来临♪<br>元旦太阳升♪<br>富士双颊红通通，山也笑盈盈♪<br>天灵灵，地灵灵，福气随你行♪”<br><br>“天灵灵、地灵灵～诶嘿嘿。<br>啊，不经意间就哼起来了～”<br><br>“没错没错，就是这样！<br>来吧来吧，大家一起～”<br><br>“灯笼挂起好运迎，大家欢笑不停息♪<br>雄鹰鸣，梦报喜，新年迎喜气♪<br>天灵灵，地灵灵，福气随你行♪”<br><br>“吉祥年菜饱口福♪<br>幸福美满唤胜利♪<br>茄子别烤放袋里♪<br>天灵灵，地灵灵，福气随你行♪”<br><br>“这样白兴大人就会好好保佑我们！<br>一定会一帆风顺……不，<br>一定会宝船兴航的，你就放心吧～”"},
{index="30079",text="无法触及的东西有很多。<br>巨大又耀眼的憧憬……<br>在无比遥远的顶峰处昂首挺胸的自己。<br><br>明知爬上去就能重获新生……<br>却完全做不到。<br><br>所以，就努力踮踮脚吧。<br>不会有人发现、稍微一点的那种程度。<br>随后，有人在身后推了我一下。<br><br>我想回头却并没有回头，<br>反而更努力地踮起了脚。<br>背后特别特别温暖……<br>不知何时，我喊了出来：<br><br>“我我、我，要触及到呀啊啊啊啊——！！”"},
{index="30080",text="“这是……从师父那里<br>（擅自）借来的针灸师秘笈！<br>哇哦，是这里吧☆<br>我好像只看了一半……我瞧瞧”<br><br>一、应探求优俊少女的奥秘<br>二、应将针灸术融会贯通<br>三、应知道经验胜过天赋<br>四、应苦心磨砺不得沉溺于世俗<br>五、应把针灸作为心灵之窗<br><br>“啊，不好！<br>为了吃泡面煮热水的火还开着！<br>得快点倒进去……<br>有没有什么能压住的东西……”<br><br>“这不就有个好东西嘛！<br>不愧是秘笈！这么厚正适合拿来压住！<br>哇哦，安～心☆”<br><br>三分钟后，安心泽刺刺美因为<br>将泡面洒在了秘笈上而陷入慌乱。"},
{index="30081",text="“噢，是那次拍的照片啊！<br>诶……这个影子是什么……<br>难道是鮟鱇鱼的幽灵？！”<br><br>“呀……哪里，在哪里？<br>鮟鮟、鮟鱇鱼的幽灵在哪里……”<br><br>“米浴，冷静一下。<br>黄金船的话可不能全都当真。”<br><br>“呜噢噢噢噢！回想起当时的感动了！<br>眼泪止不住了啊！”<br><br>“那时候你哭得够多的了吧。<br>你的泪腺是什么构造啊？”<br><br>“啊哈哈哈～啊！对了！<br>也得给铃鹿看看呢！”<br><br>“我就知道你会这么说，<br>所以我把照片的电子版也要来了。<br>呵呵……经历了那么多激战，<br>大家还是一点没变呢。”<br><br>“没错没错！＜天狼星＞的氛围和往常一样，<br>感觉真是太棒了！”<br><br>“是、是啊……米浴也觉得，<br>什么都没变的感觉也不错呀……诶嘿嘿。”<br><br>“哼……确实，也不赖。”<br><br>“是的，没错！<br>所以我们……＜天狼星＞队，<br>今后也要好好相处——”<br><br>“团结一心，努力加油，耶！！”<br><br>“为、为什么要拍下来啊！！”"},
{index="30082",text="一份小小的勇气，<br>和稍稍向前迈进的心思，<br>才是最重要的。<br><br>把这些都混合在一起，<br>细心烘培，轻轻包好，<br>再系上丝带就完成了。<br><br>之后微微抬起头……<br><br>“请问……你愿意收下吗？”<br><br>展现出自己最美好的微笑。<br>虽然手还有些颤抖，<br><br>但是我想传达的这份心意，<br>希望你能感受到。"},
{index="30083",text="“面粉！！黄油！！面粉！！<br>黄油！！奶油！！奶油！！”<br><br>无论食谱，还是温度，都不算什么。<br>在她面前这些都毫无意义。<br>只追求极速，唯有极速。<br><br>“呜哇，眼睛鼻子嘴都蹭上了奶油！！<br>嗯～非常好吃！！”<br><br>“接下来是最后的点缀了！<br>樱花、樱花、樱花——！！”<br><br>樱花风暴绚烂而起，极速盛开，<br>将厨房染成了一片粉色。<br><br>“好！！大功告成！！<br>这就是前进式烘培！！<br>世界上做得最快的甜品！！”<br><br>如果她一脸满足地递来蛋糕，<br>谁都会忍不住笑着收下吧。<br><br>虽说她手上沾着奶油，<br>衣服上沾着樱花……<br>可这个样子也十分惹人喜爱。<br><br>“哈——哈哈哈！！你的表情！！<br>嗯！嗯！我明白！！<br>一定十分满意对吧！！”"},
{index="30084",text="“那个，手是要……这样吗？”<br><br>“嗯，不错。<br>就先保持这样不要动哦——”<br><br>虽然不知道这种玩法<br>适不适合小花就是了。<br><br>我总是劲头满满，<br>说不出什么好话，<br>也不知道怎么鼓励别人。<br><br>可我还是没办法对人置之不理……<br>想着总得做些什么。<br><br>所以如果用我的方式<br>能让她开心起来就太走运啦。<br><br>“哇，好漂亮！<br>有种变成大姐姐的感觉了呢！”<br><br>“真的？你喜欢吗？”<br><br>“嗯！真好看！”<br><br>嘻，好耶。<br><br>这就叫干了就是赚了吧？<br>虽然我不擅长思考，<br>但是只要下手干，事情总能解决的，对吧！"},
{index="30085",text="在某位人气优俊偶像的签名会上，<br>爱丽数码攥着新专辑，排在队伍的最后……<br><br>“等、等一下，糟糕！<br>那位浑身发出圣光，都看不见人了！<br>口牙呀呀呀呀！！”<br><br>“我们身处同一个空间呼吸着同一片空气？！<br>感谢上苍，感谢父母！”<br><br>“呼啊啊啊～<br>顺序在一点点向前！<br>哇哇，比封面上的还要美腻！”<br><br>“好险！差点就升天了！<br>这是怎样的‘神圣领域’啊！<br>我的偶像……她人就在那里！”<br><br>“啊！冷静一点小数码！<br>现在可不是浮想联翩的时候！<br>必须好好脑内模拟一下！”<br><br>“要自然而然，不能给人留下印象……<br>向她要来签名→说‘我一直很支持你’→<br>迅速换到下一位……好！”<br><br>“如果在这里违反了规矩，<br>签名会本身也可能不保吧……<br>我要向我的偶像，对于她能来到这里，<br>致以最深的谢意！我去了！”<br><br>爱丽数码潇洒地走向了签名会。<br>她的背影看起来<br>比任何时候都要强大。"},
{index="30086",text="长达3000米的赛程。<br>从第3弯道开始的是长而险峻的坡道。<br>这是一条遥远的道路，<br>仅凭“努力”二字无法跨越。<br><br>额头上不断沁出的汗水，<br>迫切地遮挡着她的视线。<br>心脏跳动的声音化作尖叫，<br>紊乱的呼吸灼烧着喉咙。<br><br>她问着自己的内心：<br>为何要如此痛苦地奔跑？<br>为何拖着沉重的步伐仍要向前迈进？<br>在得出答案前传入耳中的，<br>是震天撼地般的欢呼声……那是期待的欢呼声。<br>她沉浸其中，<br>所有的痛苦随之一扫而空。<br><br>等她回过神来，宿敌强大的身影<br>已在身后咄咄逼近。<br>这情形不允许她回头，<br>也不允许她放弃。<br>这是通往顶点唯一的道路……<br><br>那天，直到最后也没有放弃的优俊少女，<br>成为了最强优俊少女。"},
{index="30087",text="“哎呀……啊，光明！<br>停下，停下！不要跑了！<br>抱歉，秒表坏了！”<br><br>“哈、哈……呼～<br>说来这一组真长呢～”<br><br>“大概有三组的运动量哦！<br>你、你没事吗？”<br><br>“嗯，没事啊～”<br><br>“这还没精疲力尽，<br>属实是坚持训练有了成效啊！<br>如果我没让你停下，<br>你该不会还能继续下去吧？！”<br><br>“呵呵呵，不好说哦。<br>我想我会毫无察觉一直跑下去的～”<br><br>“啊哈哈哈哈！像是你会做出的事！<br>你也有没变的地方呢……<br>诶嘿嘿，因为我们从小就认识，<br>看你这样就像是自己变强了一样开心！”<br><br>“听到你这么说……<br>我就觉得为了成为目白家引以为傲的一员<br>而做的努力都是值得的。”<br><br>“我今后也要一点一点，<br>不断地向前迈进～”"},
{index="30088",text="“你们俩，觉得特雷森学园怎么样？<br>入学以后感觉和想象中不一样吗？”<br><br>“是的……就像小特前辈说的，<br>完全不一样。是吧小北？”<br><br>“嗯，完全不一样呢。”<br><br>“诶，是吗？！<br>该不会让你们失望了吧？！”<br><br>“没有……倒不如说——”<br><br>“比想象中要好得多！<br>无论是训练还是比赛，<br>都比想象中还要快乐！”<br><br>“是啊是啊！每天都像是在举办庆典，<br>让人兴奋不已！”<br><br>“啊～太好了……<br>吓得我心跳都要停了～”<br><br>“不过……我也和你们俩一样。<br>入学后身边新鲜的事情接连不断……<br>而且，现在也还会一直有<br>让我激动不已的事情发生哦！”<br><br>“连小特前辈也会……！<br>哇～怎么办小光钻！”<br><br>“嗯！接下来我们会<br>遇见怎样的事呢！”<br><br>“啊哈哈！接下来也会有很多令人兴奋、<br>意想不到的事情在等着你们哦！”<br><br>“好的！”<br>“好的！”"},
{index="30089",text="在兴奋沸腾的观众席中，<br>一名男子用颤抖的声音低语着。<br><br>“我一直在等待……<br>即使被人期待、受到支持，<br>结果也一直不尽如人意……她就像我一样。<br><br>但是，她赢了……<br>她相信自己，没有放弃……”<br><br>“你感受到marvelous了吧☆<br>你也非常marvelous哦★☆★”<br><br>热泪沿着男子的脸颊流下。<br>他终于意识到了<br>那一开始就已经了然的真相——<br><br>“原来我也很marvelous啊……”<br><br>就这样，世界上又亮起了<br>一盏marvelous的灯火。"},
{index="30090",text="你的步伐如獠牙般锋利。<br>那优美的身姿，<br>宛如瞄准猎物颈项的野兽。<br><br>“看来你并没有生疏。<br>是不是暗地里努力练习了呢？”<br><br>“答对了。因为你这个人要做足了铺垫才肯大显身手，<br>我想为你隔绝大众的视线，<br>这位习惯被追捧的‘皇帝’陛下。”<br><br>“那么，这次就由你来‘倾诉’吧。<br>只要内容不是临时想出来应付我的东西，<br>我就会洗耳恭听、全心配合你的。”<br><br>你的转身打破了寂静。<br>嘲讽化为呼吸，<br>额头开始闪耀着光芒。<br><br>“如果你愿意，我可以引领你。<br>但别忘了，<br>你这个‘导火索’可是要付出代价的！”<br><br>“哎呀！真是危险的步伐。<br>跳舞最重要的是对搭档的信任。<br>为了让你牢记这一点，天狼星……<br>是时候给你上一课了。”<br><br>你步步紧逼，<br>那舞动看起来就像是对统治的渴望。<br>既然如此，我将全心全意地接受挑战。<br>“皇帝”鲁道夫象征就在这里。"},
{index="30091",text="“告诉我，你从那里看到了什么？”<br><br>“是匆忙消失的影子？<br>还是他人扬起的尘埃？”<br><br>“嗯，到处都是些无聊的东西，<br>而且还像泥潭一样棘手。”<br><br>“是继续沉沦下去……<br>还是做无谓的挣扎……<br>大概就只有这两种选择吧？”<br><br>“但是，你还有第三个选择。<br>抓住我的手——”<br><br>“我将带你看看无聊之外的世界。”"},
{index="30092",text="能量=质量×光速的平方。<br>无论什么都是等价交换。<br>付出多少，就有多少回报。<br>换句话说，期待再高也得不到更多的回报……<br>这样就好。<br><br>“真的超嗨——！<br>！Monad也太赞了吧？！<br>呼——！！”<br><br>但如果混进了噪音，<br>等式就会崩溃，径直陷入混沌……！<br>即便如此，我还是——<br><br>“正合我意。我可不会就此停下。<br>要让你沉醉到忘掉一切……！”<br><br>在这充满不确定因素的<br>缓存中，我——<br><br>“来吧，跟上我……！<br>哈……哈哈……！”<br><br>为什么我在拼命地忍住不笑？<br>啧，原来陷进去的人是我啊。<br>得到答案了……我就承认好了。<br>所以——<br><br>“只要我的节拍不停，<br>都不准开灯。”"},
{index="30093",text="我喜欢蓝色和白色。<br>它们清新却鲜明，<br>有气质却不矫揉造作。<br><br>这是最能让我接近<br>理想中的自己的色彩——<br><br>“嗯，这个搭配果然是最棒的♪”<br><br>搭配得好。<br>褶边很好看，裙摆也很棒。<br>蝴蝶结也系得很完美。<br><br>姿态没问题，笑容也很灿烂！<br>我是无可挑剔的<br>“休息日的优等生”！<br><br>“毕竟是重要的外出……<br>不穿上最有干劲的‘决胜服’<br>怎么行呢，对吧♪”"},
{index="30094",text="时而责备，时而鼓舞，时而分享。<br>你就这样一直支持着别人。<br><br>今天也是，为了给他人加油，<br>你在观众席上俯瞰着这个世界。<br><br>挥舞着远超10公斤的大旗，<br>即使喊到声音嘶哑，<br>大家的目光仍然聚焦在比赛上。<br>你所处的位置，是光照射不到的阴影。<br><br>但你不顾一切地竭尽全力，<br>贯彻自己的职责。<br>因为你相信这是正确的。<br>因为这是你引以为傲的信念。<br><br>“加油”——<br>不经意间脱口而出的话语。<br>声音微弱到在平日里也几乎会被淹没。<br>还未传达给任何人，便已消散。<br><br>即便如此……你还是回过头来。<br>挥旗的手臂不能停，鼓励的声音也不能休。<br>只是那一瞬间，你露出了笑容，<br>那笑容如同摇曳的火焰……"},
{index="30095",text="我在观众席上俯瞰着激烈的赛事。<br>优俊少女们以惊人的速度在赛道上疾驰。<br>一阵特别响亮、与她们的气势不相上下的<br>加油声在会场中回荡。<br><br>“漂亮的过弯！但是后面的选手追上来了！<br>这样下去的话……啊！”<br><br>可能是有自己支持的选手，<br>她露出遗憾的表情……<br>但是紧接着——<br><br>“做得好！漂亮的追击！<br>训练的成果展现出来了呢！<br>继续保持，就这样冲过终点吧！！”<br><br>“诶？！不是在支持<br>刚才领先的选手吗……？”<br><br>我不由自主地说了出来。<br>对此，她……采珠<br>对我微微一笑。<br><br>“比赛就是要决出胜者和败者。<br>光芒与阴影总是相伴而生的。”<br><br>“但是，全力以赴战斗的身姿<br>没有高低胜败之分，<br>都是值得赞颂的光芒！”<br><br>“为所有优俊少女加油！<br>为所有优俊少女喝彩！<br>我将永远为所有优俊少女呐喊助威！”<br><br>她那不知阴霾的纯真，就像珍珠一般。<br>被那光芒所吸引……<br>世界在我眼中的色彩也发生了变化。"},
{index="30096",text="即使是一瞬间的疏忽，也可能导致巨大的危机。<br>在强敌紧逼之时，突然听到了加油声……！<br>这简直就像是——<br><br>“公主战士！不要输啊——！”<br><br>将我小时候在电视机前的加油声<br>化为力量，迎击邪恶——<br><br>“就是现在！放手一搏吧！<br>公主战士！”<br><br>那闪耀着希望的光芒，<br>正是公主的姿态……！<br><br>“冲啊！公主战士！”<br><br>如果是这样，那么答案只有一个。<br>身为公主，一定……一定——<br><br>“不会……认输的——！！”"},
{index="30097",text="赛道是最糟糕的情况。<br>尽管如此，你依旧不顾泥泞，<br>冲出重围，一跃成为领跑者。<br><br>你穿过翻飞的草皮、<br>空中飞舞的水滴、<br>还有跑在前方的我们。<br><br>你在一切事物之间<br>穿行、<br>超越、<br>扬长而去——<br><br>被你超过时，我看到的<br>是那双清澈的天蓝色眼睛。<br>那是没有人能追得上、<br>也绝对无法抓住的自由……<br><br>“千明代表，率先冲过终点！<br>三冠的首场比赛，<br>是千明代表拿下了胜利！”<br><br>在泥泞中，几乎认不出谁是谁，<br>只有她是与众不同的。<br><br>她像少年一样伸手擦掉脸颊的泥土，<br>嘴角微微上扬，露出了潇洒的笑容。<br>她面向观众，用手指向天空。<br><br>我不由自主地看得入了迷，<br>连输给她这件事也忘在了脑后。"},
{index="30098",text="“新～的～决胜服♪<br>目标是在比赛中拿一等奖！”<br><br>“穿上决胜服～兴奋不已♪<br>满心欢喜地奔跑吧♪”<br><br>“蹦蹦♪跳跳♪<br>尽全力～冲出去！”<br><br>同班的优俊少女正在唱着什么。<br>虽然经常看到这个场景，<br>但今天不知为何格外在意她。<br><br>“那是什么歌？”<br><br>回过神时我已经问出口了。<br>因为她看起来太开心了，让我心里也变得痒痒的。<br><br>“这个嘛～是决胜服之歌哦！<br>因为我超级期待穿上它去跑步！<br>尽全力～冲出去！”<br><br>很期待奔跑。<br>因为快乐，所以唱歌。<br>多么简单——而又直率的情感啊。<br><br>“真好啊。”<br><br>我不知不觉间已经遗忘了<br>那种快乐的感觉。<br><br>“那……你要一起唱吗？<br>我起个头，一起来吧！”<br><br>“诶……这个……”<br><br>“预备，起！蹦蹦♪<br>跳跳♪尽全力～”<br><br>“冲、冲出去……”<br><br>“冲出去！<br>诶嘿嘿，好期待下一场比赛呢！”<br><br>真是不可思议。一起唱歌之后，<br>快乐的感觉就涌上了心头。<br><br>对啊，比赛本就是让人期待的。<br>不去想那些复杂的事，<br>我也要纯粹地享受比赛！"},
{index="30099",text="“哇～<br>生野真的好漂亮……<br>就像真正的新娘一样……！”<br><br>“谢谢夸奖，米浴。”<br><br>穿上设计精美的决胜服，<br>在大家的注视下……<br>感觉有些难为情。<br><br>不过，这也是难得的经历。<br>我要好好参加拍摄——<br><br>“诶？！生野是新娘吗？！<br>不要不要！不要嘛！<br>你不要嫁人——！！”<br><br>“诶，等等，涡轮你在干嘛？！<br>会妨碍到拍摄的啦！”<br><br>“不——要——嘛——！！<br>别丢下涡轮——！！”<br><br>因为涡轮的误解，<br>拍摄现场好像稍微陷入了混乱。<br><br>在比赛中总是用大差距领跑<br>甩开大家的涡轮<br>现在却在大喊“别丢下涡轮”，也真是有趣。<br><br>“涡轮，你冷静点。<br>我哪里都不会去的。”<br><br>怎么可能离开。<br>毕竟我们的比赛还没有结束呢。<br><br>总之，等这次拍摄结束后，<br>就陪涡轮她们一起训练吧。"},
{index="30100",text="曾经见过的婚礼景象——<br><br>新娘轻轻一笑，<br>随即周围也洋溢着笑脸，<br>大家都充满了幸福。<br><br>那个场景，至今仍然难以忘怀。<br><br>我也想让大家露出那样的笑容，<br>想给大家带来幸福。<br><br>那是一个微不足道的、我所向往的梦想。<br><br>我鼓起勇气，向前迈出了一步。<br>笑容随即蔓延开来。<br><br>那是那天我所向往的婚礼景象，<br>也是新娘所见的幸福景色。<br>我感觉自己仿佛也窥见了一隅……<br><br>“我还想让更多人露出笑容。”<br><br>我希望今后也要<br>为更多的人带来笑容。<br><br>然后，<br>把幸福带给大家——"},
{index="30101",text="真是鲁莽。<br><br>那仿佛能超越光速的奔跑，<br>想必会在终点前消耗殆尽吧。<br><br>在所有人都这么想的时候，<br>只有她陶醉地笑着。<br><br>“啊啊，太棒了……<br>太棒了……！真是愉快至极！”<br><br>用理论贯彻鲁莽，使其屈服。<br>这种世界的色彩变得愈发浓郁的感觉是——<br><br>“呵呵……那么，在下一次的实验中……<br>又会有怎样的愉悦在等着我呢……！”<br><br>这只有她本人才能知晓了。"},
{index="30102",text="超级赞的大姐姐为你预报天气♪<br><br>今天的我是万里无云的晴天☆<br>盛夏般火热又耀眼的阳光，<br>会直接射中大家的心！<br>在海边尽情玩耍才是潮流哦♪<br><br>但是快乐的时光总是短暂……<br>到了傍晚，<br>可能会有点凉飕飕的？<br><br>黄昏时刻会有点伤感，<br>就像是发布了局部小感伤预警一样。<br><br>但是，放一百个心！<br>毕竟照耀我的不只有太阳……<br>还有用心中热火让我炽热起来的<br>那个耀眼的她呢♪<br><br>在这多愁善感的情绪里稍稍停留之后，<br>明天又会是个温柔的晴天吧♪"},
{index="30103",text="在故事描绘的森林中，<br>有两位优俊少女<br>正在藤蔓之间飞速移动——<br><br>“我说，大树！”<br><br>“What？怎么了吗？”<br><br>“在这种情况下，<br>我有一件无论如何都想要做的事……<br>不，是想说的话？<br>不对，是想要大声喊出来的事情……？<br>就是这样！”<br><br>“I see！<br>我现在的心情，<br>也和唐怀瑟一样！」<br><br>“噢噢！<br>那我们一起……<br>3、2……1！”<br><br>“啊——啊啊♪”"},
{index="30104",text="【有水魔引诱的水边，<br>有精灵引路的庭院，<br>有星星指引的门扉……<br>历经重重考验，<br>村民们终于到达了目的地。<br>迎接他们的是<br>世间罕见的美丽景象——】<br><br>“Amazing！<br>墙壁真的在发出蓝色的光芒！”<br><br>“真的好像另一个世界一样……<br>原来还有这样的地方！”<br><br>【在这如梦似幻的景象面前，<br>村民们情不自禁地<br>发出了惊叹——】<br><br>啊啊，啊啊——！<br>我现在真的身处于那个故事之中！"},
{index="30105",text="“成为全国第一的优俊少女”——<br><br>那是我的梦想。<br>是我和妈妈许下过约定的、重要的梦想。<br><br>但这个梦想就像寒冷早晨的雾气般<br>难以成形，只是遥不可及的憧憬。<br>我曾一味地尝试抓住那无形之物。<br><br>然而——<br><br>众多邂逅<br>令我的梦想随之鲜活！<br>其中有和对手的激烈对决，<br>还有必须跨越的障碍。<br>有痛苦与悲伤的时刻，<br>也有快乐与开心的时光。<br>这一切都将我的梦想塑造成形！<br><br>你有憧憬吗？<br>有无法退让的愿望吗？<br>让我们一起去追寻吧！<br>抓住你重要的梦想！"},
{index="30106",text="这场比赛关乎于能否达成母女两代称霸奥克斯<br>这一历史性纪录。<br>会场内议论纷纷，<br>她的肩上承受着巨大的压力。<br><br>但是，“女帝”现身的瞬间，<br>就像刮起了将喧嚣一扫而空的熏风一般。<br>她统御着风，<br>以威风凛凛的步伐走向起跑线。<br><br>那锐利的目光仿佛能让万物臣服，<br>那紧握的五指仿佛将要刺进肌肤。<br><br>她追求的是理想，渴望的是胜利。<br>她的武器是作为“女帝”的骄傲。<br><br>“我一定会赢。”"},
{index="30107",text="超级赞的大姐姐为你预报天气♪<br><br>今天的我是万里无云的晴天☆<br>盛夏般火热又耀眼的阳光，<br>会直接射中大家的心！<br>在海边尽情玩耍才是潮流哦♪<br><br>但是快乐的时光总是很短暂……<br>到了傍晚，<br>可能会有点凉飕飕的？<br><br>黄昏时刻会有点难过，<br>就像是发布了局部小感伤预警一样。<br><br>但是，放一百个心！<br>毕竟照耀我的不只有太阳……<br>还有用心中热火让我炽热起来的<br>那个耀眼的她呢♪<br><br>在这多愁善感的情绪里稍作停留之后，<br>明天又会是个温柔的晴天吧♪"},
{index="30108",text="我所期望的，是那震慑心扉的一瞬间。<br>登上那简单到极致<br>却又最为刺激的舞台。<br>等待着对手们的“加注”。<br><br>我的命运，就掌握在敌人手中……<br>就是这么回事。<br><br>裁决之时——<br><br>这一瞬间，灯火们一同<br>将命运燃尽，缓缓消逝。<br><br>没错。<br>我就是为了这一瞬间……<br><br>“就是因为这样，我才欲罢不能啊。”"},
{index="30109",text="“心怀超赞，终绽樱华”<br><br>（出处：“某场白热化的战斗”）<br>这句话的意思是：就像有人会因为憧憬那<br>超级赞的心态与活法而奔跑，<br>想为憧憬之人带来力量的心情也同样存在。<br>这真挚的心情相互碰撞后<br>一定能够开花结果。<br><br>（解说）<br>正因为有憧憬的存在，<br>我才能努力至今。<br>所以，这次轮到我来为憧憬之人带来力量了！<br>为了能尽情享受、燃烧激情——<br>我要尽全力去战胜我所憧憬的人！"},
{index="30110",text="欢迎光临……<br><br>今天……你也来了呢。<br>是的……<br>我暂时会在这里，帮父亲的忙……<br><br>你要点单吗……<br>嗯，还是和往常一样的黑咖啡呢。<br>我马上为你端来——<br>要多加牛奶吗……？<br>不……没问题。<br>是没问题……我只是觉得，有些少见……<br><br>原来如此……那你一定很忙呢……<br>……<br><br>那个……虽然我刚才说“马上”……<br>但能请你稍等片刻吗？<br><br>“献上属于客人的一杯咖啡”……<br><br>父亲是这么教导我的。<br>我想稍微……花些心思……<br><br>是怎样的心思？<br>这个——<br><br>就当是之后的小惊喜吧。"},
{index="30111",text="无论是比赛时还是其他时候，<br>我在面对挑战时，<br>兴奋总是大过紧张。<br><br>虽然总是被大家说“你好奇心真旺盛”，<br>但并不只是如此。<br><br>完成挑战之后、冲过终点之后……<br>大家望向我的那种两眼放光的感觉！<br><br>我现在也很期待——在这场对决之后，<br>究竟有怎样的闪耀在等着我呢！<br>所以，我一定要全力操控方向盘夺下冠军——<br><br>“蓝色围巾飘呀飘♪<br>转动方向盘，最强机器轰鸣吧♪”<br><br>“帝王王♪　帝王王♪”<br><br>“帝王！王！王！！！”<br><br>“真是的，涡轮！我正在认真思考呢，<br>别随便编奇怪的歌啦！”"},
{index="30112",text="今天双涡轮<br>也在训练赛道上全力奔跑。<br><br>“哈……呼……哈……”<br><br>但是，她总是在全力冲刺。<br>每跑一圈，速度就会慢下来一点。<br><br>“喂喂，双推进器！<br>差不多该休息一下了吧？”<br><br>“是双涡轮！<br>比起那个，我还要再跑一次，<br>帝王你好好帮我计时！”<br><br>“游戏里也是这样的吧。<br>越努力速度就会越快！<br>我是绝对不会放弃的！”<br><br>“我要再次使出游戏里那样的技能了！<br>上吧，涡轮全开！！”<br><br>双涡轮再次猛地冲了出去。<br>但是，她很快就失速，步伐开始变得踉跄。<br><br>即使如此，<br>她那依旧全力向前奔跑的样子——<br><br>“果然……还是很帅气啊。”"},
{index="30113",text="乘着铁制的飞机越过山脉——<br><br>在现实中是理所当然的景象。<br>只要有符合空气动力学的<br>设计图组装零件就行了……但这里不一样。<br><br>没见过的素材、<br>没听过的原理……<br><br>要想实现计划，<br>果然还是应该先深入了解<br>这个世界的事情吧……<br><br>“嗯……这个相当于我们世界里的钛吗？<br>然后这个是使用蒸汽机的首个发明……”<br><br>“嗯……？这是通讯器吗？<br>竟然是用电磁波覆盖地表的输电系统？<br>还有通过压缩蒸汽实现的半永动机？”<br><br>“等等，难道这里早就开发出了<br>能承受如此压力的合金？！<br>强度难道会远超钨钢？！”<br><br>“毕竟这可是奇幻世界，<br>要吐槽起来可就没完没了了。”"},
{index="30114",text="“这些肖像画代表着我们一族的骄傲，<br>是铭刻于历史的功绩与荣耀的赞誉。”<br><br>她站在格调高雅的楼梯上，清亮的嗓音掷地有声。<br>少女站在满墙的肖像画前，<br>衣着华丽而又纤细的身姿带着一丝缥缈感，<br>眼神却凛然而清澈。<br><br>“我的母亲与祖母也在此列。<br>她们摘得了数不清的桂冠，还获得了URA奖，<br>这在我们一族中也是尤为杰出的荣光。”<br><br>白瓷般的指尖轻轻划过空中，<br>柔美的手抚上了红色跃动飞舞的胸前。<br><br>“只要是家族的一员，便无一例外。”<br><br>她的话语在挑高的阶梯上久久回荡。<br><br>墙上无数双眼睛<br>正凝视着少女的背影——"},
{index="30115",text="万圣节装扮摄影会～哦耶☆<br>我要给超上镜的善信亲拍美照！<br><br>“噢～服装和布景都超专业的！<br>感觉会拍出超级棒的照片呢～”<br><br>“就是啊！善信亲，<br>恶魔装扮超适合你的！1亿分！”<br><br>这种感觉叫什么来着，妖艳？<br>善信亲拍这种大姐姐的感觉<br>果然也超上镜的♪<br><br>“好了，那就开拍吧！<br>善信亲，彻底化身为恶魔吧！”<br><br>“诶？要代入角色啊……<br>有点小羞涩呢。”<br><br>“没～关系！<br>就用那种～贪心小恶魔的感觉，<br>把一切都夺走就好啦！”<br><br>“原来如此，夺走……好，我试试！”<br><br>“你闻起来，好香甜啊……<br>感觉比糖果还要美味♪”<br><br>哇——超心动的！<br>是那种想被善信亲吃掉的感觉！<br>超有感觉的绝美照片，诞生啦！<br><br>月夜之下微笑的恶魔！<br>万圣节之夜就此开始啦～就是这样！"},
{index="30116",text="万圣节装扮摄影会！<br>我要给太阳神拍超上镜的照片！<br><br>“哦耶哦耶—！万圣节快乐♪<br>怎么样？我很适合天使风的打扮吧？”<br><br>“呵呵，超～合适的！太阳神果然<br>还是适合充满活力的打扮呢！”<br><br>总是活力满满地追求快乐，<br>连周围的人都变得精神起来了。<br>从太阳神那里得到的活力，<br>简直就像是天使的恩赐……？<br><br>“好，太阳神你随便活动吧！<br>我会追着你随便拍的！”<br><br>“真假？！<br>那我就去给大家发糖果咯！”<br><br>“哦耶哦耶——☆<br>天使大人驾到——！<br>给大家送上糖果♪”<br><br>她竟然去派发糖果了！<br>太阳神一边不断地给大家带来活力<br>一边做派对达人……<br>嗯，这绝对是最佳照片了。<br><br>阳光之下闪耀的天使！<br>万圣节派对开始啦！"},
{index="30117",text="《小风魔王城计划书》<br><br><魔王城的设定><br>魔王小风的恐怖魔王城！<br>踏入此地之人<br>会遭遇好多超级恐怖的事情，<br>坠入恐怖的深渊！！<br><br><形象><br>·使用1间教室！！<br>·漆黑一片！要在墙上挂黑幕！<br>　→黑暗魔王的城堡又黑又可怕！<br>·最终BOSS★★魔王小风★★<br>·想见到魔王大人<br>　就要跨越重重试炼！<br>·道路错综复杂，<br>　让人分不清东南西北！<br>·试炼的种类<br>　→从满是恐怖机关的箱子里找钥匙<br>　→和怪物战斗<br><br><怪物候选！><br>·巨大怪物　※总之就是又大又可怕！<br>·南瓜怪物　※飘在空中<br>·恶魔　※被抓住就会动弹不得！<br>·僵尸　※被咬到就会变成其中一员<br><br>大家都会陷入恐怖的混乱之中，<br>魔王军的统治就要开始啦！！"},
{index="30118",text="时间到了。<br><br>每前进一步，<br>欢呼声、脚步声、心跳声——<br>一切都逐渐远去。<br>但是——<br><br>灵魂，在咆哮。<br>苦涩，早已尝尽。既然如此，<br><br>“将其咬碎便是”。"},
{index="30119",text="在那里，<br>有懊悔、<br>有叹息、<br>有遗憾。<br>但是，也一定有着<br>对未来优俊少女们的祝福——<br><br>多么高尚、伟大的前辈们，<br>多么宏大的心愿啊。<br><br>“总有一天——<br>总有一天，我会证明——”<br><br>证明所有的祈愿，<br>都化为了无形的力量，<br>不断推动着我们驰骋于现在与未来。"},
{index="30120",text="那是神俊们练习“信念相承”时的一幕——<br><br>“八重在舞蹈时，仿佛完全感觉不到<br>火焰的灼热，<br>舞姿凛然大气……<br>真是太精彩了。<br>我也很想向你学习，<br>请问你有什么诀窍吗？”<br><br>“不，我现在资历尚浅，<br>谈不上什么诀窍——<br>只是我跳舞的时候，<br>会莫名感受不到热度……”<br><br>“原来如此……<br>这就是所谓的<br>‘心静自然凉’吧。”<br><br>“如果我达到了那个境界，<br>真是万分荣幸。<br>呵呵……我平时一旦沉迷于<br>某些事情就会忘乎所以——<br>我一直以为这只是个坏习惯，<br>但换个角度看，<br>或许也能成为我的武器呢。”<br><br>“嗯，一定可以的……”<br><br>“既然如此，我八重无敌在此起誓，<br>无论面对怎样的烈火，<br>我都会以毫不动摇的决心，<br>完成自己的使命……！<br>即使烈火将我的身躯<br>烤得焦黑，<br>我也会毫不动摇地<br>将舞跳完……！！”<br><br>“呵呵呵，这气势可真是了不起。<br>不过，要是真的烤焦<br>可就糟了……<br>我们还是来练习安全的舞蹈方式，<br>避免那种情况吧。”<br><br>“好！！”"},
{index="30121",text="粉丝答谢活动的邀请函<br><br>感谢你一直以来<br>对优俊少女的支持。<br>我是执行委员美浦波旁。<br><br>一直以来，我们都心无旁骛地<br>以终点为目标奔跑着。<br>但是——<br><br>无论是为梦中所见的景色心醉神迷之时，<br>还是为高墙所挫、心灰意冷之际，<br>我们都不曾孤身一人。<br><br>你的鼓励，永远陪伴着我们。<br>每当听到你的鼓励，我们便会<br>重新振作，描绘新的梦想。<br><br>与各位一同留下的脚印，<br>也即将来到第2弯道。<br><br>若用比赛来比喻，<br>就是热身结束……<br>将积蓄的力量注入双腿，开始加速的时刻。<br><br>因此，我们将怀着平日对各位的感谢<br>以及对未来的决心，<br>举办粉丝答谢活动。<br>欢迎你的踊跃参加。<br><br>今后，我们也会与无可替代的你<br>并肩前行。<br><br>“好……！这样感觉如何？”<br><br>“好厉害……内容没变，<br>但文章不再生硬……！”<br><br>“我也同意铃鹿的看法。<br>如果送出这份邀请函，<br>推测粉丝们也能轻松参加。<br>换言之……‘很出色’。”<br><br>“诶嘿嘿！不过呢，我觉得正因为有波旁<br>倾注了心意的原文，<br>才能修改得这么好♪<br>之后只要让大家在当天玩得开心就好啦☆”<br><br>“是的。<br>那一天真是……‘令人期待’。”"},
{index="30122",text="1、2、345、67、8、910……<br>节拍器一旦紊乱，<br>就无法履行它的职责。<br><br>咔哒、咔哒——节拍器精准无误、<br>等间隔地刻画下时间。<br>那份美便是我的指引。<br>我侧耳倾听，保持均衡。然而——<br><br>123、4、567、89、10……<br>我没有去修正紊乱的节拍器，<br>而是直接将它塞进了遗忘的箱子里。<br><br>感动、往昔、欢喜、乡愁、羡慕、<br>泪水、执念、交错……！<br>这些情感此刻正向我涌来！<br>我就像个故障的铁皮玩具一般，<br>无法抑制这跃动的节奏！<br><br>“谢谢！谢谢！<br>谢谢……！！”<br><br>只留下了狂喜的熔炉……<br>谢谢！此刻我只能想到这感谢之语！"},
{index="30123",text="“原来你也会露出这种表情啊。”<br><br>听到气槽的话，<br>成田白仁的耳朵微微动了一下，<br>然后瞥了她一眼，<br>仿佛在说“你有意见吗？”。<br><br>“我只是想说这照片拍得不错。<br>毕竟平安夜就该是这样呢。<br>我还以为你不喜欢圣诞节……<br>不过你似乎并不讨厌呢？”<br><br>“毕竟这天不管吃多少肉，<br>我姐都不会唠叨我。”<br><br>“哈哈，那倒不错。原来晨光也不会<br>在平安夜做这种扫兴的事啊。”<br><br>“而且……”说着，<br>成田白仁抬头望向灯火辉煌的弗隆塔。<br><br>“偶尔这样，也不错。”<br><br>“难得我们意见一致……我也这么觉得。”<br><br>弗隆塔闪烁着耀眼的光芒。<br>接下来的一段时间里，成田白仁和气槽<br>就这样静静地眺望着那份光芒……"},
{index="30124",text="特雷森学园圣诞派对的前一天，<br>气槽正与富士奇石<br>商量某件事。<br><br>“咳咳……‘圣诞快乐。<br>今天非常感谢各位莅临特雷森学园’——<br>首先，我打算这样开场。”<br><br>“嗯，能感受到气槽满满的诚意哦！<br>不过考虑到是圣诞节，<br>这样会不会有点太严肃了？”<br><br>“果然……<br>但一想到要在公开场合代表学生会致辞，<br>就总会下意识地严肃起来……”<br><br>“毕竟气槽总是很重视<br>时间、地点和场合呢！<br>那这么想如何？<br>既然要在圣诞派对上扮演圣诞老人，<br>就必须表现得像个圣诞老人才行。”<br><br>“‘嚯嚯嚯嚯！<br>圣～诞～快～乐！’<br>像这样！好了，轮到你啦！”<br><br>“什么？！唔……唔唔……<br>‘哼哼哼，圣诞快乐！’<br>这样如何……？！”<br><br>“唔……可惜！<br>与其说是圣诞老人，不如说是撒旦吧？”<br><br>“你说谁是恶魔啊！”<br><br>“啊哈哈，就是这样！<br>表情一下子就生动起来了，<br>气槽！<br>首先这点才最重要吧？”<br><br>“唔……<br>嗯，的确如此……你说得对。”<br><br>“这样下去会被母亲斥责的——<br>圣诞节是‘快乐’的活动。<br>既然如此，就必须先由我发自内心地<br>去告诉大家这是一个‘享受快乐’的场合。”<br><br>“没错！<br>呵呵，当天也要玩得开心哦，气槽。”<br><br>“嗯，我会努力的。”"},
{index="30125",text="我不会问“我表现得怎么样？”这种问题。<br>因为我已经把一切都倾注在了舞台之上。<br><br>我放声高歌，直到喉咙沙哑。<br>我用力踏步，仿佛要踩穿地板。<br>我无论如何都想让你注意到，<br>所以我倾尽了自己的全部。<br><br>这就是我想传达给你的讯息。<br>是我此刻倾注一切的、最真实的心意。<br>所以，小白仁——<br><br>“下次，也希望你能在我的身边……<br>与我一同歌唱。”"},
{index="30126",text="本次比赛聚集了称霸一级赛事的强者们。<br>而此时的山人西风<br>尚未留下亮眼的成绩。<br><br>因此她没有受到关注<br>倒也是情有可原。<br><br>但是，人们很快就会知道。<br>将她看作微弱的【西风】是<br>多么致命的错误。<br><br>“哈啊啊啊啊啊啊！”<br><br>山人西风提早发力。<br>那副模样，正如疾风一般。<br><br>在第4弯道时她已位居第三，<br>在直道更是跃升至首位。<br><br>自由奔放的风，比任何事物都飞快地驰骋着，<br>就像那天所见到的憧憬一般。<br><br>烈风不容任何事物靠近……<br><br>“这就是，那阵风所见的景色。<br>多么清爽的风啊。”<br><br>“然而，风之道还未到终点，<br>不能在此停滞不前。”<br><br>“真正的风就在前方。<br>我会比一切都要快地呼啸而过。”<br><br>回到终点板前的她，<br>将右手伸向了天空。<br><br>赛场之上，一阵风呼啸而过——<br>它拂过青叶，送来了祝福。"},
{index="30127",text="“小特知道板羽球里<br>蕴含的愿望吗？”<br><br>小草一边把用来在脸上画墨的<br>毛笔递给我，一边突然问了我<br>这个问题。<br><br>“板羽球里蕴含的愿望……？”　　<br><br>“这羽毛前端的果实里，<br>蕴含着‘祈福健康平安’<br>的愿望……<br>而羽子板则寄托着‘驱除各种灾厄，<br>祈福健康美丽地成长’<br>这个愿望，<br>是正月时赠与他人的礼品哦。”<br><br>“哦——！”<br><br>“所以板羽球原本并非为了竞技，<br>而是一种为了互相祈求健康、<br>需要长时间<br>对打的游戏。”<br><br>“诶诶，原来是这样啊！<br>那下次可得尽量打久一点才行！<br>啊……那！小草老师！<br>难道说作为惩罚在脸上画墨，<br>也是有什么理由的吗？”<br><br>“问得好，特别周同学。<br>有一种说法是，墨的黑色被认为是驱魔的颜色，<br>把它涂在脸上就能辟邪，<br>从而保护自身安全。”<br><br>“所以，万一没接住羽毛，<br>只要在脸上涂上墨<br>就没问题了。”<br><br>“原来不只是作为惩罚啊！<br>那好！”<br><br>我紧紧握住接过的毛笔，<br>深吸了一口气。<br><br>“希望小草在接下来的一年里<br>都能无伤无病地奔跑。”<br>在右眼上画一个大大的圆。<br>“希望你不会感冒生病。”<br>在左脸颊上斜着画一道线。<br>“希望你能多吃美食，<br>笑容不断。”<br>在左脸颊上再斜着画一道线。<br><br>我的一笔一画里都倾注了心意。<br>作为朋友、作为对手，<br>希望我们能永远并肩奔跑至天涯海角——<br><br>“谢谢你为我做了这么多祈福……<br>小特。<br>不过，呵呵，是不是涂得有点太多了？”<br><br>“诶？哇？！对不起！！！！”"},
{index="30128",text="她静静地走在覆雪的石阶上，<br>艳丽的尾巴和蕾丝阳伞愉快地摇动着，<br>清冷的风中传来了她的哼唱声。<br><br>突然，摄影师呼唤了她的名字。<br>她猛地摇了一下尾巴，<br>缓缓地回头望向这边——令人不禁屏息。<br><br>美丽的脸庞上落下阳伞的阴影。<br>一抹红色点缀其中，一丝白色若隐若现。<br><br>她回眸一瞥的眼角、<br>微倾着的脖颈、<br>端庄地扶着伞柄的手，<br>颠覆了她在我心中的形象。<br><br>那份美令人心惊。<br>在那里的人确实是她，<br>却又美得让人生疑，深深吸引了我——<br>仿佛施了魔法一般。<br><br>不经意间，我与她的视线交汇。<br>她惬意地眯起眼睛，笑着说：<br><br>“哼哼，很完美吧？<br>未来的大魔女<br>可是能变成各种模样的哦♪”"},
{index="30129",text="一盏，两盏，灯火不断增加。<br>黎明前的院内，<br>有着为担任优俊巫女的她们而点亮的思念之火。<br><br>那盏盏灯火蔓延开来，<br>承载着“她们定能成功”的信念。<br><br>“真美啊……”<br><br>融化了隆冬深夜里凛冽寒气的<br>是柔和的灯火，<br>是思念着他人的真诚心意。<br><br>远处是昏暗的山影。<br>我望着灯火中断的山腰想道——<br><br>希望她们能注意到<br>这份美丽的温暖。<br><br>愿这份心意能传达给她们。<br>因为点亮这些纸灯笼的每一个人，<br>心中都未放弃她们。"},
{index="30130",text="“那么，下一首歌。<br>这首歌……大家都知道吗？”<br><br>“嗯！是生日歌！”<br><br>“对，是庆祝生日的歌呢。<br>它传递着祝福与感谢。<br><br>不过，据说它原本<br>是另一首歌。<br>不只是为了特别的某一天，<br>而是献给每天清晨‘早安’的歌。”<br><br>“是吗？”<br>“奇迹姐姐，早！”<br><br>“啊哈哈。嗯，早安。<br>那这次我们配合着钢琴的旋律<br>来打招呼吧。”<br><br>“无论是我，还是你们，<br>都一定会迎来崭新的清晨——<br><br>所以呢，晚上在床上睡觉的时候，<br>如果感到寂寞了，<br>就回想一下我们一起<br>唱这首歌时的情景吧。<br>然后，试着这样想——<br><br>‘入睡不是因为黑夜的来临，<br>而是为了迎接清晨的问候”<br><br>黑夜总会过去。<br>等待着你们的，<br>一定会是温暖的未来。"},
{index="30131",text="～Marvelous☆巧克力～<br><br>好期待会出现什么惊喜☆<br>一定会让你拥有marvelous的心情哦★<br><br>“诶，这个枫叶形状的巧克力<br>味道真新颖！像是枫糖浆一样的口味。<br>像花蜜一样好吃……！”<br><br>“这、这个再现了跑车的巧克力<br>虽然很惊艳，但不太好下口啊……<br>不对，这是什么独特的口感呀。<br>特别是后视镜，堪称绝品！”<br><br>“呜、呜啊啊啊啊啊！<br>这个天鹅湖巧克力入口的瞬间，<br>涌入口中的竟然是奥杰塔的悲伤？！<br>简直就像在品尝艺术本身一样！”<br><br>啊哈哈哈☆很不可思议吧，<br>奇怪的巧克力也要尝过之后<br>才知道好不好吃★<br><br>就和人生一模一样！<br>不试不知道会发生什么，<br>可正因为不知道，才更marvelous☆<br>来，请享用marvelous吧★"},
{index="30132",text="“欢迎光临！<br>客人，我来为您带位！”<br><br>“嗯嗯，拜托你了哦，微光♪”<br><br>“啊、阿曙！这是练习，<br>说话要像客人一样哦！<br>那么，这边请！”<br><br>“阿萨姆红茶来了！啊，不对……<br>这是您点的阿萨姆红茶。<br>浓郁的口感能衬托出甜点的甘甜，<br>所以，请和这个，一起……！”<br><br>“你、你没事吧？！那么多的甜点，<br>不用双手拿的话很危险哦？”<br><br>“直面困难才是英雄！<br>就像莱恩前辈和艾尼前辈一样，<br>我也一定能堂堂正正地做到！”<br><br>（然后——我要成为像正义的伙伴，<br>让大家都来依靠我！）<br><br>“唔～久等了！<br>这是您点的究极·无敌·飞驹<br>甜点天堂！！”<br><br>“哇啊，一个都没塌！<br>好厉害好厉害，<br>能一口气拿这么多过来！<br>简直像英雄一样帅气！”<br><br>“是、是吗？嘿嘿♪<br>那么——客人，<br>请您慢用！”"},
{index="30133",text="大家好呀，buono♪　今天的骏友圈直播<br>要来做微苦又美味的“苦味巧克力”哦！<br><br>其实呢，我一直在犹豫<br>要不要教大家这个食谱。<br>因为，也有不喜欢苦味的人吧？<br>我想做的，是像什锦火锅一样<br>能让大家都露出笑容的料理。<br><br>但是……<br>在看到了那位小小的英雄之后，<br>我觉得自己也必须鼓起勇气才行呢。<br><br>所以我决定，<br>要和大家来一次正面交锋。<br>我想用我最喜欢的这个巧克力，<br>和大家说着buono♪一起欢笑！<br><br>“好想尝尝小曙的巧克力啊～”<br>“我也想要阿曙的巧克力！”<br>“阿曙喜欢的苦味巧克力还真让人好奇呢”<br><br>嗯……对了！<br>推荐的可可配比是……<br>啊，差点忘了说重要的事，<br><br>各位——情人节快乐！"},
{index="30134",text="贯彻的是至高，<br>展现的是艳丽，<br>献上的是爱。<br><br>美妙的身姿只为驰骋。<br>紫绀色的眼瞳只凝视着无瑕的荣光。<br><br>菊花、樱花、橡树、玫瑰，<br>万千花朵皆为她俯首。<br>嫉妒、羡慕、憧憬、斗志，<br>万千思绪皆被她抛于身后。<br><br>她驰骋向前，而后取胜。<br><br>其名为——"},
{index="30135",text="各种各样的人都在说：<br>“那样的高墙是无法逾越的。”<br>“即便如此，总有一天会有人做到的吧。”<br>“总有一天，一定会有人可以的……”<br><br>但是——不是那样的吧？<br>正因为无人去做，才要迈开自己的双腿前进！<br>害怕也好，想要放弃也罢，<br>把它们全部抛下，奋力奔跑就好！<br><br>即便如此还是不敢迈出脚步的时候——<br>就看着我！跟上我吧！<br>道路就由我来开拓！<br><br>我就是优俊少女们的王牌——<br>葛城荣主！！"},
{index="30136",text="脚步声此起彼伏，<br>仿佛回响一般<br>笼罩全身。<br><br>喧嚣——逐渐升温。<br><br>目标之地、渴望之物、<br>抵达之处。<br>眼中的火焰和<br>心中的斗志并无差异。<br>那么，要一同驰骋于这片草地吗？<br><br>“No way”——<br><br>我不会……让给任何人——绝不退让。<br><br>能站上那个地方的只有一人。<br>奔跑吧，奔跑吧，奔跑吧。<br>怀着必胜的决心冲过终点吧。<br>只有这样，才能让这个地方——<br>乃至让整个世界<br>都继续沸腾下去。"},
{index="30137",text="赐予你们智慧。<br>愿先人点亮的知识火炬<br>化为你们的路标。<br><br>让我倾听你们的苦恼吧。<br>那亦是前人曾走过的路。<br>循着足迹，便能走出黑暗的森林。<br><br>需要勇气吗？<br>那么我便讲述昔日驰骋之人<br>决意踏出第一步时的故事吧。<br><br>纵使时代不同，纵使形式各异，<br>那深深铭刻于大地的足迹也亘古不变。<br><br>漫长岁月里织就的锦缎，<br>就由我们来传颂它的每一根丝线吧。<br><br>然后让它们传承下去，<br>传给驰骋在当下的优俊少女们！<br><br>传说将孕育新的传说。<br>愿无尽的祝福与继承者同在——"},
{index="30138",text="闭上眼睛，试着回想起你。<br>可脑海中浮现的，<br>却总是你逐渐远去的背影。<br><br>那宛如起舞般奔向前方的样子，<br>帅气得不禁让人苦笑——<br><br>真不甘心啊，你究竟是什么表情呢？<br>我这里根本就看不到啊。<br>毕竟就算想追上你，也办不到嘛。<br><br>至少……想要让你回头呢，<br>想要鼓起微不足道的勇气……<br>让你回头看向我呢。<br><br>但是——这份心意还没能传达。<br>我所积累的点滴、<br>我所期盼的一切都还没能传达。<br><br>所以，就让我用这支舞……<br>将一切都深深地铭刻在你的心中吧！"},
{index="30139",text="不习惯的舞会让我有些无所适从，<br>于是便走向了阳台……<br>结果却与先一步在此享受夜风的<br>目白麦昆四目相对。<br><br>“你也是来休息的吗？”<br><br>我没找到舞伴，<br>所以没能融入舞会——<br>明明可以这样坦率地回答，<br>我却用苦笑搪塞了过去。<br><br>“莫非……你也是为了躲避那些<br>络绎不绝的邀请才来到这里的……？”<br><br>我抓住这个机会用力地点了点头。<br>不想在她面前表现出没出息的样子——<br>我被不知从何而来的虚荣心所支配，<br>局促不安地移开了视线。<br><br>“我们回去吧——”<br><br>“回去——与我共舞一曲吧。”<br><br>不等我回答，目白麦昆便迈开了脚步。<br>她只回头看了一次，<br>用锐利的眼神紧紧地盯着我。<br>我急忙小跑着追了上去。<br>她的脚步似乎快了一些，<br>也多了几分轻快。"},
{index="30140",text="如流水般的舞步，<br>优雅……而又细腻……<br>但是我明白，<br>你那独占欢呼声的柔韧双腿<br>并不会就此满足。<br><br>“麦昆，感觉不错！<br>对手们的视线都好火热啊！<br>哼哼，最佳组合肯定是我们的了！”<br><br>“你已经兴奋起来了呢，<br>节奏变快了哦。”<br><br>“毕竟，再这样下去——”<br><br>“就‘只能’拿到最佳组合奖了，<br>你是想这么说吧？”<br><br>“嘿嘿，就是这样！<br>我们必须有更高的目标！<br>来，跟上我吧……！”<br><br>配合彼此的呼吸，温柔而又优雅地起舞，<br>宛如翱翔于天际的双翼。但是——<br><br>“还不够，我也有我的骄傲……<br>有应该追求的顶点。<br>我还要向着更高处迈进……！”<br><br>“啊哈哈！这才是麦昆嘛——<br>这才是我的搭档！<br>让我们来证明吧——证明我们才是<br>‘史上最棒的组合’！”"},
{index="30141",text="美浦波旁开始用餐。<br>为了高效地补充能量，<br>她正以固定的速度<br>默默地将干瓢卷塞入口中——<br><br>“波旁做的干瓢卷真漂亮呢，<br>是完美的圆柱形。”<br><br>“我是有意识地用均等的力道卷起来的。<br>可以的话，请尝一个吧。”<br><br>“谢谢，那我就不客气了。”<br><br>“波旁，<br>要不要和我的法式冻派换一下？”<br><br>“也尝尝我的炸鸡块吧！<br>这是开餐馆的父母亲传的手艺！”<br><br>“也请务必尝尝<br>我用极快速度做好的三明治！”<br><br>“各位……谢谢你们。”<br><br>美浦波旁收下料理后，<br>静静地露出了微笑。<br><br>（通过刚才的交流，<br>检测到特殊能量得到填充。）<br><br>（也想让大家获得“开心”状态。<br>但是，尚不明确我能否实现……）<br><br>美浦波旁不禁抿紧了嘴唇。<br>然而——看到其他四人后，<br>她的表情再次舒展开来。<br><br>“推测这种能量最重要的……<br>是现在的‘自然的笑容’。<br>开始执行任务‘回馈活力’。”"},
{index="30142",text="接到传球的刹那，<br>樱花桂冠回想起了自己的童年。<br><br>体弱多病的她无法参加激烈的运动，<br>总是只能在一旁观看。<br>每天都站在边线外，<br>笑着将滚来的球递还给大家。<br>她一直憧憬着<br>能和大家一起奔跑。<br><br>而今天，她明白了——<br>和互相信任的伙伴一起比赛，<br>竟是如此令人心潮澎湃。<br><br>樱花桂冠用力蹬地，<br>向着天空高高跃起。<br><br>“我想和这支队伍一起——赢下比赛！！”"},
{index="30143",text="致我亲爱的搭档——<br>小时候，我和你总是形影不离呢。<br>我因为生病无法奔跑，<br>是你载着我去往了远方。<br>能靠自己的力量去到任何地方，我开心极了。<br>那些日子里，我沉醉于不断踩动踏板……<br><br>有一次，我们一起挑战了<br>大家都说无法骑行的山坡。<br>在那仿佛永无止境的坡道上，<br>我们几度想要放弃，但最终还是成功登顶，<br>俯瞰到的大海是何等美丽……<br>那段经历至今仍在支撑着我。<br><br>而今天，与伙伴们不懈努力后，<br>我得以见到一幅美丽的景象。<br>被灯光点亮的舞台、<br>激烈挥舞的应援棒、<br>无数的笑容与欢呼。<br><br>这景色与昔日和你一同看到的高处景色<br>一样耀眼。无论哪一个，<br>都是我独自一人无法抵达的风景。<br><br>将我带到这里的<br>毫无疑问就是你。<br>让我们再一起踏上旅途，<br>去寻找从未见过的风景吧。"},
{index="30145",text="这里是特雷森学园。<br><br>她们有着来自另一个世界的名字。<br>那些名字有着刺激或悠哉的历史，<br>她们继承了那灵魂，<br>悠闲地度过青春……<br>这，就是她们的日常？<br><br>时而有晴天霹雳，<br>时而发生超乎常理的事件，<br>或许也有风平浪静的日子。<br>这——就是她们的日常？！<br><br>那么，今天又会是怎样的一天呢？"},
{index="30146",text="从“信念奔驰”的起点，<br>也能清楚地看到“信念相承”的景象——<br>“祈愿板”燃烧着，<br>化作火星升上天空。<br><br>“小栗，你盯着天空<br>发什么呆啊？<br>马上就轮到咱们的‘信念奔驰’了哦？”<br><br>“没什么，<br>我只是突然想到……<br>总有一天，我也会写下‘祈愿板’，<br>将信念托付给他人吧……”<br><br>“那个时候的自己，<br>到底会在‘祈愿板’上<br>写下什么愿景呢？<br>只要这么一想我就思绪万千……<br>但是，不管怎么想也得不出结论。”<br><br>“哈哈，你现在再怎么想<br>肯定也想不出个所以然啊！<br>对吧，稻荷？”<br><br>“那当然了！<br>为了明天，我们能做的<br>就只有把眼前的事全力做好而已！”<br><br>“对啊！你不如这么想——<br>现在努力，是为了将来能在‘祈愿板’上写下无悔的感言。<br>怀着这种心情去跑不就得啦？”<br><br>“为了写下‘祈愿板’……是啊，<br>阿玉和稻荷说得对。”<br><br>没错，现在只看着<br>眼前的终点奔跑就好——<br><br>只为在终将到来的“那一天”，<br>能在“祈愿板”上写下<br>更多的“谢谢”——"},
{index="30147",text="（哇啊啊啊啊啊——！！）<br><br>足以驱散今日阴沉天空的欢呼声<br>向她倾泻而下——<br><br>那并非如雨点般温柔的欢呼，<br>而是宛如会场中的所有热情都化作声音<br>猛烈捶打着站在赛场上的她一样。<br><br>这场比赛的气氛与往常有些不同，<br>是一场如斗争般火热而激烈的比赛。<br><br>不断追求最强、追逐着憧憬的<br>森林宝袋证明了——<br><br>能得到最强称号的，<br>是站到最后的人。<br><br>“唔噢噢噢噢噢——！！”<br><br>她沐浴着喝彩，<br>发出了撕裂天空般的咆哮。<br><br>（哇啊啊啊啊啊————！！）<br><br>欢呼声仍未停止。<br>撬开新时代之门的少女创造出的这场比赛，<br>以震撼人心的强大吸引着人们的心——"},
{index="30148",text="良辰、吉时。<br>我将色彩缤纷的缎带<br>一圈圈地绕在指尖，等待着某人的到来。<br>传来的脚步声<br>比平时更欢快、更奇妙。<br><br>“你在兴奋什么啊，<br>真是个……笨蛋。”<br><br>从头纱的缝隙中窥见的，<br>是洋溢着喜悦的满面笑容……<br><br>“真是的，为什么你比我还高兴啊？<br>明明只是和决胜服缔结誓约而已……<br>呵呵……”<br><br>我也能理解你的心情，<br>毕竟今天的我最为闪耀。<br>但是，你应该知道的吧，<br>我还远远……不止于此。<br><br>没错……今天是良辰、吉时。<br>冰沙色的裙摆只会翻飞一瞬。<br><br>“把你最棒的笑容留到后面吧，<br>我们的终点……还在前方哦。”"},
{index="30149",text="终于，来到这一步了呢，<br>给你五朵小红花吧。<br>大的小红花、小的小红花，<br>我都准备齐全了。<br><br>发生了很多很多事，也做了很多很多事呢。<br>就算关系再亲密，比赛里也毫不留情。<br>小真的漫画化作品<br>也创下了近百万的销量记录。<br><br>啊，送给你的小真娃娃<br>现在过得还好吗？<br>以后还会有很多很多，<br>建议你先留好放的地方。<br><br>屈指一算，<br>往事已经用双手数不过来了。<br>再过不久，<br>就算加上脚趾恐怕也不够用了吧。<br><br>哎呀呀……<br>你怎么一副糊里糊涂的表情？<br>唔唔，你是忘了吗？<br><br>那可真遗憾，小红花没收。<br>用橡皮擦擦一擦……<br>轻轻松松就擦掉了。<br><br>不过请放心，<br>只要再从一朵小的小红花开始就好了。<br><br>没关系，就让你和我一起<br>创造新的回忆吧。"},
{index="30150",text="“唉～要是能骑着这家伙飙一场，<br>那就真的绝了啊。”<br><br>伏特加一脸怨念地<br>瞪着万里无云的蓝天。<br>引擎似乎早已预热完毕，<br>一副随时准备蹬地出发的样子。<br><br>“嘿嘿……干脆就这样直接出发吧，<br>有种不顾一切的感觉！”<br><br>“时而在海边两人共乘一车，<br>看着水平线飞快地消失在眼角。<br>时而在夜空下，<br>只伴着引擎声的轰鸣一路疾驰向前——”<br><br>就在这时，教堂的钟声响彻四周，<br>其音色宣告着梦想之旅的句点。<br>伏特加将视线从天空移开，<br>咧嘴一笑。<br><br>“不过——也就是个白日梦啦。<br>现在想追逐的东西太多了，<br>光是应付现实【这边】就已经竭尽全力了。”<br><br>“好，我决定了！<br>将来，让我们以不曾改变的自己<br>去实现这个白日梦吧。”<br><br>“在平凡的一天，<br>去一个平凡的地方——<br>然后像傻瓜一样大笑。<br>说定了哦……！”"},
{index="30151",text="毕竟，我一直都很期待呢。<br><br>每次抬起头，你都在我的身旁。<br>我一笑，你也会对我回以微笑。<br>我一开心拉起你的手，<br>你就会无可奈何地垂下眉梢。<br><br>我还想多看看你，还想再多和你玩呀。<br>但是，眼皮……好重哦……<br><br>“重炮，下次……<br>会练习熬夜的……所以……”<br><br>约会……就在梦里继续吧。"},
{index="30152",text="太过戏剧性了——<br>与其说是比赛，倒不如说……<br>像是在观赏一出歌剧。<br><br>欢呼声和喝彩声<br>交织融合，化为歌曲。<br><br>没错，这正是总共八幕的宏大叙事诗。<br>这正是名副其实的<br>大团圆【Grand Finale】——<br><br>“现在，我在此再次宣布！<br>我就是‘世纪末霸王’！！”<br><br>啊啊，我听到了歌声。<br>那是赞美功成名就之人的歌声，<br>那是赞美世纪末霸王的歌声——！"},
{index="30153",text="真希望这个夜晚永远不要结束。<br>被海浪轻抚的沙滩闪闪发光，<br>与白天的样子截然不同。<br><br>如同大海与繁星一般，<br>永不交融的蓝色与黄色<br>就像是舀起了一杯夜色。<br><br>以两人为灵感调制的无酒精鸡尾酒<br>噼啪地冒着气泡——<br><br>本应喧闹的海滩，此刻也仿佛在<br>安抚洒落的月光，轻拍着波浪。<br><br>我总是觉得，<br>自己必须比任何人都闪耀。<br><br>但是，只要和你在一起，<br>我就可以做我自己……<br><br>在潮声之中，<br>挚友映入眼帘的笑容比任何人都更显温柔。<br><br>这个夜晚的月亮<br>如太阳般温暖了两人。"},
{index="30154",text="哎呀，这是去海边时的照片吧！<br>你去玩滑翔伞了呢，<br>看起来好开心啊。<br><br>是啊是啊！<br>海水很清澈，从天上看到的鱼<br>也像宝石一样漂亮哦！<br><br>海豚也跳得好高，<br>都快要碰到滑翔伞了！<br><br>太阳神大呼小叫的，<br>结果把海鸥都引过来了。<br><br>呵呵，不过……<br>你的表情真不错呢，善信。<br><br>你的笑容天真无邪，如同忘记重力、展翅翱翔的<br>海鸟一般自由……<br><br>啊哈哈……嗯，鼓起勇气飞起来后，<br>自由就在眼前延展开来啦。<br><br>呵呵，话说回来，这张照片<br>是怎么拍到的呢？<br><br>其实是太阳神的手机被海鸥抢走啦～<br>不过太阳神不是跟谁都能处得来嘛，<br><br>所以最后海鸥又把手机还给她了～<br>结果就发现手机里拍了好几张这样的照片。<br><br>海鸥也好，太阳神也好……<br>她们到底是什么来头啊？！"},
{index="30155",text="教室里的女孩子们<br>正看着时尚杂志说说笑笑。<br><br>今天我也像往常一样，<br>在教室的角落里望着那些同学。<br>不过我也并不是真的不感兴趣。<br><br>其实，我憧憬着网红，<br>还偷偷关注了她们的社交账号。<br><br>但是，总觉得那不是我这种人<br>可以踏足的地方，<br>所以现在只是看看而已。<br><br>就算踏足了，大家又会怎么看待<br>突然改变的我呢——<br>“随波逐流”“装成熟”<br>我满脑子想的都是这些。<br><br>（叮咚♪）<br><br>手机提示我关注的网红<br>更新了动态。<br><br>“咦……？诶？！<br>这不是太阳神吗？！”<br><br>照片上的是永远开朗活泼的太阳神。<br>但是，今天不一样，<br>她的样子成熟稳重，和平时不同——<br><br>“和平时不一样的我！<br>改变心情嗨起来——！”<br><br>太阳神的表情与平时不同，<br>清爽而妩媚。<br><br>我感受到了她那份享受改变的心情。<br>让别人看到全新的自己——<br><br>我曾觉得那是件有点可怕的事，<br>但我要不要也做出点改变呢……<br>哪怕只有一点点，从微小的事情开始……<br><br>抬起头，<br>我的同学们正一边翻着杂志，<br>一边兴高采烈地看着骏友圈特辑。<br><br>“那个，我能和你们……一起看吗？”"},
{index="30156",text="的确不全是开心的事呢……<br>但是，这世上又有什么<br>只会快乐的事呢？<br><br>被超越也好，<br>被比较也罢……<br>如果想把一件事做到极致，<br>那无论这件事自己多么喜欢，都会遇到困难。<br>一旦屈服，就到此为止了。<br>但是，那样也太无趣了吧。<br><br>最重要的是坚持不懈。<br>只要坚持下去，就一定会有好事发生。<br>会有开心的事，会有快乐的事，<br>那样一来，事情就会变得有趣哦。<br><br>只要不放弃，坚持跑下去——<br>就算变得满身泥泞，也坚持跑下去——<br>就不会输给四次的弯道，<br>在最后的直道上也一定能获胜。<br><br>你看，就像今天的我一样哦。"},
{index="30157",text="我被轻轻地捧了起来……<br>那双温暖的手掌将我<br>连同我赖以呼吸的世界一起捧了起来。<br><br>不被任何人理解也无妨，<br>我的世界并不像他人想象中<br>那般昏暗、冰冷或是寂寞。<br>所以，谁都不要来打扰我。<br>我只有在这里才能呼吸。<br>否则，我会变得无比痛苦……<br><br>那双手并没有试图<br>将我带离我的世界，<br>而是如同不让我的世界有丝毫流失一般<br>小心翼翼地将我包覆起来。<br><br>今天我也在这个世界呼吸。<br>然后，我会望见那耀眼的光芒。"},
{index="30158",text="嗯？在看什么呢？<br>啊！这不是海滩派对时的照片嘛！<br><br>那时候真开心啊！！<br>沙滩排球玩得热火朝天，<br>烧烤吃了个够，<br>看完夕阳沉入大海之后，<br>又放烟花嗨翻天！<br>最后大家还一起仰望星空！<br>速子和茶座也都笑得不行。<br>啊～真想再来一次啊——！<br><br>嗯……？<br>啊哈哈哈！别露出那种表情嘛！<br>海滩派对确实是结束了，<br>但创造最棒回忆这事<br>可没就此结束吧？<br><br>让我们大干一场吧！！<br>不只是夏天，还有春天、秋天、冬天！<br>在接下来的所有季节都是！！"},
{index="30159",text="嗯，辛苦了，玩得开心吗？<br>我吗……？<br>呵呵，如你所见。<br>说实话，<br>我没想到自己能如此放得开。<br><br>遇见未知的自己、<br>遇见无可替代的某人，<br>这些奇迹般的事情能轻易发生，<br>或许正是“这个季节”的功劳吧。<br><br>对了，差点忘了要干杯。<br>为这个季节……为这次相遇，干杯。"},
{index="30160",text="“弥生，你还记得吗？<br>小时候，我们也曾像这样<br>两个人一起仰望星空。”<br><br>“怀念。我们曾向星星许愿，<br>祈愿梦想能够实现。”<br><br>“但是……<br>如今尝尽酸甜苦辣，我才明白——<br>无论多么强烈地祈愿、多么努力，<br>也有无法实现之事，那就是梦想。”<br><br>“正因如此，我们才要将这份经验传承下去。<br>我要培养出比任何人都先跑完<br>隆尚2400米草地的、<br>世界第一的优俊少女。”<br><br>“夙愿——即便不依赖星辰，<br>仅凭我们与当代优俊少女们的力量，<br>也定要实现梦想。”<br><br>“嗯，我们一定要实现。<br>让我们一同见证吧……<br>见证至今为止的国内比赛界<br>未曾见过的景色，<br>见证新时代到来的瞬间——”"},
{index="30161",text="抬头仰望，天空万里无云。<br>脚下的地面虽然沉重，但也无妨。<br>今天，我想在这里飞翔。<br><br>站上起跑位置后，<br>心情自然而然地平静下来。<br>我回忆着一路走来的历程，<br>回忆着让我得以站在这里的人们……<br>我要去夺取那唯一的桂冠——<br>这个梦想已不再属于我一个人。<br><br>我要跑在所有人的前方，<br>跑到那无人能及的地方。<br>我要向着前无古人的顶点——<br>就在今天，就在这里，展翅高飞。"},
{index="30162",text="派对会场格外喧闹。<br>我即使一个人也无所谓，<br>于是打算在角落里安静待着，但是——<br><br>“织姬——！<br>要不要一起逛逛啊？<br>拜托！真的拜托啦！”<br><br>明明不该是这样的……<br>这个永远正确闪耀着、<br>如同北极星一般的人牵着我的手，<br>带我来到了明亮又热闹的会场中央。<br><br>回想起来，这个学园总是这样——<br>明亮、热闹得甚至有些吵闹。<br>回过神来，身边总有人在。<br><br>“说是要拍纪念照……拍下大家的笑容哦！<br>啊哈哈，好挤啊！<br>觉得痒吗？<br>织姬也是？<br>我也是，呵呵！”<br><br>这个学园里总是充满了欢笑，<br>想必今后也会如此吧——"},
{index="30163",text="如果想瞄准“惊天大冷门”……<br>那就是中山庆典了吧。<br>那位优俊少女就是有那种感觉吧？<br>反正都是遥不可及的梦，<br>能实现的话<br>当然要选更梦幻、更有趣、更震撼的……<br>毕竟“那种”梦想<br>才更值得期待嘛。<br><br>嘴上这么说——<br>但我也是比赛前装冷淡，<br>摆出一副老江湖的样子罢了……<br><br>哎呀，<br>毕竟真的亲眼目睹“那个”的时候，<br>人类根本说不出什么像样的话来。<br><br>来了！冲啊……！！<br>难道……<br>终于，要为我实现这个梦想了吗……？！<br>求求你，求求你……！！<br><br>加油啊——！！<br><br>“没错，这样就好。<br>胜负才刚刚开始——”<br><br>“忘掉一切有的没的，<br>去做一个空前绝后的梦吧！！”"},
{index="30164",text="在中山干燥的草地上，怪物爆发出最后冲刺。<br>她在这2500米的战场上以一种<br>狂野、压倒性的姿态将那高潮彻底击溃。<br><br>那是任何人都无法靠近的狂飙，<br>是足以粉碎所有人战意的梦魇。<br><br>已经追不上了……<br>已经无力抗衡了……<br>那是让所有人都如此顿悟的威势。<br><br>然而，<br><br>“还没完呢——”<br><br>一道身影在后方紧追不舍。<br>伴随着强劲的步伐，她拼尽全力追至并排，<br>势要死死咬住前方那只怪物的背影。<br><br>那是绝不屈服的内心；<br>那是牢牢锁定前方的眼眸。<br><br>摇曳间，不屈的灵魂正在升腾。<br><br>“好……来单挑吧！”"},
{index="30165",text="“来吧，在灵魂复印机前列队！<br>为了能在盛大庆典上<br>高举我们的闪耀之剑！”<br><br>“Yes ma'am！<br>那我就站正中间啦！”<br><br>“我就站你旁边啦！<br>来，克里斯也过来吧。”<br><br>“明白了——”<br><br>“喂，别把我夹在吵死人的家伙中间啊。”<br><br>“不，我不会君临此处，<br>而是会化作幻影笼罩你们！<br>创造我的幻象乃贤者的命运！”<br><br>“真没劲……”<br><br>“呵呵，大家都各顾各的呢。<br>真是个奇怪的组合♪<br>不过，也许正因如此才这么有趣吧。”<br><br>“没错，充满个性的、愉快的伙伴们！<br>比起‘福尔图娜的喝彩’，<br>也许‘散装剧团’这个名字更适合我们！”<br><br>“哦？企图改革的反命题吗？<br>既然要赌上名号，就让我来做你的对手！<br>势必对反叛的使徒降下制裁的铁锤！”<br><br>“少废话了赶紧拍！！”"},
{index="30166",text="写出一部剧本这种大工程<br>我可做不来。<br>到了明天，一定会发现比之前<br>写好的剧情还要棒的东西。<br><br>所以比起面对着原稿纸，<br>我会跳上用纸折成的船。<br><br>跃入汪洋大海，水平线上空旷无物。<br>要做的只有一件事！高歌欢笑吧！<br><br>在某处与某人萍水相逢时就愉快地干杯！<br>这才是人生最大的乐趣所在吧。<br><br>谁要老老实实朝着结局走啊。<br>Weave an endless story！<br>我要在属于我自己的故事里一路狂奔到底！"},
{index="30167",text="“请问，克里斯，<br>你脸上那道伤疤真的是化上去的妆吗？<br>看起来特别逼真……”<br><br>“这是贴纸。<br>就像这样——很轻松……就能撕掉。”<br><br>“哇～好厉害！我也想贴在脸上试试♪<br>能借我用一下吗？<br>把这个像这样……好了。”<br><br>“呜……呜呜……为什么？<br>为什么我是人造物呢？<br>我也想和大家一样。<br>所以，拜托了……克里斯——”<br><br>“唔……怎么了——你没事吧？”<br><br>“纳，命，来——！！”<br><br>“美妙……！”<br><br>“啊哈哈哈哈！抱歉啦♪<br>不过，很有万圣节的感觉吧？”<br><br>“对了！<br>也去吓其他人一下吧♪”<br><br>5分钟后，美妙姿势被空中神宫<br>极为严厉地训斥了一顿。"},
{index="30168",text="（前奏）<br><br>哈—— 嘿咻 嘿呀<br>摇摇晃晃的船儿 要出海启航<br>我这艘大大的宝船<br><br>满载着黄金与梦想 扬帆而上<br>去往何方 且问海浪<br>哈 嘿哟<br><br>暴君大章鱼啊 给我听好<br>贵妇石狗鱼啊 给我看好<br>不沉之船 将要启航<br><br>（☆）出发吧 一路向前 黄金船啊<br>驾驭激流 征服漩涡吧<br>伫立船首远眺的 是无尽之梦<br>哈 嘿呀 嘿呀<br><br>摇摇晃晃的船儿 继续驶向前方<br>承载着大家的梦想<br><br>周游世界 不过小事一桩<br>登陆月球 更是易如反掌<br>大渔旗啊 在宇宙中飘扬<br><br>（Rap） 搞庆典 豪赌一场<br>终究不过 浪漫主义<br>全都不是我 拉网小调的 对手啊<br>拿下世界第一 冲啊巨型烟花<br>咚咚锵 咚咚锵 咚咚锵 咚咚锵<br><br>（☆）重复<br><br>哈 嘿呀 嘿呀<br>哈 嘿呀 嘿呀……<br>（淡出）"},
{index="30169",text="“哇……马上就要轮到我们出场了！<br>帝王，你不紧张吗？”<br><br>“心跳确实有一点点加速啦……<br>不过小鹤你和我肯定都没问题的。<br>只要按练习的来，肯定能赢得满堂彩！”<br><br>“你、你的内心真强大啊……<br>我总觉得，有一种和比赛不同的心慌感……<br>呜呜，根本冷静不下来！！”<br>（呼啦呼啦！）<br><br>“啊！小鹤，不能乱动！<br>这可是人家好不容易才帮我们穿好的行头！”<br><br>“脑、脑子里一片空白了啊！<br>感觉脸颊也都僵住了……<br>快放松，快给我放松啊！”<br>（啪啪！）<br><br>“哇，这下脸上的化妆粉都要掉下来了……！<br>小鹤，现在开始禁止乱动！<br>来，跟我一起深呼吸！”<br><br>“诶……深……呼吸……？”<br><br>“代入你的角色，配合我的节奏——<br>吸——呼——”<br><br>“吸——呼——<br>放松身心……保持神秘感……<br>从容不迫地……展露神秘的微笑……”<br><br>“嗯嗯！就是这个表情哦！”<br><br>“呵呵，<br>‘踏出之脚步亦显稚嫩’——怎么样？”<br><br>“‘啊，左手之动作亦显笨拙’！<br>诶嘿嘿，要和我共舞就得这样才行嘛！<br>好啦，该我们上场啦！”"},
{index="30170",text="首先，微微收紧下颌，<br>向着天空，脖颈自然舒展开来。<br><br>抬起手时，动作要轻柔平稳，<br>宛如正在远眺岩石上的飞鸟。<br><br>身体的轴心当如风雨中的竹子，<br>纵然身姿柔韧摇曳，根基却纹丝不动。<br><br>此外，折扇便是手的延伸。<br>从手指到扇骨，再到扇尖，皆不可懈怠。<br><br>“刚才这些，都能理解吗？”<br><br>我的话语，<br>在你体内扎根、生息。<br>当你翩翩起舞之时，<br>我也同样在心中与你共舞。<br>所以——<br><br>“徒弟啊，我的徒弟。<br>练习的时刻到了，且上前来。”<br><br>这一切，就托付于你了。"},
{index="30171",text="今年又迎来了骏典。<br>自心醉于满台起舞的优俊少女以来，<br>我每年都必定来观看，从未缺席。<br>那么，今年会是一出怎样的“奉纳剧”呢——<br><br>“哇哈哈，好开心，好开心啊！！”<br><br>“啊？！”<br><br>我大惊失色，<br>这根本不是我所熟知的演技。<br><br>台词念得结结巴巴，<br>表演透着十足的稚气。<br>这与我看了无数遍的“奉纳剧”截然不同。<br><br>“这……成何体统……！”<br><br>是现代风的改编，还是即兴发挥？<br>无论是哪种，我都无法接受。<br>我垂头丧气地转过身，脚步迈向了出口——<br><br>“啊啊，好开心～好开心啊！”<br><br>然而……<br>她的剑舞竟出乎意料地<br>在我脑海中挥之不去。<br>明明与往年的水准根本无法相提并论，为何——<br><br>犹豫间我缓缓回过头去，<br>正好迎来了整出戏的高潮。<br>她眼神认真，额头上渗出晶莹的汗珠。<br><br>“虽未能承袭师门之绝技，<br>然赐下这般乐事的师父<br>当真是太厉害啦！”<br><br>紧紧握住的剑酣畅淋漓地划破长空。<br>她回眸时的笑颜宛如盛开的樱花——<br>那一瞬间，儿时的记忆闪过脑海。<br><br>胡闹却又拼尽全力的幼年时光<br>一幕幕地如地层般沉积。<br>昔日的自己终与眼前少女重叠——<br><br>“原来如此，所以才会选她啊……”<br><br>我将身心交托给剑舞与庆典乐声。<br>我有预感，到了明天肯定又会有其他人<br>从她身上汲取到活力。"},
{index="30172",text="“感谢你今日来观看棒球比赛。”<br><br>＞客气啦！今天超级开心哦！<br>＞（谢谢！的表情）<br><br>“那真是再好不过了。”<br><br>“中途，我想自己大概让你看到了<br>些许不合礼数的一面，<br>那是因为今天的比赛<br>实在令人过于热血沸腾了。<br>毕竟在9局下半落后6分时<br>还能展开绝地反击，<br>这种场面可不是轻易能见到的。”<br><br>“啊，我对这些不太了解，<br>不过旁边座位的大叔是这么说的。”<br><br>“特别是平局时跑垒员孤注一掷的盗垒，<br>还有之后的安全抢分触击，<br>简直令人拍案叫绝。<br>敢在职业棒球赛场使出这招的胆识<br>和将其完美执行的技巧，实在是精彩绝伦”<br><br>＞原来如此，确实！<br>＞（受教了的表情）<br><br>5分钟后……<br><br>“刚才发了长篇大论，十分抱歉。<br>总之，这段时光很有意义。”<br><br>“若有机会，下次请务必再一起观看。<br>虽然我对棒球并不太了解，<br>若不嫌弃的话我很乐意作陪。”<br><br>“（胜利队最棒了！的表情）”"},
{index="30173",text="在名为草地的五线谱上，<br>踏出一步步足迹【旋律】。<br><br>“呵呵……这场比赛，<br>正是欢愉！”<br><br>这就是她所凝视之物。<br>这就是她所热爱之物。<br><br>助奏？<br>伴奏？<br>什么角色都无所谓。<br><br>“来吧！演奏即将开始！”<br><br>尽情享受这交叠的足迹吧！"},
{index="30174",text="今晚是“目白圣诞夜”……<br>是包括我在内的目白家优俊少女们<br>为支持目白家的各位准备的<br>特别的夜晚——<br><br>“欢、欢迎来到<br>‘目白圣诞夜’！接待处在这里！”<br><br>“诶……要和我合影吗……？！<br>好、好的，我明白了……<br>微、微笑。”<br><br>所以，连不擅长在人群前露面的多伯<br>也鼓足了勇气，<br>接待着来访的宾客。<br><br>“嗯，多伯做得很棒哦……<br>虽然表情还有点僵硬，<br>但每次回应都非常礼貌！”<br><br>刚开始偷偷观察多伯的时候，<br>我还担心这对她而言是不是太难熬了……<br>可现在看来，我或许根本没必要<br>离开自己的岗位过来吧……<br><br>“真是个美妙的夜晚……没想到今年<br>能从目白家收到这样的礼物……”<br><br>“为了让大家度过一个美好的圣诞，<br>我们付出了很大的努力来准备。<br>哪怕只是一点点，如果能让这成为一段愉快的<br>回忆，我们就很高兴了。”<br><br>即使面对陌生的贵妇，多伯也没有怯场，<br>而是用自己的话表达着心声。<br>不知不觉间，我紧绷的表情<br>放松了下来。<br><br>没错，多伯就是这样温柔的人。<br>她总是会在为别人、<br>为大家着想的时候——<br><br>拿出勇气向前迈进。<br><br>“加油啊，多伯！”"},
{index="30175",text="“拉莫娜小姐，午餐已经准备好了。<br>拉莫娜小姐？”<br><br>因为敲门后没有回应，<br>所以我明知失礼，还是打开了小屋的门。<br><br>拉莫娜小姐正在画画。<br><br>那幅抽象画我无法理解——<br>她也无意让外人理解。<br><br>我曾听其他女佣说起过，<br>拉莫娜小姐的腿以前很柔弱，经历过一段<br>无法参加训练的寒冬。<br>而当时的她所画的，就是抽象画。<br><br>她将那些激情、<br>陶醉、<br>炽热、<br>忧郁——<br><br>尽情挥洒在了画布上。<br>据说拉莫娜小姐的作品和她本人一样，<br>美得难以用言语形容。<br><br>可如今，又是为何？<br>她为何又一次拿起了画笔——<br><br>“完全无法和那时相提并论。<br>不过，这也不奇怪——<br>毕竟我现在，可以去见我的所爱。”<br><br>我不明所以，却屏住了呼吸，<br>甚至不知自己究竟为何而感到震撼，<br>唯有默默沉浸在她的美丽之中。<br><br>“雪停了，<br>那就……去倾诉爱吧。”<br><br>拉莫娜小姐说完，<br>便安静地走出了房间。<br>于是，被留下的<br>便只有未能完成本职工作的我，以及——<br><br>那片她在纯白画布上绘出的<br>郁郁葱葱的新绿。"},
{index="30176",text="临近圣诞节的某一天——<br><br>“唔～看着琳琅满目的商品，<br>不知道该怎么选了呢～”<br><br>“是啊……虽然莱恩不管收到什么，<br>好像都会很开心……但既然要送，<br>还是想送真的能让她高兴的礼物呢。”<br><br>“那我们送跑鞋如何？<br>莱恩姐姐她以前<br>非常耐心地陪我<br>选过跑鞋呢～”<br><br>“所以，这次我想<br>认真地为莱恩姐姐<br>选一双跑鞋。”<br><br>“原来她一直等到光明你<br>选好为止啊……呵呵，真有莱恩的风格。”<br><br>“小时候晚上打雷，<br>她也紧紧握住过我的手呢。<br>莱恩她明明讨厌熬夜，却为了我<br>一晚没睡……<br>她这一点真是让我甘拜下风啊。”<br><br>“要送她什么，才能报答她呢……<br>助眠用品之类的？不过莱恩<br>入睡应该不怎么困难吧——”<br><br>“本店将于30分钟后结束营业，<br>期待您的再次光临。”<br><br>“诶，已经这么晚了吗？！<br>呃，该怎么办呢……<br>比想象中还要难挑……”<br><br>“没关系的哦，多伯。<br>想要传达感谢，就是要花时间。<br>要不然，这份感激的心意<br>就无法完全传达出去哦～”<br><br>“呵呵，你说得对。<br>那明天我们再到处看看吧。”"},
{index="30177",text="维普露斯冲了出去。<br>虽然记者们还有很多问题想采访她，<br>但他们也很快意识到了<br>维普露斯冲出去的理由并无奈地笑了笑。<br>使疲劳至极的双腿恢复活力的，<br>是进入她视线里的某个身影。<br><br>“姐姐，姐姐～<br>你看到我冲过终点的瞬间了吧？！<br>我是冠军哦，冠军！<br>我真的赢下比赛啦！”<br><br>看到天真无邪的妹妹<br>朝自己跑来，<br>极峰感慨万千地上前迎接。<br><br>“谢谢你……维普露斯……！<br>你刚才的最后冲刺真的是太厉害了。<br>你今天，让我见识到了<br>我那时未能触及的……<br>前方七厘米之遥的风景。”<br><br>“诶嘿嘿～再多夸夸我♪”<br><br>“明明到最近为止，<br>我都以为你还是个爱撒娇的妹妹呢。<br>没想到你在不知不觉间都变得这么强了。”<br><br>“毕竟我的姐姐是以好胜心出名的嘛！<br>既然决定了要赢，就一定要做到！<br>啊，但是就算我变强了，也是你可爱的妹妹。<br>这点是不会变的哦♡”<br><br>“呵呵呵，是啊。<br>我也想再多看看……<br>强大而又可爱的维普露斯的亮眼表现。”<br><br>“嗯！<br>以后不管是参加大型赛事，<br>还是遇到强劲的对手，<br>我也都会不断取胜的！<br>姐姐你到时候<br>可要再多夸夸我哦♪<br>好不好嘛，就这么说定啦♡”"},
{index="30178",text="“鸣声雷动向外侧大幅偏移！<br>非常棘手的失误！！”<br><br>观众们的哗然之声<br>夹杂在呼啸的风声里传入了耳中。<br><br>感觉就像失去了<br>对自己身体的控制权一样。<br><br>（我这是失去理智了吗……？！）<br><br>不，并非如此。<br>这不是被紧张吞没的感觉，<br>而是仿佛要从体内溢出的冲动——<br><br>“哈啊啊啊啊啊啊啊啊！！”<br><br>“鸣声雷动从外侧冲上来了！<br>她居然从外侧冲上来了！！”<br><br>是啊……这是流淌在我血液中的冲动；<br>是身为一族结晶的骄傲；<br>是我在激励自己，<br>要我证明自己就是“最强”……！<br><br>“鸣声雷动！！<br>竟然强到了这种程度吗？！”"},
{index="30179",text="净手池水浮鲜花。<br>绚烂的花朵为距离春意尚远的新年<br>增添了一抹斑斓。<br>这份美丽让我们二人<br>一时看入了迷。<br><br>你小声说道——愿望终将花开，<br>努力让它绽放吧。<br><br>净手池面漂满鲜花。<br>有多少花，就有多少愿望——<br>在我所背负的里见之名下。<br><br>滴答滴答落下的水珠<br>使水面泛起层层涟漪。<br>让人回想起曾几何时沿着脸颊滴落之物。<br>众多花朵未能绽放。<br><br>就由我来让它们全部绽放吧。<br><br>我一定会让这一生仅有一次的、最华丽的舞台<br>如同这浮满美丽鲜花的净手池一样，<br>开满愿望之花。<br><br>“嗯，让花开满舞台吧。”<br><br>你坚定地点了点头——<br>温暖的笑容就像落在花蕾上的阳光一般。"},
{index="30180",text="优俊少女——<br>拥有着时而坎坷，时而辉煌的历史。<br>她们背负着另一个世界的名字，继承其精神，<br>是为奔跑而生的存在。<br><br>经历重重赛事，最终<br>她们自身也将被铭刻于历史中。<br><br>“我要成为全国第一的优俊少女……！”<br><br>与两位母亲的约定——<br>怀揣着要成为“全国第一”的壮志<br>离开故乡的少女与诸多对手<br>驰骋于赛场，历经失败与胜利，<br>最终实现了梦想。<br><br>“就算这样我也要赢。”<br><br>追寻“皇帝”背影的“帝王”<br>即使历经挫折，<br>内心也不曾放弃，<br>让一起奔跑的朋友和<br>激励自己的对手<br>见识到了自己创造的奇迹。<br><br>“大家都说，<br>想看我奔跑的样子。”<br><br>少女怀揣着对不屈“帝王”的崇拜，<br>与许下了约定的挚友一起<br>纵身跃入了比赛的世界里。<br><br>虽然也曾对自己的梦想感到迷茫，<br>但最终还是找到了自己的路，<br>成了受人们喜爱的<br>庆典少女。<br><br>而接下来——<br><br>“啊，小特前辈，这里！”<br><br>“抱、抱歉久等了！<br>想着为了提振精神去填填肚子，<br>结果东西太好吃了就……”<br><br>“真是的～比赛都要开始了哦？<br>对了！<br>反正都要到检阅场去，<br>不如来赛跑吧？<br>以此来决定我们当中谁才是第一♪”<br><br>“噢，听起来很有趣呢！<br>小特前辈，要试试看吗？”<br><br>“正合我意！<br>虽然我是最后一个到这儿的，<br>但接下来我会第一个冲到终点！”<br><br>“那就——预备，跑！！”<br><br>她们的轨迹至今仍在延续。"},
{index="30181",text="“接下来要唱《自此已成万众之……》喽！<br>大家跟着涡轮一起唱——！！”<br><br>“点燃梦想的烈焰～<br>拨动冲线的心弦♪”<br><br>“绝望不会阻止我向前！<br>唔，后面是……？<br>极限什么的哼哼哼哼～哼♪<br>噔噔楞噔噔楞♪涡轮的领先！！”<br><br>“（哎呀……涡轮她<br>是忘词了吗？<br>莱斯、素质，<br>该我们出场了！）”<br><br>“（嗯，帮她打掩护！<br>练习的时候涡轮就经常会<br>忘记主歌和导歌的歌词……<br>那就以乐器为主蒙混过去！）”<br><br>♪♪♪～～～♪～♪♪～<br>♪♪～～♪♪♪♪～♪♪<br>沙卡沙卡沙沙沙卡沙！<br><br>“唔唔唔，声音变大了！<br>意思是更加嗨起来吗？！<br>好——！”<br><br>“Go！Go！Let's Go！噢——噢噢——噢！<br>Go！Go！Let's Go！涡轮超强！<br>Go！Go！Let's Go！唔噢——噢噢噢！<br>上啊上啊Go！Go！涡轮全开——！！”<br><br>“不是，这怎么还唱得更大声了？！<br>而且歌词也还是错的！”<br><br>“呵……加快节奏吗？好啊！<br>涡轮，就让我来效仿你的热情吧！！”<br><br>“呃，好快……但我必须跟上！<br>坚持住啊，莱斯！”<br><br>“你们俩指法好离谱！而且太快了太快了！！<br>节奏这么快的话——”<br><br>“无论多少次，哪怕无数次！<br>全力以赴——！！<br>无论，多少次！<br>哪怕无数次……哈啊……哈啊……！<br>绝——不，放，弃——！<br>呼……哈，哈啊——嘿嘿嘿嘿！”<br><br>“唔噢噢噢噢噢噢噢噢，涡轮，<br>是，不，会，输，的——！！”<br><br>“我的天啊，果然变成这样了——！<br>所有人都被涡轮的节奏带着走，<br>场面收不住啦！！”"},
{index="30182",text="映入眼帘的是耀眼的光芒。<br>熟悉的故乡会场里<br>满是熟悉的面孔。<br><br>“唱歌和跳舞<br>都非常熟练了呢……！<br>不愧是我们的地方偶像啊！”<br><br>“是啊，多亏了她，<br>愿意来这里观光的游客也变多了。<br>她真的很可靠，是我们的骄傲啊！”<br><br>听着这些温暖的话语，看着这些人的笑容，<br>眼眶不禁阵阵发热。<br>因为曾经微弱的光芒<br>如今充满了灿烂绽放的笑容，<br>如此耀眼。<br><br>“接下来是最后一首歌！<br>请听——”<br><br>“《苫小牧欢迎你》！”<br><br>无论前路多么泥泞，<br>就算脚步屡屡受阻，<br>我今后也会一直奔跑下去。<br><br>这都是为了用这双腿守护那不想失去的地方。"},
{index="30183",text="小雪好像在房间里<br>找到了她故乡的点心食谱。<br>因为她说“久违地想做一做”，<br>所以我打算<br>去旁观一下——<br><br>小雪的手艺超级好呢！<br>动作又快又灵巧，而且非常细致！！<br><br>“好厉害好厉害！！<br>最后捏那一下<br>很关键呢！！”<br><br>“小雪，你真的太厉害了！！<br>连细节都能做得这么漂亮，<br>真是太厉害啦——！！”<br><br>“真、真是的，奖券，<br>你太夸张啦～”<br><br>“不过……还是谢谢你。<br>我真的很高兴♪<br>好——我要再加把劲喽！”<br><br>做点心时的小雪<br>看起来真的好开心！<br>看着她那副模样，总觉得连我也<br>变得想做点心了。<br>柜子里应该有围裙和三角巾——<br>好，来做吧！！<br><br>接下来，就是考虑要做什么了……<br><br>“啊，想到了！！”<br><br>根据脑海中浮现出的形象，<br>我也动起手来。<br>感觉做得还挺不错的嘛！<br><br>“耳朵像这样捏一下！！<br>然后，把豆沙揪成小块……<br>轻轻地放上去——”<br><br>“做好啦——！！”<br><br>“哇，好可爱啊♪<br>笑眯眯的，<br>看着就是个很温柔的点心呢！”<br><br>“诶嘿嘿！<br>这个啊～是小雪哦！！<br>看着开心的小雪，<br>我也变得想做点心了，<br>然后就想着干脆做成小雪的样子了！”<br><br>“哎呀呀？！<br>你说这个是我吗？！<br>这样啊，我真的很开心嘞！”<br><br>“嗯嗯，就是这个表情！<br>果然一模一样呢！！”<br><br>“诶嘿嘿……奖券，<br>我看着奖券的脸，<br>也变得想做点心了。<br>我能再多做一个<br>奖券的点心吗？”<br><br>“小、小雪——！！<br>当然可以啦——！！”"},
{index="30184",text="　　　　　　　问候<br><br>作为大家的班长，<br>我将平日里的感谢倾注在点心里送给大家！！<br>感谢，那是美丽的心意！<br>而说到美丽，那就是樱花！！<br>所以，我制作了樱花花瓣形状的<br>点心！<br>做出来的成品<br>也是非常美丽哦！<br>因为，这是美丽×美丽嘛！！<br>　　　　　　　　　樱花进王<br><br>虽说只是一句“感谢”，<br>但我认为它有着各种各样的形式。<br>想制作樱花花瓣形的点心——<br>我从进王的这个想法中，<br>想出了改编的创意。<br>由5瓣组成的，美丽花朵。<br>由5种颜色组成的，各种感谢。<br>在打开盒子时请用眼睛品味，<br>送入口中时也尽情享受吧♪<br>　　　　　　　　　　　　北方飞翔<br><br>　　　　　　　菜单<br><br>一、感谢活力<br>　酥脆的曲奇！<br>　明亮的黄色带来力量！<br><br>二、感谢温柔<br>　甜甜的粳米点心！<br>　可爱的桃色温暖人心！<br><br>三、感谢笑容<br>　软糯弹牙的团子！<br>　亲切纯洁的笑容会带动周围一起笑出来！<br><br>四、感谢严格<br>　稍微有些硬的糯米点心！<br>　甜味会在之后慢慢散开！<br><br>五、感谢梦想<br>　闪亮的金箔羊羹！<br>　来吧，让我们共同进步，走向闪耀的未来！"},
{index="30185",text="“哦？复古风的外套？<br>哎呀，这个品牌！<br>我都不知道还出了这样的新款！<br>以前我和母亲还聊过<br>这个品牌有高端的感觉，很棒——不对，咳咳。<br>谢谢你，飞翔。<br>不仅能衬托帝王我的高雅气质，<br>还能展现出我新的一面，<br>真不愧是时尚达人呢！”<br><br>“呀～是街头风呢！<br>宽松连帽衫搭配短裤，<br>再配上带点俏皮设计的<br>厚底运动鞋……<br>呵呵，一说到这些就好想出门呀♪<br>真想快点让大家看看<br>在网红景点打扮得漂漂亮亮的机伶啊！<br>到时候飞翔也一起<br>来场骏友圈直播怎么样？”<br><br>“好厉害……这是只有在精选店<br>才有卖的饰品吧？<br>你的消息真的很灵通呢，飞翔。<br>有机会再交流一下信息吧。<br>作为回报，<br>我也会带最新的单品情报过来的。<br>话说，我真的很佩服<br>你那份钻研的劲头，不骗你。”<br><br>无论是你，还是别人，<br>又或是我！<br>每个人体内都蕴藏着与生俱来的珍贵原石，<br>那正是光芒的源泉。<br><br>我想打磨它，让它绽放光芒！<br>如果能帮上忙，<br>那就是最令我高兴的事了。<br><br>那么——你好呀，新的原石！<br>要和我一起寻找绽放光芒的方法吗？"},
{index="30186",text="让我来看看，这次与我交锋的<br>会是怎样的人呢？<br><br>“就准许你在近处拜谒<br>我这金色的称霸之路吧。”<br><br>“我很期待<br>把所有人甩掉，突破通往<br>最强【顶点】大门的那一刻！”<br><br>“作为证明我的血脉以及最强之名的对手——<br>再合适不过了。”<br><br>“我要赢！赢下比赛……然后由我来<br>开辟出后冠优俊少女的道路！”<br><br>哎呀，真棒。<br>在这里奔驰的优俊少女<br>个个都拥有金刚石般<br>璀璨且坚韧的意志……<br><br>“也正因如此，才更有粉碎的价值呢。”"},
{index="30187",text="接受玉盏的洗礼吧。<br><br>君临者乃激情的霸王。<br>立于草地之巅，将世间万物踩在脚下。<br><br>其霸业犹如艺术，<br>其征途宛如风暴，<br>将世界染成金色。<br><br>退避吧，膜拜吧，下跪吧。<br>我等唯有——仰望其尊贵姿态。"},
{index="30188",text="我有想要传达的热情，<br>有想要传递的感动。<br><br>所以，今天我也要继续寻找。<br><br>寻找那个梦想最闪耀的舞台，<br>那个灵魂最璀璨的瞬间——<br><br>“怎么样，凉花！<br>有没有展现出我熊熊燃烧的干劲？”<br><br>“嗯，表情很不错哦。<br>艾尔菲的热情<br>即使隔着屏幕也能传达出来呢。”<br><br>“我决定了，这次的视频<br>就用这个镜头吧。<br>辛苦了，艾尔菲。”<br><br>“太好了——！<br>谢谢你！”<br><br>“诶嘿嘿～希望这次的视频<br>大家也能看得开心呢！”<br><br>“不用担心，<br>大家一定会很高兴。”<br><br>因为你是如此耀眼——<br><br>散发着能给予人们力量的<br>璀璨光芒。<br><br>而将这份光芒毫无保留地传递出去，<br>甚至在适当的时刻让它变得更加闪耀，就是我的工作。<br><br>“对了，凉花！<br>待会儿能跟你聊聊吗？<br>是关于下一个企划的事——”<br><br>“哎呀，是吗？那我们就趁现在<br>简单地开个会吧，<br>反正拍摄已经顺利结束了。”<br><br>“我明白了！<br>这样更干脆利落又合理！对吧？”<br><br>“呵呵……没错。”<br><br>好了，今天也来打造<br>震撼人心的娱乐作品吧——<br><br>与我最棒的搭档一起。"},
{index="30189",text="手牵着手。<br>怀着梦想开始的激动心情。<br>一起穿过了那扇大门。<br><br>“我也绝对要成为！<br>像帝王前辈那样的优俊少女！”<br><br>“我也要，像麦昆前辈那样。<br>作为里见家的优俊少女绽放光芒！”<br><br>憧憬的地方，教会了我们梦想的形状。<br>许多的相遇，为未来增添了色彩。<br><br>曾经只有我们两人的世界，向着无尽的远方扩展——<br><br>“我先走一步了哦，小钻！”<br><br>“嗯。我会追上去……一定会追上你的”<br><br>道路岔开，各自向前。<br>然后再次交汇、碰撞。<br><br>“小钻……<br>我一直都在期待这一天的到来！”<br><br>“我也是。不过……<br>我会超越你，赢得胜利”<br><br>“来一较高下吧！”<br><br>好了，该松开紧握的手了。<br><br>为了夺得那唯一的光芒！"},
{index="30190",text="她渴望着成为“最强”。<br>即使被迫承受了长达九个月的空窗期，<br>也要将自己的血脉铭刻在历史之中。<br><br>“我将展现<br>任何人都能理解的最强”<br><br>她追求着“荣冠”。<br>为了给里见家留下名誉的功绩，<br>回应一族的期待。<br><br>“人气第一可以让出去，但冠军非我莫属——<br>区区逆境，看我将其逆转！”<br><br>既然彼此都有追求的“理想”——<br>那么争夺比赛的荣耀，便是必然。<br><br>“以绝对之势，使其屈服”<br><br>“就让我展示一下，完美的计划吧！”<br><br>她们各自怀揣着激情<br>驰骋着。"}
}
p.text_data_163={
{index="1001",text="我叫特别周！<br>梦想是成为全国第一的优俊少女！<br>为了让妈妈她们开心……我会加油嘞！"},
{index="1002",text="我叫无声铃鹿，我很喜欢跑步。<br>领头的位置，我不会让给任何人。<br>嗯……就说这些吧。"},
{index="1003",text="呀吼，我是东海帝王！<br>务必关注会成为<br>零败三冠优俊少女的我哦！"},
{index="1004",text="Hi，我是丸善斯基！<br>异次元的跑法，你也是来看这个的吧？<br>哼哼♪要是被我迷得神魂颠倒的话……<br>我可不管哦♪"},
{index="1005",text="我是负责让大家开心的漆黑表演者<br>富士奇石！我一定会用最棒的“奇迹”<br>让你露出笑容！"},
{index="1006",text="我叫小栗帽。<br>为了让故乡的大家开心，<br>我会全力以赴。请多指教。"},
{index="1007",text="哟，我是黄金船大人！<br>管它是在火焰里还是草地上！<br>即使是宇宙的尽头也无所谓！<br>我会追寻有趣的东西直到天涯海角☆"},
{index="1008",text="噢，我是伏特加！我的原则是时刻保持<br>身为最帅气优俊少女的形象！<br>逊爆了的事我绝对不会做，给我记好了！"},
{index="1009",text="你好，我叫大和赤骥！<br>我会竭尽全力……啊，是你啊。哼！<br>我的目标只有第1名，除此之外什么都不要！"},
{index="1010",text="Howdy！我是大树快车！<br>我要用马力全开的奔跑<br>带给大家快乐！"},
{index="1011",text="我是草上飞。<br>既然作为优俊少女出生，<br>就要在这条“道路”上钻研到底。呵呵♪"},
{index="1012",text="这里有很多神气十足的家伙啊……<br>嘿嘿，让菱亚姐来会会你们！来单挑吧！"},
{index="1013",text="我是目白麦昆。我的家族，<br>目白家的夙愿——称霸“天王奖”<br>就用我的双腿来实现吧。"},
{index="1014",text="奔跑于赛道的赤红怪鸟！<br>神鹰登！场！啦！<br>以世界为目标，奋勇前进！"},
{index="1015",text="哈——哈哈哈！我是最强大<br>最美丽的“霸王”——好歌剧！<br>让传说就此开演吧！"},
{index="1016",text="我是成田白仁。<br>没什么特别想说的。<br>我只需要把所有人都远远甩在后面，<br>夺得比赛的胜利。"},
{index="1017",text="我是鲁道夫象征，是站在所有优俊少女<br>的顶点为她们引路的“皇帝”。<br>志同道合的同志们，一起勇往直前吧。"},
{index="1018",text="我是气槽。只要坚定信念，<br>理想定会发芽。为了证明这一点，<br>我会作为“女帝”为大家指明方向。"},
{index="1019",text="辛苦喽！我是小数码！<br>我是光彩夺目的优俊少女们的粉丝！<br>每天都好幸福！能成为阿宅真是太幸运了♪"},
{index="1020",text="呀吼，我是青云天空哦——<br>适度随意且悠闲地活下去吧——<br>放长线才能钓大鱼，对吧？"},
{index="1021",text="咱叫玉藻十字！咱呀，要在比赛中<br>获胜获胜再获胜，成为大明星！<br>别因为咱个子小，就小看咱！"},
{index="1022",text="您好，我是美妙姿势！<br>我想尽可能多地创造美好回忆。<br>首先我想了解一下好吃的拉面店♪"},
{index="1023",text="我是琵琶晨光。<br>我的目的，是创造无懈可击的胜利公式。<br>还有，我的头围在正常范围内！"},
{index="1024",text="诶嘿嘿，我是重炮亲哦☆<br>特别喜欢令人兴奋的事<br>和刺激的事，请多指教！"},
{index="1025",text="我是……曼城茶座。<br>我想追上……一个朋友……<br>她总是跑在我前面……看，就在那里……"},
{index="1026",text="我的名字是美浦波旁。<br>当前设置的目标是成为三冠优俊少女。<br>跑法等信息请参考其他数据。"},
{index="1027",text="我叫目白莱恩！<br>锻炼身体就能精神饱满！锻炼肌肉<br>就能健康强壮！鼓足力气加油吧！"},
{index="1028",text="buono～buono♪我是菱曙☆<br>无论是料理还是赛跑，我都会<br>为大家献上大大——的爱！请多关照♪"},
{index="1029",text="我、我叫雪之美人！<br>我的梦想是成为在闪耀之星系列赛里获得成功<br>的城市少女！呼……成功说出来了……"},
{index="1030",text="我叫……米浴……那、那个？<br>米浴，会让大家陷入不幸……很没用……<br>但是……我、我会加油改变的！"},
{index="1031",text="哈喽哈喽！我是艾尼风神！<br>为了让家人们开心，不管是比赛还是打工，<br>我都会加油的！"},
{index="1032",text="优俊少女究竟可以快到什么程度……<br>你对此也不感兴趣吗？如果有兴趣的话……<br>就来成为我——爱丽速子的小白鼠吧！"},
{index="1033",text="我是爱慕织姬……我可以走了吗？<br>我要更努力地训练、赢得比赛。<br>因为我必须成为一等星。"},
{index="1034",text="你说啥呢！我是稻荷一！<br>如你所见，我是土生土长的江户人！<br>我要成为最厉害的优俊少女！"},
{index="1035",text="我我我！我的梦想是成为德比优俊少女！<br>还有……啊！名字！<br>我叫胜利奖券！请多指教！"},
{index="1036",text="我叫空中神宫。任何比赛中<br>数据都很关键。模拟实验没有异常，<br>让我来扳倒你吧，用我的逻辑。"},
{index="1037",text="我是荣进闪耀。为了保护优俊少女的传统，<br>我会一直奔跑下去。不管是什么样的比赛，<br>我都会严格按照计划进行。"},
{index="1038",text="我是Curren，真机伶！<br>让世界被“可爱”包围吧☆<br>不许东张西望哟。你只能看着机伶♪"},
{index="1039",text="哦——呵呵！我是川上公主……<br>没错，我就是高贵优雅的公主中的公主！<br>比赛中我也会以可爱动人的身姿飞驰到底！"},
{index="1040",text="我是黄金城……事先说好，<br>绝对不许把我当成换装娃娃。<br>别看我的外表，靠我的跑步表现来评价我吧。"},
{index="1041",text="你好！我是樱花进王！<br>如你所见，我还是一名优秀的班长！<br>为了成为大家的榜样，现在！前进吧！"},
{index="1042",text="呵——呵呵呵！我是采珠！<br>你知道吗？这个世界充满了可能。<br>我一定会证明给你看！"},
{index="1043",text="嗷呜！我是新光风！<br>害怕了吗？你肯定害怕了，老实承认吧！<br>喂！别无视我！我咬！"},
{index="1044",text="东商变革是变身前的名字！<br>我是天才魔法少女小革！<br>这就是魔法哦！嘿！（咚）"},
{index="1045",text="呵呵，我是超级溪流哦～<br>为了让大家露出笑容，<br>我会非——常努力的。交给我吧♪"},
{index="1046",text="我是醒目飞鹰！叫我飞鹰子吧！<br>我的梦想是成为优俊偶像！<br>随时都可以找我要签名哦☆"},
{index="1047",text="我叫荒漠英雄。那个……虽然我<br>并不强大，但是我非常向往英雄传说……<br>总有一天，我要在比赛中书写自己的故事！"},
{index="1048",text="我是岛川乔丹。我的梦想是……<br>我可不想聊这种严肃话题哦☆<br>总之你先看看我的美甲！很漂亮吧？"},
{index="1049",text="我是中山庆典。<br>不温不火的比赛可没法让我感受到刺激啊。<br>我说……让我更兴奋吧！"},
{index="1050",text="我是成田大进，就这样。我只想<br>包揽胜利，让那些看不起我的人<br>好好看看。不要管我……"},
{index="1051",text="你好，我是西野花。<br>我想成为值得大家信赖的、<br>优秀的优俊少女大姐姐！"},
{index="1052",text="我是春乌菈菈！最喜欢胡萝卜，<br>跑步也超——级喜欢♪<br>为了拿到第1名，我会努力加油！"},
{index="1053",text="嘿！我叫青竹回忆！<br>赌上魔鬼纪律委员长的名号，<br>我会努力奔跑的！"},
{index="1054",text="正义的英雄，微光飞驹登场！<br>我的奔跑可以击败一切强敌<br>让大家的脸上露出笑容！厉害吧！"},
{index="1055",text="嗨嗨，我是美丽周日！<br>我要将marvelous的心情传递给全世界！<br>大家一起来，marvelous！"},
{index="1056",text="你好！我叫待兼福来！<br>坚信白兴大人的神谕，等待福气到来……<br>同时也在夜以继日地钻研占卜！"},
{index="1057",text="有一种风只存在于赛场之上。<br>那是轻盈、澄澈的……随心所欲的顺风哦。<br>我是千明代表，请多关照。"},
{index="1058",text="我叫名、名将怒涛！那个、那个，<br>我想变得更自信，<br>我会竭尽船力……说、说错了！"},
{index="1059",text="你好……那个，我是目白多伯。<br>我也是目白家的优俊少女，<br>所以要跑出不负家族之名的成绩……我是这么想的。"},
{index="1060",text="啊……我是优秀素质。啊哈哈，<br>“优秀的素质”这个名字果然名过其实了吧……<br>哎呀，慢慢来吧？"},
{index="1061",text="哦——呵呵！我的名字是帝王光辉！<br>作为一流的优俊少女，我会创造最优秀的<br>成绩！这也是为了向全世界展现我的才能！"},
{index="1062",text="呀吼，我是待兼唐怀瑟哦。<br>为了不输给大家，我得努力<br>训练……诶，今天休息？！"},
{index="1063",text="我叫生野狄杜斯。<br>管理工作就交给我吧。<br>我会用钢铁般的意志实行严格的管理方针。"},
{index="1064",text="我是目白善信！你好呀～<br>遇到难题的时候，随时都可以找我聊天哦。<br>不要有顾忌，放开说♪"},
{index="1065",text="耶——我是大拓太阳神！<br>我会让比赛嗨翻天，所以<br>麻烦你们提供史上最棒的欢呼声☆"},
{index="1066",text="我是双涡轮！<br>涡轮要拿第1，一定要拿第1！<br>冲吧，开足涡轮！"},
{index="1067",text="我叫里见光钻。<br>这个世界上不存在什么命中注定。<br>我要用奔跑，让未来绽放光芒！"},
{index="1068",text="我是北部玄驹！<br>我的目标是让比赛像庆典一样<br>使大家热情高涨，为此我要全力奔跑！"},
{index="1069",text="我、我是樱花千代王！<br>为了和我憧憬的那个人一起站上梦想的舞台，<br>我要让这份信念……开花结果！"},
{index="1070",text="我是天狼星象征！<br>比赛不需要讲什么大道理，静静地看着吧。<br>我要征服世界，向所有人证明我才是“最强”。"},
{index="1071",text="我叫目白雅丹。<br>即使这双腿如此脆弱，我也要骄傲地跑下去……<br>哪怕转瞬即逝，我也要在赛场上绽放光芒"},
{index="1072",text="我是八重无敌。作为金刚八重垣流<br>的门生，我渴望和强者交手。<br>来吧，一决胜负！"},
{index="1073",text="我是鹤丸强志！总之我会向着憧憬的<br>“三冠优俊少女”全力——咳咳！<br>只、只是呛到了而已！我很好不用担心！"},
{index="1074",text="哎呀？是该做自我介绍了吗？<br>呵呵，我叫目白光明。<br>身为目白家的一员，我会努力的～"},
{index="1076",text="我是樱花桂冠。我的目标是世界，是凯旋门奖！<br>呵呵，虽然现在这还只是个“梦”……<br>但我将来一定会让它实现的"},
{index="1077",text="你好，我是成田路！<br>为了不辜负大家的支持和期待，<br>我会全力以赴的！"},
{index="1078",text="我是山人西风……<br>我的目标，是风……<br>我想要成为快过一切、自由驰骋的风"},
{index="1082",text="嗯，我是北方飞翔！服装、妆容、饰品，<br>还有坚持不懈的努力——请见证由这一切<br>雕琢而成的、属于我的闪耀光芒吧！"},
{index="1083",text="我是克里斯象征，象征家对我有恩。<br>作为其中一员，不论是自己立下的目标<br>还是被赋予的任务，我都会将其完成"},
{index="1084",text="我是谷水琴蕾！我追求的是理想的“我”。<br>我无意伪装这个暂居的自我。尽情破坏，<br>踹破一切——然后向着终焉前进吧！"},
{index="1085",text="我是第一红宝。<br>登峰造极乃我们一族的责任。<br>为履行己身之责，我定将勇往直前"},
{index="1086",text="想要了解我？那就请移步草地吧。<br>我是目白拉莫娜……我的一切都在那里。"},
{index="1087",text="我是小真——阿斯顿真弓。<br>总有一天我会成为世界的吉祥物。<br>请用你的双眼一直注视着我哦"},
{index="1088",text="我是里见皇冠。我一定会为里见家夺得荣冠。<br>为此我会做好一切能做的准备，<br>把逆境也化作力量！敬请期待吧！"},
{index="1089",text="我是高尚骏逸……唔，我知道自己有些不自量力。<br>但是……总有一天——<br>我、我会成为伟大的优俊……没什么，我会努力的。"},
{index="1090",text="我是极峰。<br>总有一天我会打破一切成为女王，<br>在那之前我决不会气馁。"},
{index="1091",text="我是维普露斯哦！总有一天，我一定要在<br>闪闪发光的迪拜跑一场有名人风范的比赛♪<br>我们一起去吧！毕竟我都决定好啦♪"},
{index="1093",text="我是……喜嘉奇迹。<br>为了回报赐予我生命的大家……<br>我一定会创造奇迹"},
{index="1094",text="我是森林宝袋。<br>想跑的话，我随时奉陪。<br>不过，“最强”的宝座可不会让给你。"},
{index="1098",text="Rickey☆Lucky☆大吉大利☆<br>我是小林历奇！我会用风水的力量<br>为你也带来幸福的哦♪"},
{index="1099",text="我是从北方港口飞来的纸翼候鸟♪<br>苫小牧的地方偶像——北幸樽前嘞♪<br>唔……是不是该想个更别致的说法呢"},
{index="1100",text="我是奇锐骏。<br>虽然性格悠哉，但我可是很擅长<br>踏踏实实努力哦。请多指教啦"},
{index="1102",text="啊，我深爱的音乐家们！<br>今天也与我万籁争鸣一同，<br>让彼此的旋律交织相融吧！"},
{index="1103",text="我想要的——只有“最强”的称号哦！<br>我要成为铭刻在人们记忆中的优俊少女！<br>为此我所需的……没错，就是自我包装哦！"},
{index="1104",text="我是葛城荣主，请多指教！<br>有梦想的话可别畏手畏脚的。<br>那些狭隘的障壁就由我来为你打破！"},
{index="1105",text="新宇宙，<br>提议进行友好“接触”。<br>也就是说——“请多指教”。"},
{index="1106",text="嗯，我是菱奇宝。<br>凭感觉（？）适当地努努力就好啦～<br>我是这么想的，还请多多关照～"},
{index="1107",text="来吧，踏上令人心潮澎湃的旅途！享受与伙伴<br>共舞的日子！Everyone！想要追寻梦想的<br>家伙们——全都登上我跳舞城的船吧！"},
{index="1108",text="我是鸣声雷动……<br>我的目标并非胜利，而是在其前方的“最强”。<br>就是这样……"},
{index="1115",text="无礼之徒，还不速速跪下——<br>黄金巨匠的称霸之道，<br>你只管俯首膜拜便是。"},
{index="1116",text="过程也好，道理也罢，都毫无意义。<br>胜者即是正义，不是吗？<br>我贵妇人定将让一切都屈服于我。"},
{index="9001",text="您好，我是特雷森学园的理事长秘书<br>骏川手纲。为了让各位过上<br>更舒适的学园生活，我会全力以赴♪"},
{index="9004",text="你好，我是桐生院葵，是特雷森学园的<br>新人训练员。我只是一个新手，<br>但是我会为优俊少女竭尽全力的！"},
{index="9005",text="我是技艺高超的针灸师（的徒弟），安心泽刺刺美。<br>只要让我扎一下就能提升力量！<br>哇哦，安～心☆"},
{index="9006",text="我是㭴本理子。<br>保证优俊少女身心健康是训练员的职责，<br>处理工作时当然要时刻紧绷神经。"},
{index="9008",text="我是明亮光晕，主要负责活动策划工作。<br>让我为舞台上闪闪发光的各位……<br>稍尽绵薄之力吧"},
{index="9040",text="我是达利阿拉伯。<br>优俊少女们各有各的个性，人人都是主角——<br>要好好培养她们啊，小羊羔！"},
{index="9041",text="我是高多芬柏布。<br>正因为有着各种各样的牵绊和存在，<br>优俊少女才会奔跑。我也会助你一臂之力的。"},
{index="9042",text="我的名字是拜耶尔土耳其。对优俊少女而言，<br>最重要的是强大。我会帮你锻炼出<br>足以将名字铭刻于大地之上的强大。"},
{index="9043",text="我是佐岳鸣！欧洲赛事的分析就交给我吧。<br>让我们一起实现称霸“凯旋门奖”<br>这一前无古人的梦想吧！"},
{index="9044",text="我是都留岐凉花。<br>平时主要从事各种内容的制作。<br>我会给各位带来最棒的感动。"}
}
p.text_data_144={
{index="1001",text="要加油嘞！<br>一心追梦、性格单纯的北海道少女"},
{index="1002",text="恬静的疾驰者。<br>目标是超越音速"},
{index="1003",text="无敌又可爱！<br>天真烂漫的活泼少女"},
{index="1004",text="爱开超跑的<br>昭和风大姐姐"},
{index="1005",text="无比称职的护花使者！<br>华丽的绅士少女"},
{index="1006",text="在乡下长大的、<br>朴素而帅气的梦想家"},
{index="1007",text="粗犷！奔放！　<br>情绪为谜的黄金电波少女"},
{index="1008",text="莽撞的青春！<br>略带痞帅气质的纯情少女"},
{index="1009",text="唯我独尊！<br>异常要强的傲娇女孩"},
{index="1010",text="出生于美国的<br>的热情女孩"},
{index="1011",text="清秀可爱。<br>从美国归来的大和抚子"},
{index="1012",text="单挑的话放马过来！<br>大家可靠的大姐头宿舍长"},
{index="1013",text="名门目白家的至宝。<br>优雅又专心的大小姐"},
{index="1014",text="北美的怪鸟！<br>活泼奇特的自由摔角"},
{index="1015",text="尊贵的歌剧之王。<br>她的笑声无比高亢！"},
{index="1016",text="用背影说话！<br>性格顽固的硬派孤狼"},
{index="1017",text="称霸全场的“皇帝”<br>她的权威不可动摇！"},
{index="1018",text="冷静无比的“女帝”<br>才貌兼备的事业型女性"},
{index="1019",text="最爱优俊少女！<br>无敌的万能宅女"},
{index="1020",text="我行我素，随心所欲<br>如浮云一般……"},
{index="1021",text="吐槽如闪电般犀利<br>秀出毅力吧，大阪少女"},
{index="1022",text="热爱创造回忆！<br>雍容华贵的豪门千金"},
{index="1023",text="热情的知性派。以逻辑思维<br>为武器努力拼搏！"},
{index="1024",text="老幺般性格甜美的女孩。<br>好想快点变成大人！"},
{index="1025",text="追逐着看不见的影子<br>充满神秘感的少女"},
{index="1026",text="绝对遵守命令！<br>改造人优俊少女"},
{index="1027",text="神清气爽适合运动！<br>晶莹的汗水也如此纯粹"},
{index="1028",text="大！大份！大……碗？<br>请享用buono♪"},
{index="1029",text="目标是成为城市少女！<br>来自乡下的努力家"},
{index="1030",text="不幸体质？<br>顽强求生的不幸少女"},
{index="1031",text="元气满满！<br>体贴家族的打工能手"},
{index="1032",text="禁忌般的疯狂科学家。<br>肉体研究即是全部！"},
{index="1033",text="背负着决心。<br>保持孤高的一等星"},
{index="1034",text="你说啥呢！<br>电光石火的江户人（自称）"},
{index="1035",text="尽情欢笑尽情哭泣！<br>满怀真诚的直率少女"},
{index="1036",text="跟着逻辑走吧！<br>异乎寻常的天才女孩"},
{index="1037",text="一切都按计划进行。<br>谨慎耿直的德国少女"},
{index="1038",text="可爱的闪光冲刺！<br>要多多爱我哦♪"},
{index="1039",text="目标是成为公主！<br>豪爽活泼的优俊少女"},
{index="1040",text="性格直率的<br>高品质辣妹"},
{index="1041",text="大暴走的班长。<br>时刻都在前进！"},
{index="1042",text="挑战世界！<br>能将不可能之事都变成珍珠的大姐姐"},
{index="1043",text="最爱恶作剧！<br>不理我就咬你哦！"},
{index="1044",text="单纯又任性的孩子！<br>绝对要成为魔女！"},
{index="1045",text="用沉稳母性治愈他人的<br>温柔大姐姐"},
{index="1046",text="最擅长与粉丝互动！<br>未来的顶级优俊偶像"},
{index="1047",text="梦想是书写英雄传说。<br>想象力丰富的爱书人"},
{index="1048",text="土气只是玩笑（乔丹）！<br>紧跟流行的辣妹☆"},
{index="1049",text="孤注一掷！<br>进攻到最后一秒的狂放博弈者"},
{index="1050",text="冷酷&淡漠！<br>以娇小的身躯夺取胜利"},
{index="1051",text="花朵绽放般的笑容♪<br>善解人意的优俊少女"},
{index="1052",text="即使连败也不会气馁！<br>百折不挠的女孩"},
{index="1053",text="只求认真对决！<br>热血·纪律委员长！"},
{index="1054",text="正义的火焰熊熊燃烧！<br>热血英雄，参见！"},
{index="1055",text="Marvelous！<br>用活力和无敌改变世界！"},
{index="1056",text="福星降临吧！<br>最爱占卜的快乐祈福少女"},
{index="1057",text="不被任何事所束缚！<br>纯真无邪的开朗优俊少女"},
{index="1058",text="希望能变得积极乐观！<br>消极的努力家"},
{index="1059",text="想要改变！怀揣着过往<br>伤痛而奔跑的大小姐"},
{index="1060",text="“拒绝被寄予期待？”的<br>冷酷少女"},
{index="1061",text="心高气傲的大小姐。<br>她的自尊心比天还高！"},
{index="1062",text="备受宠爱的明日之星。<br>今天一定要大获全胜！"},
{index="1063",text="彻底管理主义。<br>刚柔并济的干练优俊少女"},
{index="1064",text="活得坦然一点吧。<br>可靠的乐观辣妹"},
{index="1065",text="躁起来笑起来尽情嗨起来☆<br>每天都是派对人！"},
{index="1066",text="开足涡轮！<br>不知极限的暴走优俊少女！"},
{index="1067",text="内心强度堪称钻石级！<br>挑战厄运的大小姐"},
{index="1068",text="照亮大家的心！<br>爽朗快活的庆典少女！"},
{index="1069",text="追寻心中的憧憬！<br>直率努力的优俊少女"},
{index="1070",text="要成为世界上最闪耀的星星！<br>具有领袖魅力的野心家优俊少女"},
{index="1071",text="即使转瞬即逝也要全力绽放光芒。<br>双腿如玻璃般脆弱的大小姐"},
{index="1072",text="以武为礼，全力奔跑。<br>粗野的优俊少女"},
{index="1073",text="梦想是三冠！！永远全力以赴！！<br>经常会超出极限？！"},
{index="1074",text="意志坚定，慢慢悠悠！<br>悠闲的大小姐"},
{index="1076",text="平静而坚韧。<br>越冬绽放的樱花"},
{index="1077",text="开朗的完美优等生！<br>却有着配角气质……？"},
{index="1078",text="热爱自然的微风优俊少女。<br>但其灵魂却宛如烈风"},
{index="1082",text="闪耀是磨砺出来的！<br>璀璨的时尚达人"},
{index="1083",text="生于海外、<br>沉默寡言的任务执行者"},
{index="1084",text="为这美学沉醉吧！<br>难以驾驭的唯美派破坏神"},
{index="1085",text="胜利乃是必然。<br>来自华丽一族的优俊少女"},
{index="1086",text="将至高无上的爱献给比赛……<br>绝世独立、绽放于顶点的魔性之花"},
{index="1087",text="目标是成为吉祥物。<br>带着些许缥缈感的奇妙优俊少女"},
{index="1088",text="草地上的奇术师！<br>可靠的精英大姐姐"},
{index="1089",text="内向的心中怀揣着野心。<br>目标是成为伟大的优俊少女"},
{index="1090",text="目标是与自己相称的“女王”宝座。<br>争强好胜的名人风范优俊少女"},
{index="1091",text="天生的撒娇高手，<br>梦想是跨越遥远的大海"},
{index="1093",text="将奇迹作为感谢的证明。<br>温柔沉静的优俊少女"},
{index="1094",text="目标是成为最强，疾驰于比赛之路！<br>纯真的领袖型不良少女"},
{index="1098",text="Rickey☆Lucky☆<br>爱为他人操心的风水优俊少女☆"},
{index="1099",text="背负着苫小牧之名奔跑的<br>现实主义地方偶像"},
{index="1100",text="悠哉悠哉，耐心十足。<br>永不言弃、百折不挠的优俊少女"},
{index="1102",text="比赛就是合奏！<br>热爱音乐的艺术家优俊少女"},
{index="1103",text="创造传说吧！<br>以独特的视角剑指最强"},
{index="1104",text="目标是成为优俊少女界的王牌！<br>为远大理想一往无前的活力少女"},
{index="1105",text="有点不可思议？非常不可思议？<br>宇宙级优俊少女"},
{index="1106",text="悠闲自在的优俊少女。<br>今天也普普通通地和平时一样"},
{index="1107",text="伙伴、梦想与金钱全都要！<br>为浪漫而活的优俊少女"},
{index="1108",text="体内流淌着最强之血。<br>名门家族的结晶"},
{index="1115",text="天上天下唯我独尊。<br>自称草地之王的暴君"},
{index="1116",text="刚毅贵妇。<br>唯有强而有力地傲然绽放！"},
{index="2001",text="标准的大家闺秀型优俊少女。<br>幸福往往是大器晚成的！"},
{index="9001",text="笑容甜美的特雷森<br>学园理事长秘书"},
{index="9004",text="无论何时都一心一意！<br>热情洋溢的训练员"},
{index="9005",text="全世界都“针”挚期待？<br>超级天才（？？）针灸师"},
{index="9006",text="来自URA，<br>严厉却温柔的能干女性"},
{index="9008",text="目标是创造大家都能闪耀的舞台！<br>心意相连的活动制作人"},
{index="9040",text="开朗而贤明、<br>重视个性的指导者"},
{index="9041",text="散发着包容一切的温柔气息、<br>举止优雅的老师"},
{index="9042",text="军人气质的严厉背后，<br>是对优俊少女深沉的爱"},
{index="9043",text="不断挑战世界<br>追逐梦想的领导者"},
{index="9044",text="致力于打造最棒娱乐的<br>实力派制作人"}
}

return p